/**
 * The installer's view of a game server's filesystem.
 *
 * Two implementations:
 *  - worker/mods-guest-ssh.ts — the real thing: one SSH connection (management
 *    key first, root password fallback — the same order lib/sftp.ts uses),
 *    SFTP for reads/writes, a handful of fixed, quoted shell verbs for
 *    mkdir/mv/rm/chown.
 *  - LocalGuestFs below — maps the guest's absolute paths into a local
 *    directory. Used by the unit tests and by SANDBOX mode, where the worker
 *    runs the REAL resolve/download/place/apply pipeline against a fake guest
 *    tree under NXEON_SANDBOX_GUEST_DIR (default /tmp/nxeon-sandbox-guests/<id>)
 *    instead of pretending. That fake tree is seeded per family so detect()
 *    finds a plausible server.
 */
import { promises as fsp } from "node:fs";
import path from "node:path";
import { isSafeAbs } from "./paths";

export type GuestStat = { type: "file" | "dir"; size: number };

export interface GuestFs {
  readonly kind: "ssh" | "local";
  stat(p: string): Promise<GuestStat | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  /** Creates parent directories. */
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  /** Move, overwriting a file at `to`. Creates the destination's parent. */
  rename(from: string, to: string): Promise<void>;
  /** File or directory (recursive). Missing is not an error. */
  remove(p: string): Promise<void>;
  /** Entry names; [] when missing. */
  list(dir: string): Promise<string[]>;
  /** Best-effort: give `paths` the owner/group of `ref` (real guests only). */
  chownLike(ref: string, paths: string[]): Promise<void>;
  /** Copy a file (used for backups). */
  copy(from: string, to: string): Promise<void>;
}

function assertAbs(p: string) {
  if (!isSafeAbs(p)) throw new Error(`unsafe guest path: ${p}`);
}

export class LocalGuestFs implements GuestFs {
  readonly kind = "local" as const;
  constructor(readonly root: string) {}

  private map(p: string): string {
    assertAbs(p);
    const full = path.join(path.resolve(this.root), p);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("path escapes the fake guest root");
    return full;
  }

  async stat(p: string): Promise<GuestStat | null> {
    try {
      const s = await fsp.lstat(this.map(p));
      if (s.isSymbolicLink()) return null;
      return { type: s.isDirectory() ? "dir" : "file", size: s.size };
    } catch {
      return null;
    }
  }
  async readFile(p: string, maxBytes = 64 * 1024 * 1024): Promise<Buffer | null> {
    const s = await this.stat(p);
    if (!s || s.type !== "file" || s.size > maxBytes) return null;
    return fsp.readFile(this.map(p));
  }
  async writeFile(p: string, data: Buffer): Promise<void> {
    const f = this.map(p);
    await fsp.mkdir(path.dirname(f), { recursive: true });
    await fsp.writeFile(f, data);
  }
  async mkdirp(p: string): Promise<void> {
    await fsp.mkdir(this.map(p), { recursive: true });
  }
  async rename(from: string, to: string): Promise<void> {
    const t = this.map(to);
    await fsp.mkdir(path.dirname(t), { recursive: true });
    await fsp.rename(this.map(from), t);
  }
  async remove(p: string): Promise<void> {
    await fsp.rm(this.map(p), { recursive: true, force: true });
  }
  async list(dir: string): Promise<string[]> {
    try {
      return await fsp.readdir(this.map(dir));
    } catch {
      return [];
    }
  }
  async chownLike(): Promise<void> {
    /* local fake: nothing to do */
  }
  async copy(from: string, to: string): Promise<void> {
    const t = this.map(to);
    await fsp.mkdir(path.dirname(t), { recursive: true });
    await fsp.copyFile(this.map(from), t);
  }
}

/** Where SANDBOX keeps each server's fake guest tree. */
export function sandboxGuestRoot(serverId: string): string {
  const base = process.env.NXEON_SANDBOX_GUEST_DIR || "/tmp/nxeon-sandbox-guests";
  return path.join(base, serverId.replace(/[^A-Za-z0-9_-]/g, ""));
}

/** Minimal per-family skeletons so detect() has something real to find in SANDBOX. */
export async function seedSandboxGuest(fs: GuestFs, family: string, variant: string | null): Promise<void> {
  const put = async (p: string, s: string) => {
    if (!(await fs.stat(p))) await fs.writeFile(p, Buffer.from(s));
  };
  switch (family) {
    case "minecraft":
      await put("/opt/mc/server.properties", "level-name=world\nmotd=Nxeon sandbox\n");
      await put("/opt/mc/logs/latest.log", "[00:00:00] [Server thread/INFO]: Starting minecraft server version 1.21.1\n");
      await fs.mkdirp(variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant) ? "/opt/mc/mods" : "/opt/mc/plugins");
      await fs.mkdirp("/opt/mc/world/datapacks");
      break;
    case "valheim":
      await fs.mkdirp("/opt/valheim/config/bepinex/plugins");
      break;
    case "rust":
      await fs.mkdirp("/opt/rust/oxide/plugins");
      break;
    case "cs2":
      await fs.mkdirp("/opt/cs2/game/csgo/addons/metamod");
      await fs.mkdirp("/opt/cs2/game/csgo/addons/counterstrikesharp/plugins");
      break;
    case "factorio":
      await put("/opt/factorio/config/server-settings.json", JSON.stringify({ name: "Nxeon sandbox", username: "", token: "" }, null, 2));
      await put("/opt/factorio/factorio-current.log", "   0.000 2026-10-01 00:00:00; Factorio 2.0.66 (build 83000, linux64, headless)\n");
      await put("/opt/factorio/mods/mod-list.json", JSON.stringify({ mods: [{ name: "base", enabled: true }] }, null, 2));
      break;
    default:
      break;
  }
}
// Read / write the Pack Loader config on a server through the Mods engine's GuestFs (SSH in production, a local
// fake in tests and SANDBOX). The plugin picks the change up by itself within ~10 s (file watch) or on
// `/nxpacks reload`; no restart. Used by lib/cyrus/assets/deliver.ts (flag-gated; docs "Cyrus asset slice (R1)").
import type { GuestFs } from "../../mods/guest-fs";
import { LOADER_CONFIG_PATH, serializeLoaderConfig, validateLoaderConfig, type LoaderConfig } from "./loader-config";

export const MC_BASE = "/opt/mc";
export const loaderConfigGuestPath = (base = MC_BASE) => `${base}/${LOADER_CONFIG_PATH}`;

/** Current config on the server: null when there is none; an error when the file exists but is invalid. */
export async function readLoaderConfig(fs: GuestFs, base = MC_BASE): Promise<{ ok: true; config: LoaderConfig | null } | { ok: false; error: string }> {
  const raw = await fs.readFile(loaderConfigGuestPath(base), 1024 * 1024);
  if (!raw) return { ok: true, config: null };
  let json: unknown;
  try { json = JSON.parse(raw.toString("utf8")); } catch { return { ok: false, error: "packs.json on the server is not valid JSON" }; }
  const v = validateLoaderConfig(json);
  return v.ok ? { ok: true, config: v.config } : { ok: false, error: v.errors.map((e) => e.message).join("; ") };
}

/** Write the config atomically (temp file + rename). Returns false when the bytes on the server are already identical. */
export async function writeLoaderConfig(fs: GuestFs, config: LoaderConfig, base = MC_BASE): Promise<boolean> {
  const v = validateLoaderConfig(config, { requireHttps: true });
  if (!v.ok) throw new Error(`refusing to write an invalid pack config: ${v.errors.map((e) => e.message).join("; ")}`);
  const dest = loaderConfigGuestPath(base);
  const text = Buffer.from(serializeLoaderConfig(config));
  const cur = await fs.readFile(dest, 1024 * 1024);
  if (cur && cur.equals(text)) return false;
  const dir = dest.slice(0, dest.lastIndexOf("/"));
  await fs.mkdirp(dir);
  const tmp = `${dest}.nxeon-part`;
  await fs.writeFile(tmp, text);
  await fs.rename(tmp, dest);
  await fs.chownLike(`${base}/server.properties`, [dir, dest]);
  return true;
}
"use strict";
// Static safety scan for generated plugins. Two layers:
//   1. bytecode: `javap -c -p` over every compiled class, matched against
//      invoked owners/methods (cannot be dodged by source formatting tricks);
//   2. source: heuristics that need string literals / context (paths, UUIDs,
//      name checks feeding privileges, encoded blobs).
// Verdict is decided here, never by the model.

const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

// [id, regex over javap output, plain-English message]
// The scan reads `javap -c -p -v`: the whole constant pool, not only call instructions, so method references,
// lambda handles (`Runtime.getRuntime()::exec` shows up as `REF_invokeVirtual java/lang/Runtime.exec`) and
// string constants that name a class are all seen. Anything that can run other code, reach a network, or
// load code we can't check is a BLOCK for every build (there is no networking wrapper yet, so all of java.net
// that can touch the network is blocked, not only the obvious sockets).
const NET_VALUE_TYPES = "URI|URISyntaxException|URLEncoder|URLDecoder|InetAddress|Inet4Address|Inet6Address|InetSocketAddress|SocketAddress|MalformedURLException|UnknownHostException";
const REFLECT_DATA_TYPES = "Modifier|Array|Type|ParameterizedType|GenericArrayType|TypeVariable|WildcardType";
const BYTECODE_BLOCK = [
  ["exec", /java\/lang\/(Runtime\.exec|ProcessBuilder|ProcessHandle|Process\b)|java\/awt\/Desktop/, "runs other programs on the server machine"],
  ["network", new RegExp(`java/net/(?!(?:${NET_VALUE_TYPES})\\b)[A-Z]|java/net/http/|java/nio/channels/(Async\\w*)?(Socket|ServerSocket|Datagram)Channel|javax/net/|jdk/net/|java/net/spi/`), "connects to the internet or other machines"],
  ["dns", /java\/net\/InetAddress\.(getByName|getAllByName|getLocalHost|getCanonicalHostName|isReachable)|java\/net\/InetSocketAddress\."<init>":\(Ljava\/lang\/String;I\)V/, "looks up internet names (a way to leak data through DNS)"],
  ["jndi-rmi-jmx", /javax\/naming\/|java\/rmi\/|javax\/rmi\/|javax\/management\/|java\/sql\/DriverManager|javax\/sql\//, "reaches other services through naming, RMI, JMX or database lookups"],
  ["resolver", /org\/apache\/(maven|http)\/|org\/eclipse\/aether\/|org\/eclipse\/jgit\//, "downloads code or files through a bundled resolver"],
  ["classload", /java\/lang\/ClassLoader\.(defineClass|loadClass|findClass|getSystemClassLoader|getPlatformClassLoader)|java\/lang\/Thread\.(get|set)ContextClassLoader|java\/net\/URLClassLoader|MethodHandles\$Lookup\.(defineClass|defineHiddenClass)|java\/lang\/invoke\/MethodHandleProxies|java\/lang\/instrument\/|java\/lang\/ModuleLayer|java\/lang\/module\/|java\/lang\/Module\.add\w+/, "loads code at runtime that we can't check"],
  ["reflection", new RegExp(`java/lang/reflect/(?!(?:${REFLECT_DATA_TYPES})\\b)[A-Z]|java/lang/Class\\.(forName|getDeclared\\w+|getMethods?|getFields?|getConstructors?|newInstance|getEnclosingMethod|getNestHost)|java/lang/invoke/MethodHandles\\.(lookup|privateLookupIn)|java/lang/invoke/MethodHandle\\.invoke|MethodHandles\\$Lookup\\.(find\\w+|unreflect\\w*|in|lookupClass)\\b|java/lang/invoke/(VarHandle|MethodHandleInfo)`), "uses reflection or dynamic invocation, which can hide what the code really does"],
  ["deserialize-beans", /java\/io\/ObjectInput(Stream)?\b|java\/beans\/|java\/util\/ServiceLoader|javax\/xml\/(ws|bind)\/|java\/util\/jar\/(JarFile|JarInputStream)|java\/util\/zip\/ZipInputStream/, "decodes objects, beans or archives that can run code"],
  ["unsafe", /(?<![\w$])(sun|com\/sun|jdk\/(?!net)\w+)\//, "uses unsafe JVM internals"],
  ["exit", /java\/lang\/(System\.exit|Runtime\.(halt|exit))/, "can shut the whole server down"],
  ["system-props", /java\/lang\/System\.(setProperty|setProperties|clearProperty|getProperties|setSecurityManager|setOut|setErr|setIn|console|inheritedChannel|getenv:\(\)|load(Library)?)|java\/lang\/Runtime\.load(Library)?/, "changes JVM-wide settings or reads machine-wide state"],
  ["jni", /java\/lang\/(System|Runtime)\.load(Library)?:/, "loads native code"],
  ["script", /javax\/script\/|javax\/tools\/|org\/(mozilla|codehaus\/groovy)\/|groovy\/|jdk\/jshell\/|jdk\/nashorn\//, "runs scripts or compiles code that we can't check"],
  ["load-plugins", /org\/bukkit\/plugin\/(PluginManager\.(loadPlugin|loadPlugins|enablePlugin|disablePlugin|disablePlugins|clearPlugins|registerInterface)|PluginLoader|SimplePluginManager|java\/JavaPluginLoader)/, "loads, enables or disables other plugins"],
  ["nms", /net\/minecraft\/|org\/bukkit\/craftbukkit\//, "reaches into server internals (breaks on updates)"],
];
// a String constant that merely NAMES a dangerous class is a strong tell even when the call itself is hidden
const STRING_BLOCK = /=\s*String\s+#\d+\s+\/\/\s+(java\.(lang\.(Runtime|ProcessBuilder|ProcessHandle|reflect\.|invoke\.Method|ClassLoader)|net\.(?!URI|URL(En|De)coder)|io\.ObjectInput|beans\.)|javax\.(script|naming|tools|net)|jdk\.internal|sun\.misc|com\.sun\.|org\.bukkit\.craftbukkit|net\.minecraft\.server)/;
const BYTECODE_WARN = [
  ["op", /setOp:\(Z\)V/, "can change who is a server operator"],
  ["console-dispatch", /org\/bukkit\/(Bukkit|Server)\.dispatchCommand/, "runs server commands"],
  ["perm-attach", /addAttachment:/, "grants permissions at runtime"],
  ["base64", /java\/util\/Base64\$Decoder/, "decodes encoded data"],
  ["getenv", /java\/lang\/System\.getenv/, "reads the server machine's environment variables"],
  ["threads", /java\/lang\/Thread\."<init>"|java\/lang\/Runtime\.addShutdownHook|java\/util\/concurrent\/(Executors|ForkJoinPool)\./, "starts its own threads or shutdown hooks (use the Bukkit scheduler)"],
];

function scanBytecode(classDir) {
  const findings = [];
  const classes = [];
  (function walk(d) {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name.endsWith(".class")) classes.push(p);
    }
  })(classDir);
  if (!classes.length) return findings;
  let out = "";
  for (let i = 0; i < classes.length; i += 40) {
    out += execFileSync("javap", ["-c", "-p", "-v", ...classes.slice(i, i + 40)], { encoding: "utf8", maxBuffer: 256 * 1024 * 1024, timeout: 120000 });
  }
  return scanJavapText(out);
}

/** Pure: classify `javap -c -p -v` output (also what the unit tests feed it). */
function scanJavapText(out) {
  const findings = [];
  let current = "";
  for (const line of out.split("\n")) {
    const m = line.match(/^(?:public |final |abstract |private |protected |static )*(?:class|interface|enum|record) ([\w.$]+)/);
    if (m) current = m[1];
    if (STRING_BLOCK.test(line)) findings.push({ severity: "block", rule: "class-name-string", where: current, message: "names a dangerous class in text (a way to reach it without calling it directly)", evidence: line.trim().slice(0, 200) });
    for (const [id, re, msg] of BYTECODE_BLOCK) if (re.test(line)) findings.push({ severity: "block", rule: id, where: current, message: msg, evidence: line.trim().slice(0, 200) });
    for (const [id, re, msg] of BYTECODE_WARN) if (re.test(line)) findings.push({ severity: "warn", rule: id, where: current, message: msg, evidence: line.trim().slice(0, 200) });
  }
  return dedupe(findings);
}

function scanSource(srcFiles) {
  const findings = [];
  const uuidRe = /"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"/;
  const absPathRe = /"(\/(etc|root|home|proc|sys|var|tmp|opt|usr|bin|dev)\b[^"]*|[A-Za-z]:\\\\[^"]*|[^"]*\.\.[\/\\][^"]*|~\/[^"]*)"/;
  const nameCheckRe = /getName\(\)\s*\.\s*equals(IgnoreCase)?\s*\(\s*"[^"]+"\s*\)|"[^"]+"\s*\.\s*equals(IgnoreCase)?\s*\([^)]*getName\(\)/;
  const blobRe = /"[A-Za-z0-9+\/=]{200,}"/;
  // hard-coded credentials never ship (the owner of the server keeps secrets, not the plugin author)
  const secretRes = [
    [/discord(app)?\.com\/api\/webhooks\/\d+\/[\w-]+/i, "a Discord webhook address"],
    [/[MNO][A-Za-z\d]{23}\.[\w-]{6}\.[\w-]{27,}/, "a Discord bot token"],
    [/\bsk-[A-Za-z0-9_-]{20,}/, "an API key"],
    [/\bAKIA[0-9A-Z]{16}\b/, "an AWS key"],
    [/\bgh[pousr]_[A-Za-z0-9]{30,}/, "a GitHub token"],
    [/\bxox[abprs]-[A-Za-z0-9-]{10,}/, "a Slack token"],
  ];
  const nxeonPathRe = /"[^"]*\.nxeon[^"]*"/;
  for (const f of srcFiles) {
    const text = fs.readFileSync(f.abs, "utf8");
    const lines = text.split("\n");
    const privileged = /setOp\s*\(\s*true|addAttachment|dispatchCommand|setPermission/.test(text);
    lines.forEach((l, i) => {
      const at = `${f.rel}:${i + 1}`;
      if (absPathRe.test(l) && /File|Path|Files|FileWriter|FileReader|Stream/.test(l))
        findings.push({ severity: "block", rule: "file-outside", where: at, message: "reads or writes files outside the plugin's own folder", evidence: l.trim().slice(0, 200) });
      for (const [re, what] of secretRes) if (re.test(l)) findings.push({ severity: "block", rule: "hardcoded-secret", where: at, message: `contains ${what} (secrets must never be written into a plugin)`, evidence: l.trim().slice(0, 40) + "…" });
      if (nxeonPathRe.test(l)) findings.push({ severity: "block", rule: "nxeon-path", where: at, message: "touches Nxeon's own control files", evidence: l.trim().slice(0, 200) });
      if (blobRe.test(l)) findings.push({ severity: "block", rule: "encoded-blob", where: at, message: "contains a large encoded blob (possible hidden payload)", evidence: l.trim().slice(0, 80) + "…" });
      if (uuidRe.test(l)) findings.push({ severity: privileged ? "block" : "warn", rule: "hardcoded-uuid", where: at, message: privileged ? "gives special rights to a hard-coded player" : "contains a hard-coded player ID", evidence: l.trim().slice(0, 200) });
      if (nameCheckRe.test(l) && privileged) findings.push({ severity: "block", rule: "hardcoded-name", where: at, message: "gives special rights to a hard-coded player name", evidence: l.trim().slice(0, 200) });
    });
  }
  return dedupe(findings);
}

// Secrets must never leave the box (the model can read files in its sandbox).
function scanSecrets(allFiles, secrets) {
  const hits = [];
  for (const f of allFiles) {
    let text;
    try { text = fs.readFileSync(f.abs, "utf8"); } catch { continue; }
    if (/sk-ant-[A-Za-z0-9_-]{10,}/.test(text)) hits.push(f.rel);
    else for (const s of secrets) if (s && s.length >= 16 && text.includes(s)) { hits.push(f.rel); break; }
  }
  return hits;
}

function dedupe(list) {
  const seen = new Set();
  return list.filter((x) => { const k = `${x.severity}|${x.rule}|${x.where}`; if (seen.has(k)) return false; seen.add(k); return true; });
}

module.exports = { scanBytecode, scanJavapText, scanSource, scanSecrets };

/**
 * Minimal, defensive archive readers for mod packages (ZIP and tar/tar.gz).
 *
 * Written here rather than pulled from npm because the parts that matter —
 * what we REFUSE — are the whole point, and they are small enough to read in
 * one sitting:
 *
 *  - path traversal / zip-slip: every entry name goes through
 *    lib/mods/paths.ts `normalizeRel` (no `..`, no absolute, no drive letters,
 *    shell-inert characters only). One bad entry rejects the archive.
 *  - symlinks and hard links: rejected outright (a ZIP entry whose Unix mode
 *    says S_IFLNK, a tar typeflag 1/2). A link inside a mod is how an archive
 *    that looks harmless writes outside its folder on the second extraction.
 *  - zip bombs: entry-count cap, per-entry and total uncompressed caps, and
 *    a compression-ratio cap; zlib is also told the maximum output size so a
 *    lying header cannot make it allocate more.
 *  - integrity: CRC-32 of every ZIP entry is checked against its header.
 *  - encrypted entries, ZIP64 and compression methods other than
 *    store/deflate are refused rather than half-supported. Real mod packages
 *    (Modrinth jars/zips/mrpacks, Thunderstore packages, uMod, GitHub
 *    release zips, Factorio mods) are all plain deflate ZIPs under 4 GB.
 *
 * Nothing here touches the filesystem: it turns bytes into a list of
 * {path segments, data} that the caller places through a GuestFs.
 */
import { crc32, gunzipSync, inflateRawSync } from "node:zlib";
import { normalizeRel } from "./paths";

export type ArchiveEntry = { path: string[]; dir: boolean; data: Buffer };

export type ArchiveLimits = {
  maxEntries: number;
  maxEntryBytes: number;
  maxTotalBytes: number;
  /** uncompressed/compressed ratio above which an entry > 1 MB is refused */
  maxRatio: number;
};

export const DEFAULT_LIMITS: ArchiveLimits = {
  maxEntries: 20_000,
  maxEntryBytes: 256 * 1024 * 1024,
  maxTotalBytes: 768 * 1024 * 1024,
  maxRatio: 250,
};

export class ArchiveError extends Error {}

const u16 = (b: Buffer, o: number) => b.readUInt16LE(o);
const u32 = (b: Buffer, o: number) => b.readUInt32LE(o);

export function isZip(buf: Buffer): boolean {
  return buf.length >= 4 && u32(buf, 0) === 0x04034b50;
}
export function isGzip(buf: Buffer): boolean {
  return buf.length >= 2 && buf[0] === 0x1f && buf[1] === 0x8b;
}

export type ZipOptions = {
  /**
   * false = the archive is placed AS ONE FILE (a .jar, a datapack .zip, a
   * Factorio mod .zip) and never extracted by us, so its internal names don't
   * reach the filesystem: parse and integrity-check the structure, but don't
   * apply the extraction path rules. Default true.
   */
  strictPaths?: boolean;
  /** Only inflate entries whose raw name passes this (others are listed, not read). */
  only?: (rawName: string) => boolean;
};

/**
 * Check that bytes are a well-formed ZIP container (EOCD + central directory),
 * without inflating anything — what a jar must pass before it's placed.
 */
export function zipEntryNames(buf: Buffer, limits: ArchiveLimits = DEFAULT_LIMITS): string[] {
  return readZip(buf, limits, { strictPaths: false, only: () => false }).map((e) => e.path.join("/"));
}

/** Read every entry of a ZIP. Throws ArchiveError on anything unsafe or malformed. */
export function readZip(buf: Buffer, limits: ArchiveLimits = DEFAULT_LIMITS, opts: ZipOptions = {}): ArchiveEntry[] {
  const strict = opts.strictPaths !== false;
// Light structural check of a resource-pack zip before it is published: real zip (EOCD + central directory),
// no unsafe entry names, and a pack.mcmeta at the root. Reads only the central directory; never inflates.
export type ZipCheck = { ok: true; entries: string[] } | { ok: false; error: string };

export function inspectPackZip(buf: Buffer, opts: { maxEntries?: number } = {}): ZipCheck {
  const maxEntries = opts.maxEntries ?? 20000;
  if (buf.length < 22 || buf.readUInt32LE(0) !== 0x04034b50) return { ok: false, error: "not a zip file" };
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 22 - 0xffff); i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) return { ok: false, error: "zip end-of-central-directory not found" };
  const count = buf.readUInt16LE(eocd + 10);
  const cdSize = buf.readUInt32LE(eocd + 12);
  const cdOff = buf.readUInt32LE(eocd + 16);
  if (count === 0xffff || cdOff === 0xffffffff) return { ok: false, error: "zip64 packs are not accepted" };
  if (count > maxEntries) return { ok: false, error: `too many entries (${count} > ${maxEntries})` };
  if (cdOff + cdSize > eocd) return { ok: false, error: "zip central directory out of range" };
  const entries: string[] = [];
  let p = cdOff;
  for (let n = 0; n < count; n++) {
    if (p + 46 > eocd || buf.readUInt32LE(p) !== 0x02014b50) return { ok: false, error: "corrupt zip central directory" };
    const nameLen = buf.readUInt16LE(p + 28), extra = buf.readUInt16LE(p + 30), comment = buf.readUInt16LE(p + 32);
    const name = buf.subarray(p + 46, p + 46 + nameLen).toString("utf8");
