    await fs.copy(p, dest);
    out.set(p, dest);
  }
  if (await fs.stat(STATE_PATH)) await fs.copy(STATE_PATH, `${dir}/state.json`);
  await pruneBackups(fs);
  return out;
}

type Write = { pkg: ResolvedPackage; files: PlacedFile[]; prev: PkgState | null };

/**
 * Install (or update) a catalogue mod and its required dependencies.
 * Idempotent: running it again with nothing new upstream changes nothing.
 */
export async function installOrUpdate(
  installer: FamilyInstaller,
  mod: CatalogFacts,
  server: ServerFacts,
  deps: EngineDeps,
  mode: "install" | "update" = "install",
): Promise<OpResult> {
  const fs = deps.fs;
  const now = (deps.now ?? (() => new Date()))();
  try {
    await deps.progress?.("Checking your server", 5);
    const layout = await detectOrFail(installer, fs, server, mod);
    const state = await loadState(fs, server.family);
    const ctx: InstallerCtx = { server, layout, fetcher: deps.fetcher };

    await deps.progress?.(`Resolving ${mod.name} and its dependencies`, 15);
    const res = await installer.resolve(mod, ctx);
    if ("error" in res) return { ok: false, error: res.error };
    const pkgs = res.packages;
    const rootPkg = pkgs[pkgs.length - 1];
    if (!rootPkg || !rootPkg.root) return { ok: false, error: "Resolver returned no package for this mod." };

    // A disabled mod is enabled again, not reinstalled behind the customer's back.
    const prevRoot = state.roots[mod.id];
    if (prevRoot && state.packages[prevRoot.key]?.disabled && mode === "install") {
      return { ok: false, error: `${mod.name} is installed but disabled — enable it instead.` };
    }

    // ── declared incompatibilities, both directions ─────────────────────────
    const incoming = new Set(pkgs.map((p) => p.key));
    for (const p of pkgs) {
      for (const bad of p.incompatible) {
        const have = state.packages[bad.key];
        if (have && !have.disabled && !incoming.has(bad.key)) {
          return { ok: false, error: `${p.name} is incompatible with ${have.name}, which is installed — remove ${have.name} first.` };
        }
      }
    }
    for (const have of Object.values(state.packages)) {
      if (have.disabled) continue;
      const clash = have.incompatible.find((b) => incoming.has(b.key));
      if (clash) return { ok: false, error: `${have.name} (installed) declares it is incompatible with ${clash.name} — nothing was installed.` };
    }

    // ── download + place, nothing written yet ───────────────────────────────
    const writes: Write[] = [];
    const notes = [...res.notes];
    let total = 0;
    let i = 0;
    for (const pkg of pkgs) {
      i++;
      const prev = state.packages[pkg.key] ?? null;
      if (prev && prev.version === pkg.version && (await filesIntact(fs, prev))) continue; // already there — idempotent
      await deps.progress?.(`Downloading ${pkg.name} ${pkg.version}`, 15 + Math.round((60 * i) / pkgs.length));
      const dl = await download(pkg, deps);
      total += dl.bytes.length;
      if (total > MAX_OP_BYTES) return { ok: false, error: `This install would download more than ${MAX_OP_BYTES / 1048576} MB — too large for one click.` };
      const placed = await installer.place(pkg, dl.bytes, ctx);
      if ("error" in placed) return { ok: false, error: placed.error };
      if (placed.length === 0) return { ok: false, error: `${pkg.name} ${pkg.version} contains nothing this server can load.` };
      for (const f of placed) {
        if (!isWithin(layout.base, f.path)) return { ok: false, error: `${pkg.name} tried to write outside the game folder — refused.` };
      }
      if (dl.from === "mirror") notes.push(`${pkg.name} came from the NX Labs mirror (checksum verified).`);
      writes.push({ pkg, files: placed, prev });
    }

    const legacy = (installer.legacyPaths?.(mod, layout) ?? []).filter((p) => isWithin(layout.base, p));

    // ── conflicts against files we don't own ───────────────────────────────
    const overwrite: string[] = [];
    for (const w of writes) {
      const prevPaths = new Set(w.prev?.files.map((f) => f.path) ?? []);
      for (const f of w.files) {
        const other = ownerOf(state, f.path, w.pkg.key);
        if (other) {
          const rec = other.files.find((x) => x.path === f.path)!;
          if (rec.sha256 === sha256(f.data)) continue; // byte-identical shared file — fine
          return { ok: false, error: `${w.pkg.name} would overwrite ${f.path}, which belongs to ${other.name} — nothing was changed.` };
        }
        if (prevPaths.has(f.path) || legacy.includes(f.path)) { overwrite.push(f.path); continue; }
        const st = await fs.stat(f.path);
        if (!st) continue;
        if (st.type === "dir") return { ok: false, error: `${f.path} already exists as a folder — nothing was changed.` };
        if (f.overwrite === "backup") { overwrite.push(f.path); continue; }
        const cur = await fs.readFile(f.path);
        if (cur && sha256(cur) === sha256(f.data)) continue; // same file already there (installed by hand) — adopt it
        return {
          ok: false,
          error: `${f.path} already exists and wasn't installed by Nxeon (added by hand?). Remove or rename it in Files, then try again — nothing was changed.`,
        };
      }
    }

    // Files of the previous version that the new version no longer ships.
    const stale: string[] = [];
    for (const w of writes) {
      if (!w.prev) continue;
      const keep = new Set(w.files.map((f) => f.path));
      for (const f of w.prev.files) if (!keep.has(f.path) && !ownerOf(state, f.path, w.pkg.key)) stale.push(f.path);
    }

    // Nothing to do at all → idempotent success, no restart needed.
    const existingLegacy: string[] = [];
    for (const p of legacy) {
      // A "legacy" path the engine itself now owns (same filename) is not legacy.
      if (ownerOf(state, p) || writes.some((w) => w.files.some((f) => f.path === p))) continue;
      if (await fs.stat(p)) existingLegacy.push(p);
    }
    if (writes.length === 0 && existingLegacy.length === 0) {
      addRoots(state, pkgs, mod);
      await saveState(fs, state);
      return { ok: true, version: rootPkg.version, versionId: rootPkg.versionId ?? null, fileName: rootFileName(state, rootPkg.key), restartRequired: false, changed: [], notes: [...notes, `${mod.name} ${rootPkg.version} is already installed and up to date.`] };
    }

    // ── backup, then staged write ───────────────────────────────────────────
    await deps.progress?.("Backing up files that will change", 80);
    // Config the installer asked to keep a copy of (Cyrus: the plugin's own folder), backup only.
    const keep: string[] = [];
    for (const d of res.alsoBackupDirs ?? []) {
      if (!isWithin(layout.base, d)) continue;
      for (const f of (await fs.list(d)).slice(0, 40)) {
        const st = await fs.stat(`${d}/${f}`);
        if (st?.type === "file" && st.size <= 4 * 1024 * 1024) keep.push(`${d}/${f}`);
      }
    }
    const backups = await backup(fs, mod.slug, [...overwrite, ...stale, ...existingLegacy, ...keep], now);

    await deps.progress?.("Writing files to your server", 88);
    const written: string[] = [];
    const created: string[] = [];
    try {
      for (const w of writes) {
        for (const f of w.files) {
          const existed = !!(await fs.stat(f.path));
          const part = `${f.path}.nxeon-part`;
          await fs.writeFile(part, f.data);
          await fs.rename(part, f.path);
          written.push(f.path);
          if (!existed) created.push(f.path);
        }
      }
      for (const p of stale) await fs.remove(p);
      for (const w of writes) {
        if (!w.prev) continue;
        const keep = new Set(w.files.map((f) => f.path));
        await removeSyncedCopies(installer, fs, w.prev.files.filter((f) => stale.includes(f.path) && !keep.has(f.path)));
      }
      for (const p of existingLegacy) if (!written.includes(p)) await fs.remove(p);

      // State: record exactly what we wrote.
      for (const w of writes) {
        const prev = w.prev;
        state.packages[w.pkg.key] = {
          key: w.pkg.key,
          name: w.pkg.name,
          version: w.pkg.version,
          versionId: w.pkg.versionId ?? null,
          files: w.files.map((f) => ({ path: f.path, sha256: sha256(f.data), size: f.data.length })),
          roots: prev?.roots ?? [],
          requires: w.pkg.requires,
          incompatible: w.pkg.incompatible,
          disabled: false,
          installedAt: prev?.installedAt ?? now.toISOString(),
          updatedAt: now.toISOString(),
        };
      }
      addRoots(state, pkgs, mod);

      if (installer.configure) {
        const edits = await installer.configure(fs, layout, enabledList(state), allList(state));
        for (const e of edits) {
          if (!isWithin(layout.base, e.path)) continue;
          if (!backups.has(e.path) && (await fs.stat(e.path))) await backup(fs, `${mod.slug}-config`, [e.path], now);
          await fs.writeFile(`${e.path}.nxeon-part`, e.data);
          await fs.rename(`${e.path}.nxeon-part`, e.path);
        }
      }
      await saveState(fs, state);
    } catch (e) {
      // Roll back: new files out, overwritten files back from the backup.
      for (const p of created) await fs.remove(p).catch(() => {});
      for (const [orig, copy] of backups) await fs.copy(copy, orig).catch(() => {});
      for (const w of writes) for (const f of w.files) await fs.remove(`${f.path}.nxeon-part`).catch(() => {});
      const why = failure(e).error;
      return { ok: false, error: `Writing to your server failed and the change was rolled back: ${why}` };
    }
    await fs.chownLike(layout.base, [...new Set(written.map((p) => p.split("/").slice(0, -1).join("/")))].filter((d) => isWithin(layout.base, d)));

    const changed = writes.map((w) =>
      w.prev ? `updated ${w.pkg.name} ${w.prev.version} → ${w.pkg.version}` : `${w.pkg.root ? "installed" : "added dependency"} ${w.pkg.name} ${w.pkg.version}`,
    );
    if (existingLegacy.length) changed.push(`replaced ${existingLegacy.length} file(s) from the older Nxeon installer`);
    return { ok: true, version: rootPkg.version, versionId: rootPkg.versionId ?? null, fileName: rootFileName(state, rootPkg.key), restartRequired: installer.restartRequired, changed, notes };
  } catch (e) {
    return failure(e);
  }
}

/** Basename of the first file a package placed (what the mod-health check and the panel call its file). */

// Cyrus Test Flight (R0) types: the typed spec a caller writes, the resolved spec the node-2 runner receives,
// and the report it returns. The runner is services/modbuilder/tools/testflight/runner.js (plain Node on node-2).
// A check passes only if it actually ran; a skipped required check means the flight is NOT a success.

export const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "clean_stop", "no_leaks"] as const;
export type CheckId = (typeof CHECK_IDS)[number];
export type CheckStatus = "pass" | "fail" | "not_run";

/** A regex matched against each log line (JS syntax; flags limited to i/m/s/u). */
export type LogMatcher = { id: string; pattern: string; flags?: string };

/** A small text file in the server directory (e.g. a plugin's config). Path relative to the server root, under plugins/ only. */
export type ServerFile = { path: string; content: string };

export type RconCheck = {
  id?: string;
  /** Written (created or replaced) in the server dir right before this command is sent, e.g. to test a config reload. */
  writeFile?: ServerFile;
  /** Wait this long (ms, max 30000) before sending the command (after writeFile), e.g. for a file watcher. */
  waitMs?: number;
  /** One console command without the leading slash. stop/restart/op/deop/reload are reserved for the runner. */
  command: string;
  /** Every substring must appear in the reply (colour codes stripped). Empty = the command only has to answer. */
  expect?: string[];
  /** None of these may appear. */
  expectNot?: string[];
  /** Default true. An optional check is reported but does not fail the stage. */
  required?: boolean;
};

/** An artifact either on the caller's disk (uploaded by the invoker) or already on node-2 under the Test Flight root. */
export type ArtifactRef = { localPath: string; remotePath?: never; sha256?: string } | { remotePath: string; localPath?: never; sha256?: string };

export type TestFlightSpec = {
  /** Exact registry id, e.g. "26.2" or "1.21.11". The registry supplies the JDK and the pinned Paper server jar. */
  version: string;
  plugins?: ArtifactRef[];
  /** Datapacks go into world/datapacks before first boot; each one adds an automatic `datapack list enabled` check. */
  datapacks?: (ArtifactRef & { name: string })[];
  /** Written to server.properties only. No client connects, so the pack itself is NOT exercised (reported as such). */
  resourcePack?: { url: string; sha1?: string; id?: string; required?: boolean };
  /** Small text files placed before the first boot (max 16, 64 KB each, under plugins/). */
  files?: ServerFile[];
  rcon?: RconCheck[];
  /** Replace the runner's default startup-log matchers (omit to use the defaults). */
  logMatchers?: LogMatcher[];
  /** Extra ignore patterns, added to the runner's sandbox ignores. */
  logIgnore?: LogMatcher[];
  timeouts?: { bootSec?: number; rconSec?: number; stopSec?: number; totalSec?: number };
  /** xmxMb max 1024 (node-2 rule). rssCapMb is a watchdog: above it the server is killed and the run fails. */
  memory?: { xmxMb?: number; rssCapMb?: number };
  /** Extra stages to treat as required even if the spec would not make them required. */
  requireStages?: CheckId[];
  /** Keep the server dir on node-2 for debugging (default false). */
  keepDir?: boolean;
};

/** What the runner receives: registry pins resolved, artifact paths on node-2. */
export type ResolvedSpec = {
  schema: 1;
  runId: string;
  version: string;
  javaRelease: 21 | 25;
  paper: { build: number; sha256: string };
  plugins: { path: string; sha256?: string }[];
  datapacks: { path: string; name: string }[];
  resourcePack?: TestFlightSpec["resourcePack"];
  files?: ServerFile[];
  rcon: RconCheck[];
  logMatchers?: LogMatcher[];
  logIgnore?: LogMatcher[];
  timeouts: { bootSec: number; rconSec: number; stopSec: number; totalSec: number };
  memory: { xmxMb: number; rssCapMb: number };
  keepDir: boolean;
};

export type CheckResult = { id: CheckId; status: CheckStatus; required: boolean; evidence: string[]; durationMs: number };

export type ReportArtifact =
  | { kind: "plugin"; file: string; sha256: string; pluginName: string | null; apiVersion: string | null; descriptor: string | null }
  | { kind: "datapack"; name: string; sha256: string | null; directory: boolean }
  | { kind: "resourcePack"; url: string; sha1: string | null; exercised: false };

export type EngineMeta = {
  runner: string;
  runnerSha256: string;
  node: string;
  host: string;
  kernel: string;
  jdk: { release: number; version: string | null; dist: string; sha256: string };
  paper: { version: string; build: number; sha256: string; channel: string | null };
  isolation: { netns: string; uid: number; noNewPrivs: boolean; nice: number; activeProcessorCount: number };
};

/** Raw runner output. `status` says whether the runner itself completed; `overall` is its own verdict (recomputed by summarize). */
export type TestFlightReport = {
  schema: 1;
  runId: string | null;
  status: "completed" | "busy" | "error";
  version: string | null;
  javaRelease: number | null;
  startedAt: string;
  finishedAt: string | null;
  checks: CheckResult[];
  timings: Record<string, number>;
  bootMs: number | null;
  doneReportedSec: number | null;
  peakRssKb: number | null;
  artifacts: ReportArtifact[];
  engine: EngineMeta | null;
  notes: string[];
  overall: "passed" | "failed" | "incomplete";
};

export type Overall = "passed" | "failed" | "incomplete" | "busy" | "error";

export type TestFlightSummary = {
  version: string;
  overall: Overall;
  /** true only when overall === "passed". */
  success: boolean;
  passed: CheckId[];
  failed: CheckId[];
  /** Required checks that did not run (or "passed" without evidence): any entry here blocks success. */
  skippedRequired: CheckId[];
  notRunOptional: CheckId[];
  reasons: string[];
  bootMs: number | null;
  peakRssKb: number | null;
  runId: string | null;
};

export type MatrixSummary = { overall: Overall; success: boolean; versions: TestFlightSummary[] };
// Thin Test Flight invoker: push the runner + artifacts to node-2, run ONE flight, parse the report, summarise.
// Not wired into the live build path. All I/O goes through the injectable `Remote`, so tests use a fake.
// Server-only (node:child_process / node:fs).
import { spawn } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import type { TestFlightReport, TestFlightSpec, TestFlightSummary, ResolvedSpec } from "./types";
import { resolveSpec, validateSpec, TF_DEFAULT_ROOT } from "./spec";
import { summarize } from "./summary";

export type ExecResult = { code: number | null; stdout: string; stderr: string };
/** Runs a shell command line on the build host. `input` is piped to stdin. */
export type Remote = { exec: (command: string, opts?: { input?: Buffer; timeoutMs?: number }) => Promise<ExecResult> };

export const NODE2 = "root@178.63.94.114";
export const BUSY_EXIT = 75;

/** POSIX single-quote a word for a remote shell. */
export const shq = (s: string) => `'${String(s).replace(/'/g, `'\\''`)}'`;

/** Real transport: ssh with BatchMode (no prompts), hard local timeout (SIGKILL of the ssh child we spawned). */
export function sshRemote(host = NODE2): Remote {
  return {
    exec: (command, opts = {}) => new Promise((resolve) => {
      const child = spawn("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", host, command], { stdio: ["pipe", "pipe", "pipe"] });
      let stdout = "", stderr = "";
      child.stdout.on("data", (d) => (stdout += d));
      child.stderr.on("data", (d) => (stderr += d));
      const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
      child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
      child.stdin.on("error", () => {});
      child.stdin.end(opts.input ?? undefined);
    }),
  };
}

export type RunOptions = {
  remote?: Remote;
  root?: string;
  /** Directory holding runner.js + lib.js (default: the repo copy). */
  runnerDir?: string;
  runId?: string;
  readFile?: (p: string) => Buffer;
  /** Files of a local datapack directory, relative path -> absolute path. */
  listDir?: (dir: string) => { rel: string; abs: string }[];
};

export type RunResult = { report: TestFlightReport; summary: TestFlightSummary; resolved: ResolvedSpec; stderr: string };

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");

function walk(dir: string, rel = ""): { rel: string; abs: string }[] {
  const out: { rel: string; abs: string }[] = [];
  for (const e of readdirSync(path.join(dir, rel)).sort()) {
    const r = rel ? `${rel}/${e}` : e;
    if (statSync(path.join(dir, r)).isDirectory()) out.push(...walk(dir, r));
    else out.push({ rel: r, abs: path.join(dir, r) });
  }
  return out;
}

export function newRunId(version: string): string {
  return `tf-${version.replace(/[^0-9]+/g, "-")}-${Date.now().toString(36)}-${randomBytes(3).toString("hex")}`.toLowerCase();
}

/** Minimal POSIX ustar archive (regular files only) so one ssh call can carry every artifact. */
export function tarball(entries: { name: string; data: Buffer }[]): Buffer {
  const blocks: Buffer[] = [];
  for (const e of entries) {
    if (!e.name || e.name.startsWith("/") || e.name.split("/").includes("..") || Buffer.byteLength(e.name) > 99) throw new Error(`bad tar entry name ${e.name}`);
    const h = Buffer.alloc(512);
    h.write(e.name, 0, "utf8");
    h.write("0000644\0", 100); h.write("0000000\0", 108); h.write("0000000\0", 116);
    h.write(e.data.length.toString(8).padStart(11, "0") + "\0", 124);
    h.write("00000000000\0", 136);
    h.fill(" ", 148, 156);
    h.write("0", 156);
    h.write("ustar\0" + "00", 257);
    let sum = 0;
    for (const b of h) sum += b;
    h.write(sum.toString(8).padStart(6, "0") + "\0 ", 148);
    blocks.push(h, e.data, Buffer.alloc((512 - (e.data.length % 512)) % 512));
  }
  blocks.push(Buffer.alloc(1024));
  return Buffer.concat(blocks);
}

/** Push the runner if node-2's copy differs (content hash), so every flight runs the code in this repo. */
async function ensureRunner(remote: Remote, root: string, dir: string, read: (p: string) => Buffer) {
  const files = ["lib.js", "runner.js"];
  const want = files.map((f) => `${sha256(read(path.join(dir, f)))}  ${root}/runner/${f}`).join("\n") + "\n";
  const have = await remote.exec(`sha256sum ${files.map((f) => shq(`${root}/runner/${f}`)).join(" ")} 2>/dev/null || true`);
  if (have.stdout === want) return;
  const stage = `${root}/runner/.new-${randomBytes(4).toString("hex")}`;
  const tar = tarball(files.map((f) => ({ name: f, data: read(path.join(dir, f)) })));
  const r = await remote.exec(`mkdir -p ${shq(stage)} && tar --no-same-owner -xf - -C ${shq(stage)} && ${files.map((f) => `mv -f ${shq(`${stage}/${f}`)} ${shq(`${root}/runner/${f}`)}`).join(" && ")} && rmdir ${shq(stage)}`, { input: tar });
  if (r.code !== 0) throw new Error(`could not install the runner on the build host: ${r.stderr.slice(0, 300)}`);
}

/** Run one Test Flight. Throws only for an invalid spec or a transport failure; every server outcome is in the report. */
export async function runTestFlight(spec: TestFlightSpec, opts: RunOptions = {}): Promise<RunResult> {
  const v = validateSpec(spec);
  if (!v.ok) throw new Error(`invalid Test Flight spec: ${v.errors.join("; ")}`);
  const remote = opts.remote ?? sshRemote();
  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const read = opts.readFile ?? ((p: string) => readFileSync(p));
  const list = opts.listDir ?? ((d: string) => walk(d));
  const runId = opts.runId ?? newRunId(spec.version);
  const resolved = resolveSpec(spec, { runId, root });
  const inbox = `${root}/inbox/${runId}`;
  const rel = (p: string) => p.slice(inbox.length + 1);

  // Everything local goes into one tar: plugins, datapacks, the resolved spec.
  const entries: { name: string; data: Buffer }[] = [];
  for (const [i, p] of (spec.plugins ?? []).entries()) {
    if (!p.localPath) continue;
    const buf = read(p.localPath);
    if (p.sha256 && sha256(buf) !== p.sha256) throw new Error(`${p.localPath}: sha256 does not match the spec`);
    resolved.plugins[i].sha256 = sha256(buf); // the runner re-hashes on node-2 and refuses a mismatch
    entries.push({ name: rel(resolved.plugins[i].path), data: buf });
  }
  for (const [i, d] of (spec.datapacks ?? []).entries()) {
    if (!d.localPath) continue;
    if (/\.zip$/.test(d.localPath)) {
      resolved.datapacks[i].path += ".zip";
      entries.push({ name: rel(resolved.datapacks[i].path), data: read(d.localPath) });
      continue;
    }
    for (const f of list(d.localPath)) entries.push({ name: `${rel(resolved.datapacks[i].path)}/${f.rel}`, data: read(f.abs) });
  }
  entries.push({ name: "spec.json", data: Buffer.from(JSON.stringify(resolved)) });

  await ensureRunner(remote, root, opts.runnerDir ?? path.join(process.cwd(), "services/modbuilder/tools/testflight"), read);
  // One call: unpack, run (outer hard timeout on node-2 on top of the runner's own), always remove the inbox.
  const hard = resolved.timeouts.totalSec + 420;
  const cmd = [
    `mkdir -p ${shq(inbox)} && tar --no-same-owner -xf - -C ${shq(inbox)} || exit 3`,
    `TF_ROOT=${shq(root)} timeout -s KILL ${hard} node ${shq(`${root}/runner/runner.js`)} run ${shq(`${inbox}/spec.json`)}`,
    `rc=$?; rm -rf -- ${shq(inbox)}; exit $rc`,
  ].join("\n");
  const r = await remote.exec(cmd, { input: tarball(entries), timeoutMs: (hard + 60) * 1000 });
  const line = r.stdout.trim().split("\n").filter(Boolean).pop() ?? "";
  let report: TestFlightReport;
  try { report = JSON.parse(line); } catch { throw new Error(`runner gave no report (exit ${r.code}): ${(r.stderr || r.stdout).slice(-400)}`); }
  if ((report as unknown as { error?: string }).error) throw new Error(`runner refused the spec: ${JSON.stringify(report).slice(0, 400)}`);
  if (r.code === BUSY_EXIT && report.status !== "busy") report.status = "busy";
  return { report, summary: summarize(spec, report), resolved, stderr: r.stderr };
}

// REAL Test Flight runs of the Cyrus R1 asset slice on node-2 (not part of the unit suite: boots real Paper servers).
//   tsx test/cyrus-assets-real.ts [v12111|v262|all] [--out file.json]
// Pipeline per version: golden texture specs -> the portal sync (lib/cyrus/assets/sync.ts: re-validate, render,
// quality, buildPack through the registry, publish to a LocalDiskStore with an https public base, Pack Loader entry)
// -> packs.json exactly as deliverBuildPack writes it (applyPackChange + serializeLoaderConfig) -> a flight with the
// Nxeon Pack Loader fixture jar + the TfItemModel fixture jar (does what generated mods do: setItemModel with the
// project's nx_ key). 26.2 is a preview version, so the production sync refuses its pack (no allowPreview); for the
// flight the 26.2 pack is built with buildPack(..., allowPreview: true) HERE ONLY, and that is reported.
// SERVER SIDE ONLY: no Minecraft client connects, so the pack download, the accept prompt and the textures actually
// showing in a client are NOT verified.
// Jars on node-2: /tank/nxeon-build/tmp/testflight/inbox/fx/{NxeonPackLoader-0.1.0.jar,TfItemModel-1.0.0.jar}
// (TfItemModel built by services/modbuilder/tools/testflight/fixtures/build.sh, see docs "Cyrus asset slice (R1)").
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { runTestFlight, type RunResult } from "../lib/cyrus/testflight/client";
import { describe } from "../lib/cyrus/testflight/summary";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";
import { applyPackChange, LOADER_CONFIG_PATH, serializeLoaderConfig } from "../lib/cyrus/packhost/loader-config";
import { LocalDiskStore } from "../lib/cyrus/packhost/local";
import { publishPack } from "../lib/cyrus/packhost/publish";
import { buildPack } from "../lib/cyrus/textures/pack";
import { checkSpec } from "../lib/cyrus/textures/dsl";
import { HEALTH_POTION } from "../lib/cyrus/textures/sample-items";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";

const FX = "/tank/nxeon-build/tmp/testflight/inbox/fx";
const NS = "nx_r1fl1ght";
const BASE = "https://packs.example.invalid";
const ruby = JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
const specs = [ruby, HEALTH_POTION].map((s) => { const c = checkSpec(s); if (!c.ok) throw new Error(c.error); return c.spec; });

async function packFor(version: string, store: LocalDiskStore) {
  if (version === "26.2") {
    const b = buildPack({ namespace: NS, description: "TfItemModel: custom textures by Cyrus", mcVersion: version, textures: specs, allowPreview: true });
    if (!b.ok) throw new Error(b.error);
    const pub = await publishPack(store, b.pack.zip, { maxBytes: 10 * 1024 * 1024 });
    if (!pub.ok) throw new Error(pub.error);
    return { path: "buildPack(allowPreview, test only)", sha1: pub.sha1, url: pub.url, format: b.pack.packFormat, bytes: b.pack.bytes, prompt: "TfItemModel uses custom item textures. Accept the pack to see them.", required: false };
  }
  const projects = new Map([[`mbflight${version}`, { id: "cp" + "f".repeat(20), namespace: NS, userId: "flight" }]]);
  const revs: { id: string; modBuildId: string | null }[] = [];
  const deps: AssetSyncDeps = {
    selectStore: () => ({ ok: true, store, maxBytes: 10 * 1024 * 1024 }),
    projectForRootBuild: async (r) => projects.get(r) ?? null,
    createProject: async () => { throw new Error("unexpected"); },
    findRevisionForBuild: async (_p, m) => revs.find((r) => r.modBuildId === m) ?? null,
    headRevisionId: async () => revs.at(-1)?.id ?? null,
    addRevision: async (_p, i) => { const r = { id: `rev${revs.length + 1}`, modBuildId: i.modBuildId ?? null }; revs.push(r); return r; },
    recordAsset: async () => null,
  };
  const a = await syncBuildAssets(
    { id: `mbflight${version}`, userId: "flight", rootBuildId: `mbflight${version}`, mcVersion: version, pluginName: "TfItemModel", jarName: null, jarSha256: null },
    { namespace: NS, promptVersion: null, qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [], textures: specs.map((s) => ({ name: s.name, path: `assets/textures/${s.name}.json`, sha256: "", spec: s, quality: null })) },
    deps,
  );
  if (!a || a.status !== "ready" || !a.loader || !a.pack) throw new Error(`sync did not produce a hosted pack: ${JSON.stringify(a)}`);
  return { path: "syncBuildAssets (production path)", sha1: a.pack.sha1, url: a.loader.url, format: a.pack.format, bytes: a.pack.bytes, prompt: a.loader.prompt, required: a.loader.required, quality: a.textures.map((t) => `${t.name}:${t.quality}`) };
}

async function spec(version: string, store: LocalDiskStore): Promise<{ spec: TestFlightSpec; pack: Awaited<ReturnType<typeof packFor>>; loaderId: string }> {
  const pack = await packFor(version, store);
  const r = applyPackChange(null, { op: "upsert", namespace: NS, role: "main", sha1: pack.sha1, prompt: pack.prompt, required: pack.required }, { urlFor: () => pack.url });
  if (!r.ok) throw new Error(r.error);
  return {
    pack, loaderId: r.id,
    spec: {
      version,
      plugins: [{ remotePath: `${FX}/NxeonPackLoader-0.1.0.jar` }, { remotePath: `${FX}/TfItemModel-1.0.0.jar` }],
      files: [{ path: LOADER_CONFIG_PATH, content: serializeLoaderConfig(r.config) }],
      rcon: [
        { id: "pack-listed", command: "nxpacks list", expect: ["1 pack(s)", r.id, `sha1=${pack.sha1}`, "required=false"], expectNot: ["REJECTED"] },
        { id: "loader-status", command: "nxpacks status", expect: ["packs=1", "config=ok"] },
        { id: "item-model-ruby", command: `tfitem ${NS} ruby_sword`, expect: [`itemModel=${NS}:ruby_sword`, "material=IRON_SWORD"] },
        { id: "item-model-potion", command: `tfitem ${NS} health_potion`, expect: [`itemModel=${NS}:health_potion`] },
        { id: "plugins-listed", command: "plugins", expect: ["NxeonPackLoader", "TfItemModel"] },
      ],
    },
  };
}

const brief = (name: string, r: RunResult, extra: unknown) => ({
  name, version: r.report.version, status: r.report.status, overall: r.summary.overall, success: r.summary.success,
  bootMs: r.report.bootMs, peakRssKb: r.report.peakRssKb, timings: r.report.timings,
  checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence })),
  line: describe(r.summary), notes: r.report.notes, artifacts: r.report.artifacts, engine: r.report.engine, ...((extra as object) ?? {}),
});

async function main() {
  const which = process.argv[2] ?? "all";
  const outIdx = process.argv.indexOf("--out");
  const versions: Record<string, string> = { v12111: "1.21.11", v262: "26.2" };
  const names = which === "all" ? ["v12111", "v262"] : [which];
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-r1-flight-"));
  const store = new LocalDiskStore(dir, BASE);
  const out: unknown[] = [];
  try {
    for (const n of names) { // strictly one at a time (node-2 rule)
      const s = await spec(versions[n], store);
      const r = await runTestFlight(s.spec);
      out.push(brief(n, r, { pack: s.pack, loaderId: s.loaderId, namespace: NS, client: "none (server-side only)" }));
      console.log(`${n}: ${describe(r.summary)}`);
    }
  } finally { rmSync(dir, { recursive: true, force: true }); }
  if (outIdx > 0) writeFileSync(process.argv[outIdx + 1], JSON.stringify(out, null, 1));
  else console.log(JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });
#!/bin/bash
# Build one Test Flight fixture plugin jar the way the build service does (javac --release N -proc:none against the
# version's resolved classpath file, reproducible `jar --date`). Runs on the build host; fixtures are trusted code.
#   build.sh <fixture-dir> <api-version> <java-home> <release 21|25> <classpath.txt> <out.jar>
set -euo pipefail
SRC="${1:?fixture dir}"; API="${2:?api-version}"; JH="${3:?java home}"; REL="${4:?release}"; CP="${5:?classpath file}"; OUT="${6:?out jar}"
W="$(mktemp -d)"; trap 'rm -rf "$W"' EXIT
mkdir -p "$W/classes"
"$JH/bin/javac" -J-Xmx768m --release "$REL" -proc:none -encoding UTF-8 -cp "$(tr -d '\n' < "$CP")" -d "$W/classes" $(find "$SRC/src" -name '*.java' | sort)
sed "s/@API@/$API/" "$SRC/plugin.yml" > "$W/classes/plugin.yml"
( cd "$W/classes" && find . -type f | sed 's#^\./##' | sort > "$W/entries" )
args=(); while read -r e; do args+=(-C "$W/classes" "$e"); done < "$W/entries"
"$JH/bin/jar" --create --file "$OUT" --date 2026-01-01T00:00:00Z "${args[@]}"
sha256sum "$OUT"
