/** Minimal plugin.yml / paper-plugin.yml reader: top-level scalar keys only (name, main, version, api-version). */
function parsePluginYml(text) {
  const out = {};
  for (const raw of String(text).split(/\r?\n/)) {
    const m = /^([A-Za-z][\w-]*):[ \t]*(.*)$/.exec(raw);
    if (!m) continue;
    let v = m[2].replace(/\s+#.*$/, "").trim();
    if (/^(['"]).*\1$/.test(v)) v = v.slice(1, -1);
    if (["name", "main", "version", "api-version"].includes(m[1]) && v) out[m[1]] = v;
