export type YamlValue = string | null | YamlValue[] | { [k: string]: YamlValue };
export type YamlResult = { value: YamlValue; issues: string[] };

export const YAML_LIMITS = { maxBytes: 512 * 1024, maxLines: 20_000, maxDepth: 32, maxNodes: 50_000 };
