type Line = { n: number; indent: number; text: string; raw: string };

function stripComment(s: string): string {
  let q: string | null = null;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (q) {
      if (c === q) { if (q === "'" && s[i + 1] === "'") { i++; continue; } q = null; }
      else if (q === '"' && c === "\\") i++;
