    if (/^[|>][+-]?[0-9]?[+-]?$/.test(s)) return this.blockScalar(ind, s[0] === ">");
    if (s.startsWith("[") || s.startsWith("{")) {
      const f = new Flow(s, this, l.n, depth);
      const v = f.value();
      f.ws();
      if (f.pos < s.length) this.issue(`line ${l.n}: trailing text after a flow collection`);
      return v;
    }
    if (s.startsWith('"') || s.startsWith("'")) {
      const q = this.quoted(s, l.n);
      return q;
    }
    return plain(s);
  }

  quoted(s: string, n: number): string | null {
    const q = s[0];
    if (s.length < 2 || s[s.length - 1] !== q) { this.issue(`line ${n}: unterminated or multi-line quoted scalar`); return s.slice(1); }
    const body = s.slice(1, -1);
    if (q === "'") return body.replace(/''/g, "'");
    return body.replace(/\\(u[0-9a-fA-F]{4}|x[0-9a-fA-F]{2}|.)/g, (_m, e: string) => {
      if (e[0] === "u" || e[0] === "x") return String.fromCharCode(parseInt(e.slice(1), 16));
      return ({ n: "\n", t: "\t", r: "\r", "0": "\0", '"': '"', "\\": "\\", "/": "/", " ": " " } as Record<string, string>)[e] ?? e;
