  }

  blockScalar(ind: number, folded: boolean): string {
    const parts: string[] = [];
    let minInd = -1;
    while (this.lines[this.i] && this.lines[this.i].indent > ind) {
      const l = this.lines[this.i++];
      if (minInd < 0) minInd = l.indent;
      parts.push(l.raw.slice(Math.min(minInd, l.indent)));
    }
    return parts.join(folded ? " " : "\n");
  }
}

function plain(s: string): string | null {
  const t = s.trim();
  if (t === "" || t === "~" || t === "null" || t === "Null" || t === "NULL") return null;
  return t;
}

class Flow {
  pos = 0;
  constructor(readonly s: string, readonly p: Parser, readonly n: number, readonly depth: number) {}
  ws() { while (this.pos < this.s.length && /\s/.test(this.s[this.pos])) this.pos++; }
  value(d = this.depth): YamlValue {
