        out.push(this.value(d + 1));
        this.ws();
        if (this.s[this.pos] === ",") this.pos++;
        else if (this.s[this.pos] !== "]") { this.p.issue(`line ${this.n}: bad flow sequence`); this.pos = this.s.length; return out; }
      }
    }
    if (c === "{") {
      this.pos++;
      const out: { [k: string]: YamlValue } = {};
      for (;;) {
        this.ws();
        if (this.s[this.pos] === "}") { this.pos++; return out; }
        if (this.pos >= this.s.length) { this.p.issue(`line ${this.n}: unterminated { }`); return out; }
