        this.ws();
        let v: YamlValue = null;
        if (this.s[this.pos] === ":") { this.pos++; v = this.value(d + 1); }
        if (k != null && !BAD_KEYS.has(k)) out[k] = v;
        this.ws();
        if (this.s[this.pos] === ",") this.pos++;
        else if (this.s[this.pos] !== "}") { this.p.issue(`line ${this.n}: bad flow mapping`); this.pos = this.s.length; return out; }
      }
    }
    return this.scalar(false);
  }
  scalar(isKey: boolean): string | null {
    this.ws();
    const c = this.s[this.pos];
    if (c === '"' || c === "'") {
      let j = this.pos + 1;
      for (; j < this.s.length; j++) {
        if (this.s[j] === c) { if (c === "'" && this.s[j + 1] === "'") { j++; continue; } break; }
        if (c === '"' && this.s[j] === "\\") j++;
      }
      const tok = this.s.slice(this.pos, j + 1);
      this.pos = j + 1;
      return this.p.quoted(tok, this.n);
    }
    const start = this.pos;
    while (this.pos < this.s.length && !",]}".includes(this.s[this.pos]) && !(isKey && this.s[this.pos] === ":" && /[\s,}]|$/.test(this.s[this.pos + 1] ?? ""))) {
      if (!isKey && this.s[this.pos] === ":" && false) break;
      this.pos++;
    }
    return plain(this.s.slice(start, this.pos));
  }
}

export function parseYaml(text: string): YamlResult {
  if (typeof text !== "string") return { value: null, issues: ["not text"] };
  if (Buffer.byteLength(text) > YAML_LIMITS.maxBytes) return { value: null, issues: [`larger than ${YAML_LIMITS.maxBytes} bytes`] };
  const lines: Line[] = [];
  const all = text.replace(/^\uFEFF/, "").split(/\r?\n/);
  if (all.length > YAML_LIMITS.maxLines) return { value: null, issues: [`more than ${YAML_LIMITS.maxLines} lines`] };
  const pre: string[] = [];
  all.forEach((raw, idx) => {
    if (/^(---|\.\.\.)\s*$/.test(raw)) return;
    const tabLead = /^\s*\t/.test(raw);
    const expanded = raw.replace(/^[ \t]+/, (m) => m.replace(/\t/g, "  "));
    const t = stripComment(expanded);
    if (!t.trim()) { lines.push({ n: idx + 1, indent: -1, text: "", raw: expanded }); return; }
    if (tabLead) pre.push(`line ${idx + 1}: tab indentation (read as 2 spaces)`);
    const indent = t.length - t.trimStart().length;
    lines.push({ n: idx + 1, indent, text: t.trim(), raw: expanded });
  });
  // Blank lines matter only inside block scalars; give them the indent of the next real line so they are kept there.
  for (let k = lines.length - 1, next = 0; k >= 0; k--) { if (lines[k].indent < 0) lines[k].indent = next; else next = lines[k].indent; }
  const real = lines.filter((l, k) => l.text || (k > 0 && lines.slice(0, k).some((x) => x.text)));
  const nonEmpty = real.filter((l) => l.text);
  if (!nonEmpty.length) return { value: null, issues: pre };
  const p = new Parser(real.filter((l) => l.text || true).map((l) => (l.text ? l : { ...l, text: "" })).filter((l) => l.text));
