  p.issues.push(...pre);
  const first = p.lines[0];
  let value: YamlValue;
  if (!isSeqItem(first.text) && keyColon(first.text) <= 0 && p.lines.length === 1) value = p.valueText(first.text, -1, 0, first);
  else value = p.block(first.indent, 0);
  while (p.i < p.lines.length) { p.issue(`line ${p.lines[p.i].n}: content after the top-level block (ignored)`); p.i = p.lines.length; }
  return { value, issues: p.issues };
}

// ---- small typed accessors used by descriptor readers ------------------------------------------------------------
export const asMap = (v: YamlValue | undefined): { [k: string]: YamlValue } | null => (v && typeof v === "object" && !Array.isArray(v) ? v : null);
export const asStr = (v: YamlValue | undefined): string | null => (typeof v === "string" ? v : null);
/** A string or a list of strings (plugin.yml allows both for depend/aliases/authors). */
export function asStrList(v: YamlValue | undefined): string[] {
  if (typeof v === "string") return v.split(/[,\s]+/).map((x) => x.trim()).filter(Boolean).length > 1 && !/\s/.test(v.trim()) ? [v.trim()] : [v.trim()].filter(Boolean);
  if (Array.isArray(v)) return v.filter((x): x is string => typeof x === "string").map((x) => x.trim()).filter(Boolean);
  return [];
}
export function asBool(v: YamlValue | undefined): boolean | null {
  if (typeof v !== "string") return null;
  const t = v.toLowerCase();
  if (["true", "yes", "on", "y"].includes(t)) return true;
  if (["false", "no", "off", "n"].includes(t)) return false;
  return null;
}

