// plugin.yml / paper-plugin.yml -> a typed descriptor. Pure. Unknown or malformed fields are reported, never thrown.
// Bukkit rules mirrored here: permission defaults (true/false/op/not op and their aliases, falling back to the
// top-level `default-permission`, else op); command aliases may be a string or a list; depend/softdepend/loadbefore
// may be a string or a list. paper-plugin.yml declares dependencies as `dependencies.server.<Name>: { load, required }`
// (load BEFORE = this plugin loads before that one = Bukkit `loadbefore`) and has no `commands:` (Brigadier only).
import { asBool, asMap, asStr, asStrList, parseYaml, type YamlValue } from "./yaml";

export type PermissionDefault = "true" | "false" | "op" | "not op";
export type DeclaredCommand = { name: string; aliases: string[]; permission: string | null; description: string | null };
export type DeclaredPermission = { name: string; default: PermissionDefault; explicitDefault: boolean; children: string[] };
export type PluginDescriptor = {
  file: "plugin.yml" | "paper-plugin.yml";
  name: string | null;
  version: string | null;
  main: string | null;
  apiVersion: string | null;
  foliaSupported: boolean;
  depend: string[];
  softdepend: string[];
  loadbefore: string[];
  provides: string[];
  libraries: string[];
  commands: DeclaredCommand[];
  permissions: DeclaredPermission[];
  issues: string[];
};

const PERM_DEFAULTS: Record<string, PermissionDefault> = {
  true: "true", t: "true", yes: "true", y: "true",
  false: "false", f: "false", no: "false", n: "false",
  op: "op", isop: "op", operator: "op", isoperator: "op", admin: "op", isadmin: "op",
  "!op": "not op", notop: "not op", "not op": "not op", "!operator": "not op", notoperator: "not op", "!admin": "not op", notadmin: "not op",
};
export const normalizePermDefault = (v: YamlValue | undefined): PermissionDefault | null => {
  const s = asStr(v);
  return s == null ? null : PERM_DEFAULTS[s.toLowerCase().replace(/_/g, " ").trim()] ?? PERM_DEFAULTS[s.toLowerCase().replace(/[\s_]/g, "")] ?? null;
};

const NAME_RE = /^[A-Za-z0-9 _.-]{1,64}$/;

export function readDescriptor(text: string, file: "plugin.yml" | "paper-plugin.yml"): PluginDescriptor {
  const { value, issues } = parseYaml(text);
  const d: PluginDescriptor = { file, name: null, version: null, main: null, apiVersion: null, foliaSupported: false, depend: [], softdepend: [], loadbefore: [], provides: [], libraries: [], commands: [], permissions: [], issues: [...issues] };
  const root = asMap(value);
  if (!root) { d.issues.push(`${file} is not a mapping`); return d; }
  d.name = asStr(root.name);
  if (d.name && !NAME_RE.test(d.name)) d.issues.push(`plugin name '${d.name.slice(0, 80)}' has characters Paper refuses`);
  d.version = asStr(root.version);
  d.main = asStr(root.main);
  d.apiVersion = asStr(root["api-version"]);
  d.foliaSupported = asBool(root["folia-supported"]) === true;
  d.provides = asStrList(root.provides);
  d.libraries = asStrList(root.libraries);
  if (file === "plugin.yml") {
    d.depend = asStrList(root.depend);
    d.softdepend = asStrList(root.softdepend);
    d.loadbefore = asStrList(root.loadbefore);
  } else {
    const deps = asMap(asMap(root.dependencies)?.server);
    for (const [dep, cfgRaw] of Object.entries(deps ?? {})) {
      const cfg = asMap(cfgRaw);
      const load = (asStr(cfg?.load) ?? "OMIT").toUpperCase();
      const required = asBool(cfg?.required) ?? true;
      if (load === "BEFORE") d.loadbefore.push(dep);
      else if (required) d.depend.push(dep);
      else d.softdepend.push(dep);
    }
    for (const k of ["depend", "softdepend", "loadbefore"] as const) if (root[k] !== undefined) d.issues.push(`paper-plugin.yml ignores '${k}' (use dependencies.server)`);
    if (root.commands !== undefined) d.issues.push("paper-plugin.yml cannot declare commands (Paper ignores them; Brigadier only)");
  }
  if (!d.name) d.issues.push(`${file} has no name`);
  if (!d.main) d.issues.push(`${file} has no main class`);

  const fallback = normalizePermDefault(root["default-permission"]) ?? "op";
  const commands = file === "plugin.yml" ? asMap(root.commands) : null;
  if (root.commands !== undefined && file === "plugin.yml" && !commands && root.commands !== null) d.issues.push("commands is not a mapping");
  for (const [name, raw] of Object.entries(commands ?? {})) {
    const c = asMap(raw);
    if (/[\s:]/.test(name) || !name) { d.issues.push(`command '${name.slice(0, 40)}' has an invalid label`); continue; }
    d.commands.push({ name: name.toLowerCase(), aliases: asStrList(c?.aliases).map((a) => a.toLowerCase()).filter((a) => !/[\s:]/.test(a)), permission: asStr(c?.permission), description: asStr(c?.description) });
  }
  const perms = asMap(root.permissions);
  const seen = new Set<string>();
  const addPerm = (name: string, raw: YamlValue, inheritedDefault: PermissionDefault, depth: number) => {
    if (depth > 8 || d.permissions.length >= 2000) return;
    const key = name.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    const p = asMap(raw);
    const def = normalizePermDefault(p?.default);
    const childMap = asMap(p?.children);
    const children = childMap ? Object.keys(childMap) : asStrList(p?.children);
    d.permissions.push({ name: key, default: def ?? inheritedDefault, explicitDefault: def != null, children: children.map((c) => c.toLowerCase()) });
    // Bukkit registers map-form children that carry their own definition as permissions too.
    for (const [cn, cv] of Object.entries(childMap ?? {})) if (asMap(cv)) addPerm(cn, cv, def ?? inheritedDefault, depth + 1);
  };
  for (const [name, raw] of Object.entries(perms ?? {})) addPerm(name, raw, fallback, 0);
  return d;
}

