export type AnnotationInfo = { type: string; values: Record<string, string> };
export type MethodInfo = { name: string; desc: string; access: number; annotations: AnnotationInfo[]; calls: Call[]; codeBytes: number };
export type ClassInfo = { name: string; superName: string | null; interfaces: string[]; major: number; access: number; methods: MethodInfo[] };
export type ClassResult = { ok: true; cls: ClassInfo } | { ok: false; error: string };

export const CLASS_LIMITS = { maxBytes: 2 * 1024 * 1024, maxConstants: 65535, maxMethods: 4000, maxCallsPerMethod: 5000, window: 8 };

/** Calls that only box/convert a constant: the constant window survives them (`setCustomModelData(Integer.valueOf(7))`). */
const TRANSPARENT = new Set(["java/lang/Integer.valueOf", "java/lang/Float.valueOf", "java/lang/Long.valueOf", "java/lang/Short.valueOf", "java/lang/Byte.valueOf", "java/lang/Boolean.valueOf"]);

type Cp = { tag: number; a?: number; b?: number; s?: string; i?: number };

class Reader {
  o = 0;
  constructor(readonly b: Buffer) {}
  need(n: number) { if (this.o + n > this.b.length) throw new Error("truncated class file"); }
  u1() { this.need(1); return this.b[this.o++]; }
  u2() { this.need(2); const v = this.b.readUInt16BE(this.o); this.o += 2; return v; }
  u4() { this.need(4); const v = this.b.readUInt32BE(this.o); this.o += 4; return v; }
  i4() { this.need(4); const v = this.b.readInt32BE(this.o); this.o += 4; return v; }
  bytes(n: number) { this.need(n); const v = this.b.subarray(this.o, this.o + n); this.o += n; return v; }
}

/** Java's "modified UTF-8" is close enough to UTF-8 for names and literals; invalid sequences become U+FFFD. */
const utf8 = (b: Buffer) => b.toString("utf8");

export function parseClass(buf: Buffer): ClassResult {
  try {
    if (buf.length > CLASS_LIMITS.maxBytes) return { ok: false, error: "class file too large" };
    const r = new Reader(buf);
    if (r.u4() !== 0xcafebabe) return { ok: false, error: "not a class file" };
    r.u2();
    const major = r.u2();
    const count = r.u2();
    const cp: Cp[] = new Array(count);
    for (let i = 1; i < count; i++) {
      const tag = r.u1();
      switch (tag) {
        case 1: { const len = r.u2(); cp[i] = { tag, s: utf8(r.bytes(len)) }; break; }
        case 3: cp[i] = { tag, i: r.i4() }; break;
        case 4: r.u4(); cp[i] = { tag }; break;
        case 5: case 6: r.u4(); r.u4(); cp[i] = { tag }; i++; break;
        case 7: case 8: case 16: case 19: case 20: cp[i] = { tag, a: r.u2() }; break;
        case 9: case 10: case 11: case 12: case 17: case 18: cp[i] = { tag, a: r.u2(), b: r.u2() }; break;
        case 15: cp[i] = { tag, a: r.u1(), b: r.u2() }; break;
