    const cls = (i: number): string => { const e = cp[i]; if (!e || e.tag !== 7) throw new Error("bad class ref"); return str(e.a!); };
    const ref = (i: number): { owner: string; name: string; desc: string } => {
      const e = cp[i];
      if (!e || ![9, 10, 11].includes(e.tag)) throw new Error("bad member ref");
      const nt = cp[e.b!];
      if (!nt || nt.tag !== 12) throw new Error("bad name-and-type");
      return { owner: cls(e.a!), name: str(nt.a!), desc: str(nt.b!) };
    };
    const access = r.u2();
    const name = cls(r.u2());
    const superIdx = r.u2();
    const superName = superIdx ? cls(superIdx) : null;
    const interfaces: string[] = [];
    for (let n = r.u2(); n > 0; n--) interfaces.push(cls(r.u2()));
    const skipAttrs = () => { for (let n = r.u2(); n > 0; n--) { r.u2(); r.bytes(r.u4()); } };
    for (let n = r.u2(); n > 0; n--) { r.u2(); r.u2(); r.u2(); skipAttrs(); }
