          strs: win.filter((w) => w.t === "s").map((w) => w.v as string),
          ints: win.filter((w) => w.t === "i").map((w) => w.v as number),
          classes: win.filter((w) => w.t === "c").map((w) => w.v as string),
          fields: win.filter((w) => w.t === "f").map((w) => w.v as string),
        });
      }
