export const javaReleaseOf = (major: number): number => Math.max(1, major - 44);

/** `(Lorg/bukkit/event/player/PlayerJoinEvent;)V` -> `org.bukkit.event.player.PlayerJoinEvent` (first parameter type). */
export function firstParamType(desc: string): string | null {
  const m = /^\(L([^;]+);/.exec(desc);
  return m ? m[1].replace(/\//g, ".") : null;
}

