// Cyrus server inventory (R2): report types + the read-only file-access seam.
// HOST SEAM: the inventory reaches a server only through `ReadOnlyServerFs`, a read-only subset that Nxeon's Mods
// engine GuestFs (lib/mods/guest-fs.ts: SSH in production, LocalGuestFs in tests/SANDBOX) already satisfies
// structurally, so no Nxeon module is imported here. A standalone Cyrus would implement it over the host API.
import type { PluginDescriptor } from "./descriptor";

export interface ReadOnlyServerFs {
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  list(dir: string): Promise<string[]>;
}

export type EventUse = { event: string; priority: string; ignoreCancelled: boolean; mutates: boolean; cancels: boolean; where: string };
export type ServiceUse = { service: "economy" | "permission" | "chat"; via: "ServicesManager.register" | "implements"; where: string };
export type SingleOwnerResource = "economy_provider" | "permission_provider" | "chat_provider" | "chat_renderer" | "tab_list" | "sidebar" | "world_rules" | "join_quit_messages";
export type SingleOwnerUse = { resource: SingleOwnerResource; where: string; evidence: string };
export type KeyUse = { key: string; where: string };

export type BytecodeSummary = {
  classesParsed: number;
  classesFailed: number;
  classesSkipped: number;
  /** Highest class-file major version seen (65 = Java 21, 69 = Java 25). */
  maxClassMajor: number | null;
  javaRelease: number | null;
  events: EventUse[];
  /** Root literals registered through Paper's Brigadier API (`Commands.register`), approximate. */
  brigadierRoots: string[];
  services: ServiceUse[];
  singleOwner: SingleOwnerUse[];
  /** Full `namespace:key` strings; plugin-scoped keys use the plugin's name lowercased (Bukkit's rule). */
  namespacedKeys: KeyUse[];
  pdcUsed: boolean;
  customModelData: number[];
  itemModels: KeyUse[];
  recipes: KeyUse[];
  soundKeys: KeyUse[];
  repeatingTaskSites: number;
  displayEntitySpawnSites: number;
  bukkitSchedulerSites: number;
  foliaSchedulerSites: number;
  usesItemModelApi: boolean;
  /** What this summary could NOT determine (computed keys, dynamic registration, skipped classes...). */
  undetermined: string[];
};

export type JarFlags = { unsafeNames: string[]; duplicateNames: string[]; bombEntries: string[]; unreadable: string | null; serverJar: boolean; serverJarEvidence: string | null };

export type PluginJar = {
  file: string;
  path: string;
  size: number;
  sha256: string;
  sha1: string;
  descriptor: PluginDescriptor | null;
  bytecode: BytecodeSummary | null;
  flags: JarFlags;
};

export type DatapackFile = { type: string; id: string };
export type DatapackTag = { registry: string; id: string; replace: boolean; values: string[] };
export type DatapackIndex = {
  name: string;
  /** "world" = <level>/datapacks; "plugin" = bundled in a plugin (not scanned yet); "candidate" = a new pack. */
  source: "world" | "candidate";
  container: "zip" | "dir";
  format: { packFormat: number | null; min: number | null; max: number | null; description: string | null } | null;
  files: DatapackFile[];
  tags: DatapackTag[];
  issues: string[];
};

export type ResourcePackOwner = { kind: "server.properties" | "pack-loader" | "plugin"; name: string; detail: string };

export type ServerSoftware = { name: "paper" | "purpur" | "folia" | "spigot" | "craftbukkit" | "vanilla" | "fabric" | "forge" | "neoforge" | "unknown"; mcVersion: string | null; build: string | null; evidence: string[] };

export type InventoryReport = {
  schema: 1;
  base: string;
  software: ServerSoftware;
  plugins: PluginJar[];
  serverProperties: { present: boolean; keys: Record<string, string>; redacted: number };
  datapacks: { levelName: string; folder: DatapackIndex[]; registered: { enabled: string[]; disabled: string[] } | null; issues: string[] };
  resourcePackOwners: ResourcePackOwner[];
  packLoader: { present: boolean; packs: { id: string; sha1: string; url: string; required: boolean }[]; error: string | null };
  bedrock: { geyser: boolean; floodgate: boolean };
  limits: { jarsSeen: number; jarsScanned: number; bytesRead: number; truncated: string[] };
  undetermined: string[];
};

