    let lastAdvKey: string | null = null;
    let literals: string[] = [];
    let mutates = false, cancels = false;
    const eventType = eh ? firstParamType(m.desc) : null;
    const pushKey = (k: string | null) => { if (k) { lastKey = k; sum.namespacedKeys.push({ key: k, where }); } else note("NamespacedKey built from a computed (non-literal) string"); };
    for (const call of m.calls) {
      const ow = call.owner, nm = call.name;
      // NamespacedKey construction
      if (ow === NK && nm === "<init>") {
        if (call.desc === "(Lorg/bukkit/plugin/Plugin;Ljava/lang/String;)V") pushKey(call.strs.length && pluginNs ? `${pluginNs}:${call.strs.at(-1)!.toLowerCase()}` : null);
        else if (call.desc === "(Ljava/lang/String;Ljava/lang/String;)V") pushKey(call.strs.length >= 2 ? `${call.strs.at(-2)!.toLowerCase()}:${call.strs.at(-1)!.toLowerCase()}` : null);
      } else if (ow === NK && nm === "minecraft") pushKey(call.strs.length ? `minecraft:${call.strs.at(-1)}` : null);
      else if (ow === NK && (nm === "fromString" || nm === "fromStringOrNull")) {
        const s = call.strs[0];
        pushKey(s ? (s.includes(":") ? s.toLowerCase() : `minecraft:${s.toLowerCase()}`) : null);
      } else if (ow === "net/kyori/adventure/key/Key" && nm === "key") {
        if (call.strs.length >= 2 && call.desc.startsWith("(Ljava/lang/String;Ljava/lang/String;")) lastAdvKey = `${call.strs.at(-2)}:${call.strs.at(-1)}`;
        else if (call.strs.length) lastAdvKey = call.strs.at(-1)!.includes(":") ? call.strs.at(-1)! : `minecraft:${call.strs.at(-1)}`;
      }
      if (/^org\/bukkit\/persistence\/PersistentDataContainer$/.test(ow) || /PersistentDataHolder$/.test(ow) && nm === "getPersistentDataContainer") sum.pdcUsed = true;
      // item models / custom model data
      if (nm === "setItemModel" || (ow === "io/papermc/paper/datacomponent/DataComponentTypes" && nm === "ITEM_MODEL")) {
        sum.usesItemModelApi = true;
        if (lastKey) sum.itemModels.push({ key: lastKey, where }); else note("item_model set from a computed key");
      }
      if (call.fields.includes("io/papermc/paper/datacomponent/DataComponentTypes.ITEM_MODEL")) { sum.usesItemModelApi = true; if (lastKey) sum.itemModels.push({ key: lastKey, where }); }
      if (nm === "setCustomModelData") {
        if (call.ints.length) sum.customModelData.push(call.ints.at(-1)!); else note("custom_model_data set from a computed value");
      }
      // recipes
      if (nm === "<init>" && RECIPE_CLASS.test(ow) && call.desc.startsWith("(Lorg/bukkit/NamespacedKey;")) {
        if (lastKey) sum.recipes.push({ key: lastKey, where }); else note("recipe registered with a computed key");
      }
      // sounds
      if (nm === "playSound" && call.desc.includes("Ljava/lang/String;")) {
        const k = call.strs.find((s) => SOUNDISH.test(s));
        if (k) sum.soundKeys.push({ key: k.includes(":") ? k : `minecraft:${k}`, where }); else note("sound played by a computed name");
      }
      if (ow === "net/kyori/adventure/sound/Sound" && nm === "sound") {
        const k = lastAdvKey ?? lastKey;
        if (k) sum.soundKeys.push({ key: k, where });
      }
      // commands (Paper Brigadier)
      if ((ow === "io/papermc/paper/command/brigadier/Commands" || ow === "com/mojang/brigadier/builder/LiteralArgumentBuilder") && nm === "literal") { if (call.strs.length) literals.push(call.strs.at(-1)!.toLowerCase()); else note("Brigadier literal from a computed string"); }
      if (ow === "io/papermc/paper/command/brigadier/Commands" && nm === "register") {
        const root = call.desc.startsWith("(Ljava/lang/String;") ? call.strs[0]?.toLowerCase() : literals[0];
        if (root) sum.brigadierRoots.push(root); else note("Brigadier command registered under a computed name");
        literals = [];
      }
      // services and single-owner resources
      if (ow === "org/bukkit/plugin/ServicesManager" && nm === "register") {
        const s = call.classes.map((k) => VAULT[k]).find(Boolean);
        if (s) { sum.services.push({ service: s, via: "ServicesManager.register", where }); sum.singleOwner.push({ resource: SERVICE_OWNER[s], where, evidence: `ServicesManager.register(${s})` }); }
        else note("ServicesManager.register for a service class this summary does not know");
      }
      if (/AsyncChatEvent$/.test(ow) && nm === "renderer" && call.desc.startsWith("(L")) sum.singleOwner.push({ resource: "chat_renderer", where, evidence: "AsyncChatEvent.renderer(...)" });
      if (/AsyncPlayerChatEvent$/.test(ow) && nm === "setFormat") sum.singleOwner.push({ resource: "chat_renderer", where, evidence: "AsyncPlayerChatEvent.setFormat(...)" });
      if (TAB.test(nm)) sum.singleOwner.push({ resource: "tab_list", where, evidence: `${nm}(...)` });
      if (nm === "setDisplaySlot" && call.fields.some((f) => f.endsWith("DisplaySlot.SIDEBAR"))) sum.singleOwner.push({ resource: "sidebar", where, evidence: "Objective.setDisplaySlot(SIDEBAR)" });
      if ((ow === "org/bukkit/World" && WORLD_RULES.test(nm)) || (ow === "org/bukkit/WorldBorder" && /^(setSize|setCenter)$/.test(nm))) sum.singleOwner.push({ resource: "world_rules", where, evidence: `${ow.split("/").pop()}.${nm}` });
      if (/Player(Join|Quit)Event$/.test(ow) && /^(setJoinMessage|setQuitMessage|joinMessage|quitMessage)$/.test(nm) && !call.desc.startsWith("()")) sum.singleOwner.push({ resource: "join_quit_messages", where, evidence: `${ow.split("/").pop()}.${nm}` });
      // budgets / schedulers
      if (REPEATING.test(nm)) sum.repeatingTaskSites++;
      if (ow === "org/bukkit/scheduler/BukkitScheduler" || ow === "org/bukkit/scheduler/BukkitRunnable") sum.bukkitSchedulerSites++;
      if (FOLIA_SCHED.test(ow)) sum.foliaSchedulerSites++;
      if ((nm === "spawn" && call.classes.some((k) => DISPLAY.test(k))) || (nm === "spawnEntity" && call.fields.some((f) => DISPLAY_FIELD.test(f)))) sum.displayEntitySpawnSites++;
      if (ow === "org/bukkit/plugin/PluginManager" && nm === "registerEvent") note("listener registered dynamically (registerEvent): its event and priority are not analysed");
      // event mutation inside a handler
      if (eventType && /Event$/.test(ow) && call.desc !== "()V" && !call.desc.startsWith("()")) {
        if (nm === "setCancelled" || nm === "setUseInteractedBlock" || nm === "setUseItemInHand") cancels = true;
        else if (/^set[A-Z]/.test(nm) || (call.desc.endsWith(")V") && nm !== "<init>")) mutates = true;
      }
    }
    if (eh && eventType) {
      sum.events.push({ event: eventType, priority: (eh.values.priority || "NORMAL").toUpperCase(), ignoreCancelled: eh.values.ignoreCancelled === "1", mutates, cancels, where });
    } else if (eh) note("@EventHandler method without an event parameter");
  }
}

/** Sort + dedupe every list so the summary is deterministic regardless of class order in the jar. */
export function finishSummary(sum: BytecodeSummary, notes: Map<string, number>): BytecodeSummary {
  const uniq = <T>(xs: T[], key: (x: T) => string) => { const m = new Map<string, T>(); for (const x of xs) if (!m.has(key(x))) m.set(key(x), x); return [...m.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)).map(([, v]) => v); };
  sum.events = uniq(sum.events, (e) => `${e.event}|${e.priority}|${e.where}`);
  sum.brigadierRoots = [...new Set(sum.brigadierRoots)].sort();
  sum.services = uniq(sum.services, (s) => `${s.service}|${s.via}|${s.where}`);
  sum.singleOwner = uniq(sum.singleOwner, (s) => `${s.resource}|${s.where}`);
  sum.namespacedKeys = uniq(sum.namespacedKeys, (k) => `${k.key}|${k.where}`);
  sum.itemModels = uniq(sum.itemModels, (k) => `${k.key}|${k.where}`);
  sum.recipes = uniq(sum.recipes, (k) => `${k.key}|${k.where}`);
  sum.soundKeys = uniq(sum.soundKeys, (k) => `${k.key}|${k.where}`);
  sum.customModelData = [...new Set(sum.customModelData)].sort((a, b) => a - b);
  for (const [k, n] of [...notes.entries()].sort()) sum.undetermined.push(`${k} (${n} site${n === 1 ? "" : "s"})`);
  if (sum.classesSkipped) sum.undetermined.push(`${sum.classesSkipped} class file(s) not analysed (limits)`);
  if (sum.classesFailed) sum.undetermined.push(`${sum.classesFailed} class file(s) could not be parsed`);
  sum.undetermined.push("calls made from helper methods outside an @EventHandler method are not attributed to the event");
  return sum;
}

export type { Call };

