// One plugin jar -> descriptor + bytecode summary + safety flags. Pure (bytes in, data out). Never extracts or runs.
import { createHash } from "node:crypto";
import { parseClass } from "./classfile";
import { addClass, emptySummary, finishSummary } from "./bytecode";
import { readDescriptor } from "./descriptor";
import { DEFAULT_ZIP_LIMITS, findEntry, indexZip, readEntry, type ZipLimits } from "./zipread";
import type { PluginJar } from "./types";

export const JAR_LIMITS = { maxClasses: 4000, maxClassBytes: 1024 * 1024, maxDescriptorBytes: 256 * 1024 };

/** Signs that a jar is a Minecraft/Paper SERVER (bundler/paperclip/CraftBukkit main), never a plugin. */
const SERVER_MARKERS = ["net/minecraft/server/Main.class", "net/minecraft/bundler/Main.class", "io/papermc/paperclip/Main.class", "io/papermc/paperclip/Paperclip.class", "org/bukkit/craftbukkit/Main.class", "META-INF/versions.list"];

export function inspectJar(file: string, path: string, buf: Buffer, opts: { zipLimits?: ZipLimits; bytecode?: boolean } = {}): PluginJar {
  const jar: PluginJar = {
    file, path, size: buf.length,
    sha256: createHash("sha256").update(buf).digest("hex"),
    sha1: createHash("sha1").update(buf).digest("hex"),
    descriptor: null, bytecode: null,
    flags: { unsafeNames: [], duplicateNames: [], bombEntries: [], unreadable: null, serverJar: false, serverJarEvidence: null },
  };
  const idx = indexZip(buf, opts.zipLimits ?? DEFAULT_ZIP_LIMITS);
  if (!idx.ok) { jar.flags.unreadable = idx.error; return jar; }
  const z = idx.zip;
  jar.flags.unsafeNames = z.unsafeNames.slice(0, 20);
  jar.flags.duplicateNames = z.duplicateNames.slice(0, 20);
  const marker = SERVER_MARKERS.find((m) => findEntry(z, m));
  if (marker) { jar.flags.serverJar = true; jar.flags.serverJarEvidence = `contains ${marker}`; }

  for (const f of ["plugin.yml", "paper-plugin.yml"] as const) {
    const e = findEntry(z, f);
    if (!e) continue;
    const r = readEntry(z, e, JAR_LIMITS.maxDescriptorBytes);
    if (!r.ok) { if (r.bomb) jar.flags.bombEntries.push(f); jar.descriptor = { ...readDescriptor("", f), issues: [`${f} unreadable: ${r.error}`] }; break; }
    jar.descriptor = readDescriptor(r.data.toString("utf8"), f);
    break; // plugin.yml wins when both exist (Paper prefers paper-plugin.yml, but plugin.yml is what Bukkit-API mods ship)
  }
  // Paper actually prefers paper-plugin.yml when both exist; mirror that.
  const pp = findEntry(z, "paper-plugin.yml");
  if (pp && jar.descriptor?.file === "plugin.yml") {
    const r = readEntry(z, pp, JAR_LIMITS.maxDescriptorBytes);
    if (r.ok) { const d = readDescriptor(r.data.toString("utf8"), "paper-plugin.yml"); d.issues.push("jar has both plugin.yml and paper-plugin.yml: Paper uses paper-plugin.yml"); jar.descriptor = d; }
  }
  if (opts.bytecode === false) return jar;

  const sum = emptySummary();
  const notes = new Map<string, number>();
  const ns = jar.descriptor?.name ? jar.descriptor.name.toLowerCase().replace(/[^a-z0-9._-]/g, "") : null;
  let n = 0;
  for (const e of z.entries) {
    if (e.dir || !e.name.endsWith(".class")) continue;
    if (n >= JAR_LIMITS.maxClasses) { sum.classesSkipped++; continue; }
    n++;
    const r = readEntry(z, e, JAR_LIMITS.maxClassBytes);
    if (!r.ok) { if (r.bomb) jar.flags.bombEntries.push(e.name.slice(0, 120)); sum.classesSkipped++; continue; }
    const c = parseClass(r.data);
    if (!c.ok) { sum.classesFailed++; continue; }
    addClass(sum, c.cls, ns, notes);
  }
  jar.flags.bombEntries = jar.flags.bombEntries.slice(0, 20);
  jar.bytecode = finishSummary(sum, notes);
  return jar;
}

