// Bounded NBT reader, only to find the registered datapacks in level.dat (Data.DataPacks.Enabled / Disabled).
// Pure. Arrays are skipped (length only), node and depth caps, gunzip output cap. Never throws.
import { gunzipSync } from "node:zlib";

export const NBT_LIMITS = { maxInflate: 32 * 1024 * 1024, maxNodes: 500_000, maxDepth: 64 };
type Nbt = string | number | bigint | null | Nbt[] | { [k: string]: Nbt };

export function readLevelDatDatapacks(gz: Buffer): { ok: true; enabled: string[]; disabled: string[] } | { ok: false; error: string } {
  let buf: Buffer;
  try { buf = gz.length >= 2 && gz[0] === 0x1f && gz[1] === 0x8b ? gunzipSync(gz, { maxOutputLength: NBT_LIMITS.maxInflate }) : gz; }
  catch { return { ok: false, error: "level.dat could not be decompressed (corrupt or over the size cap)" }; }
  let o = 0, nodes = 0;
  const need = (n: number) => { if (o + n > buf.length) throw new Error("truncated NBT"); };
  const str = () => { need(2); const l = buf.readUInt16BE(o); o += 2; need(l); const s = buf.toString("utf8", o, o + l); o += l; return s; };
  const payload = (t: number, depth: number, keep: boolean): Nbt => {
    if (++nodes > NBT_LIMITS.maxNodes) throw new Error("NBT too large");
    if (depth > NBT_LIMITS.maxDepth) throw new Error("NBT nested too deep");
    switch (t) {
      case 1: need(1); o += 1; return null;
      case 2: need(2); o += 2; return null;
      case 3: need(4); o += 4; return null;
      case 4: need(8); o += 8; return null;
      case 5: need(4); o += 4; return null;
      case 6: need(8); o += 8; return null;
      case 7: case 11: case 12: { need(4); const n = buf.readInt32BE(o); o += 4; if (n < 0) throw new Error("bad array"); const w = t === 7 ? 1 : t === 11 ? 4 : 8; need(n * w); o += n * w; return null; }
      case 8: { const s = str(); return keep ? s : null; }
      case 9: { need(5); const et = buf[o]; const n = buf.readInt32BE(o + 1); o += 5; if (n < 0 || n > NBT_LIMITS.maxNodes) throw new Error("bad list"); const out: Nbt[] = []; for (let i = 0; i < n; i++) { const v = payload(et, depth + 1, keep); if (keep) out.push(v); } return keep ? out : null; }
      case 10: {
        const out: { [k: string]: Nbt } = {};
        for (;;) {
          need(1); const ct = buf[o++];
          if (ct === 0) return keep ? out : null;
          const name = str();
          const v = payload(ct, depth + 1, keep);
          if (keep && name !== "__proto__") out[name] = v;
        }
      }
      default: throw new Error(`unknown NBT tag ${t}`);
    }
  };
  try {
    need(1);
    if (buf[o++] !== 10) return { ok: false, error: "level.dat root is not a compound" };
    str();
    const root = payload(10, 0, true) as { [k: string]: Nbt };
    const data = root?.Data as { [k: string]: Nbt } | undefined;
    const dp = data?.DataPacks as { Enabled?: Nbt; Disabled?: Nbt } | undefined;
    if (!dp) return { ok: false, error: "level.dat has no Data.DataPacks" };
    const list = (v: Nbt | undefined) => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string").slice(0, 1000) : []);
    return { ok: true, enabled: list(dp.Enabled), disabled: list(dp.Disabled) };
  } catch (e) {
    return { ok: false, error: `level.dat unreadable: ${(e as Error).message}` };
  }
}

