// Cyrus server inventory (R2, MASTER-PLAN 4.8 "Server inventory first"): a READ-ONLY, bounded scan of one Minecraft
// server's files through the injectable ReadOnlyServerFs. Writes nothing, runs nothing, never reads secrets into the
// report (server.properties is filtered to an allow-list; rcon/management passwords and the itzg env file are never
// read). Tolerant: every unreadable thing becomes an issue or an `undetermined` line, never an exception.
import { KNOWN_PACK_OWNERS, validateLoaderConfig, LOADER_CONFIG_PATH } from "../packhost/loader-config";
import { indexDatapack, type PackFileRef } from "./datapack";
import { inspectJar } from "./jar";
import { readLevelDatDatapacks } from "./nbt";
import { indexZip, readEntry, findEntry } from "./zipread";
import type { DatapackIndex, InventoryReport, ReadOnlyServerFs, ResourcePackOwner, ServerSoftware } from "./types";

export const INVENTORY_LIMITS = { maxJars: 200, maxJarBytes: 64 * 1024 * 1024, maxTotalBytes: 768 * 1024 * 1024, maxDatapacks: 100, maxDatapackBytes: 64 * 1024 * 1024, maxDirFiles: 5000, maxDirDepth: 10 };

/** server.properties keys the report keeps (version-, gameplay- and resource-pack-relevant). Everything else is counted, never copied. */
export const PROPERTY_ALLOW = [
  "level-name", "level-type", "online-mode", "enforce-secure-profile", "max-players", "gamemode", "difficulty", "hardcore", "pvp", "spawn-protection",
  "view-distance", "simulation-distance", "enable-command-block", "allow-flight", "white-list", "initial-enabled-packs", "initial-disabled-packs",
  "resource-pack", "resource-pack-sha1", "resource-pack-id", "resource-pack-prompt", "require-resource-pack",
] as const;

/** Java .properties, the subset Minecraft writes (`key=value`, `#`/`!` comments, backslash escapes). */
export function parseProperties(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const raw of text.split(/\r?\n/).slice(0, 5000)) {
    const line = raw.trimStart();
    if (!line || line.startsWith("#") || line.startsWith("!")) continue;
    const m = /^((?:\\.|[^=:\\])*?)\s*[=:]\s*(.*)$/.exec(line);
    if (!m) continue;
    const un = (s: string) => s.replace(/\\u([0-9a-fA-F]{4})|\\(.)/g, (_x, u, c) => (u ? String.fromCharCode(parseInt(u, 16)) : c === "n" ? "\n" : c === "t" ? "\t" : c));
    const k = un(m[1]).trim();
    if (k && k !== "__proto__") out[k] = un(m[2]);
  }
  return out;
}

const join = (...p: string[]) => p.join("/").replace(/\/+/g, "/");
const safeSeg = (s: string) => !!s && s !== "." && s !== ".." && !/[\/\\\0]/.test(s);

export function detectSoftware(input: { rootFiles: string[]; versionHistory: string | null; logHead: string | null; hasMods: boolean }): ServerSoftware {
  const sw: ServerSoftware = { name: "unknown", mcVersion: null, build: null, evidence: [] };
  const log = input.logHead ?? "";
  const run = /This server is running (Paper|Purpur|Folia|CraftBukkit|Spigot) version ([^\s(]+)/i.exec(log);
  if (run) {
    const n = run[1].toLowerCase();
    sw.name = (n === "spigot" ? "spigot" : n === "craftbukkit" ? (/Spigot/i.test(run[2]) ? "spigot" : "craftbukkit") : n) as ServerSoftware["name"];
    sw.evidence.push(`log: ${run[0].slice(0, 160)}`);
    const v = /^(\d+\.\d+(?:\.\d+)?)-(\d+)/.exec(run[2]);
    if (v) { sw.mcVersion = v[1]; sw.build = v[2]; }
  }
  const mc = /Starting minecraft server version ([0-9][\w.\-]*)/.exec(log);
  if (mc) { sw.mcVersion = sw.mcVersion ?? mc[1]; sw.evidence.push(`log: ${mc[0]}`); if (sw.name === "unknown") sw.name = "vanilla"; }
  if (input.versionHistory) {
    try {
      const cur = String((JSON.parse(input.versionHistory) as { currentVersion?: unknown }).currentVersion ?? "");
      const m = /\(MC: ([0-9][\w.\-]*)\)/.exec(cur);
      if (m) { sw.mcVersion = sw.mcVersion ?? m[1]; sw.evidence.push(`version_history.json: ${cur.slice(0, 120)}`); }
      const b = /^(\d+\.\d+(?:\.\d+)?)-(\d+)-/.exec(cur) ?? /git-Paper-(\d+)/.exec(cur);
      if (b && !sw.build) sw.build = b[2] ?? b[1];
      if (sw.name === "unknown" && /Paper/i.test(cur)) sw.name = "paper";
      if (sw.name === "unknown" && /Purpur/i.test(cur)) sw.name = "purpur";
    } catch { sw.evidence.push("version_history.json unreadable"); }
  }
  const jar = input.rootFiles.find((f) => /^(paper|purpur|folia|spigot|craftbukkit|fabric-server|forge|neoforge|minecraft_server)[\w.\-]*\.jar$/i.test(f));
  if (jar) {
    sw.evidence.push(`server jar: ${jar}`);
    const n = jar.toLowerCase();
    if (sw.name === "unknown") sw.name = n.startsWith("paper") ? "paper" : n.startsWith("purpur") ? "purpur" : n.startsWith("folia") ? "folia" : n.startsWith("spigot") ? "spigot" : n.startsWith("craftbukkit") ? "craftbukkit" : n.startsWith("fabric") ? "fabric" : n.startsWith("neoforge") ? "neoforge" : n.startsWith("forge") ? "forge" : "vanilla";
    const v = /(\d+\.\d+(?:\.\d+)?)/.exec(jar);
    if (v && !sw.mcVersion) sw.mcVersion = v[1];
  }
  if (input.hasMods && sw.name === "unknown") { sw.name = "fabric"; sw.evidence.push("mods/ folder with jars (modded server; exact loader not determined)"); }
  return sw;
}

/** Recursive, bounded listing of a directory datapack through the read-only fs. */
async function walkDir(fs: ReadOnlyServerFs, dir: string, budget: { files: number }, depth = 0, rel = ""): Promise<string[]> {
  if (depth > INVENTORY_LIMITS.maxDirDepth) return [];
  const out: string[] = [];
  for (const name of (await fs.list(join(dir, rel))).sort()) {
    if (!safeSeg(name) || budget.files <= 0) continue;
    const r = rel ? `${rel}/${name}` : name;
    const st = await fs.stat(join(dir, r));
    if (!st) continue;
    if (st.type === "dir") out.push(...(await walkDir(fs, dir, budget, depth + 1, r)));
    else { budget.files--; out.push(r); }
  }
  return out;
}

export async function scanServer(fs: ReadOnlyServerFs, opts: { base?: string; limits?: Partial<typeof INVENTORY_LIMITS> } = {}): Promise<InventoryReport> {
  const L = { ...INVENTORY_LIMITS, ...(opts.limits ?? {}) };
  const base = (opts.base ?? "/opt/mc").replace(/\/$/, "");
  const rep: InventoryReport = {
    schema: 1, base, software: { name: "unknown", mcVersion: null, build: null, evidence: [] }, plugins: [],
    serverProperties: { present: false, keys: {}, redacted: 0 }, datapacks: { levelName: "world", folder: [], registered: null, issues: [] },
    resourcePackOwners: [], packLoader: { present: false, packs: [], error: null }, bedrock: { geyser: false, floodgate: false },
    limits: { jarsSeen: 0, jarsScanned: 0, bytesRead: 0, truncated: [] }, undetermined: [],
  };
  const read = async (p: string, max: number): Promise<Buffer | null> => {
    if (rep.limits.bytesRead >= L.maxTotalBytes) { rep.limits.truncated.push(`total read budget reached before ${p}`); return null; }
    try {
      const b = await fs.readFile(p, Math.min(max, L.maxTotalBytes - rep.limits.bytesRead));
      if (b) rep.limits.bytesRead += b.length;
      return b;
    } catch { return null; }
  };
  const safeList = async (d: string) => { try { return (await fs.list(d)).filter(safeSeg).sort(); } catch { return []; } };

  // server.properties (allow-listed keys only)
  const propsBuf = await read(join(base, "server.properties"), 256 * 1024);
  const props = propsBuf ? parseProperties(propsBuf.toString("utf8")) : {};
  if (propsBuf) {
    rep.serverProperties.present = true;
    for (const [k, v] of Object.entries(props)) {
      if ((PROPERTY_ALLOW as readonly string[]).includes(k)) rep.serverProperties.keys[k] = v.slice(0, 1000);
      else rep.serverProperties.redacted++;
    }
  } else rep.undetermined.push("server.properties not found or unreadable");

  // software + version
  const rootFiles = await safeList(base);
  const logHead = await read(join(base, "logs/latest.log"), 64 * 1024);
  const vh = await read(join(base, "version_history.json"), 16 * 1024);
  const modsDir = (await safeList(join(base, "mods"))).some((f) => f.toLowerCase().endsWith(".jar"));
  rep.software = detectSoftware({ rootFiles, versionHistory: vh?.toString("utf8") ?? null, logHead: logHead?.toString("utf8") ?? null, hasMods: modsDir });
  if (!rep.software.mcVersion) rep.undetermined.push("Minecraft version not determined (no latest.log, version_history.json or versioned server jar)");
  if (rep.software.name === "unknown") rep.undetermined.push("server software not determined");

  // plugin jars
  const jars = (await safeList(join(base, "plugins"))).filter((f) => f.toLowerCase().endsWith(".jar"));
  rep.limits.jarsSeen = jars.length;
  for (const f of jars) {
    if (rep.plugins.length >= L.maxJars) { rep.limits.truncated.push(`only ${L.maxJars} of ${jars.length} plugin jars scanned`); break; }
    const p = join(base, "plugins", f);
    const st = await fs.stat(p).catch(() => null);
    if (!st || st.type !== "file") continue;
    if (st.size > L.maxJarBytes) { rep.limits.truncated.push(`${f}: ${st.size} bytes is over the ${L.maxJarBytes}-byte scan cap (not scanned)`); continue; }
    const buf = await read(p, L.maxJarBytes);
    if (!buf) { rep.undetermined.push(`${f}: unreadable`); continue; }
    rep.plugins.push(inspectJar(f, `plugins/${f}`, buf));
    rep.limits.jarsScanned++;
  }

  // datapacks in <level>/datapacks + registered ones in level.dat
  const level = props["level-name"] && safeSeg(props["level-name"]) ? props["level-name"] : "world";
  if (props["level-name"] && level !== props["level-name"]) rep.datapacks.issues.push("level-name is not a plain folder name; assumed 'world'");
  rep.datapacks.levelName = level;
  const dpDir = join(base, level, "datapacks");
  for (const name of (await safeList(dpDir)).slice(0, L.maxDatapacks)) {
    const p = join(dpDir, name);
    const st = await fs.stat(p).catch(() => null);
    if (!st) continue;
    let idx: DatapackIndex | null = null;
    if (st.type === "file" && name.toLowerCase().endsWith(".zip")) {
      if (st.size > L.maxDatapackBytes) { rep.datapacks.issues.push(`${name}: over the scan cap`); continue; }
      const buf = await read(p, L.maxDatapackBytes);
      const z = buf ? indexZip(buf) : null;
      if (!z || !z.ok) { rep.datapacks.issues.push(`${name}: ${z && !z.ok ? z.error : "unreadable"}`); continue; }
      const zz = z.zip;
      const mm = findEntry(zz, "pack.mcmeta");
      const rd = (e: (typeof zz.entries)[number]) => { const r = readEntry(zz, e, 256 * 1024); return r.ok ? r.data : null; };
      const files: PackFileRef[] = zz.entries.filter((e) => !e.dir && e.name.startsWith("data/")).map((e) => ({ path: e.name, read: () => rd(e) }));
      idx = await indexDatapack(name, "world", "zip", files, mm ? rd(mm) : null);
      if (zz.unsafeNames.length) idx.issues.push(`unsafe entry names: ${zz.unsafeNames.slice(0, 3).join(", ")}`);
