export const VANILLA_COMMANDS = new Set([
  "advancement", "attribute", "ban", "ban-ip", "banlist", "bossbar", "clear", "clone", "damage", "data", "datapack", "debug", "defaultgamemode", "deop",
  "dialog", "difficulty", "effect", "enchant", "execute", "experience", "xp", "fill", "fillbiome", "forceload", "function", "gamemode", "gamerule", "give",
  "help", "item", "jfr", "kick", "kill", "list", "locate", "loot", "me", "msg", "tell", "w", "op", "pardon", "pardon-ip", "particle", "perf", "place",
  "playsound", "publish", "random", "recipe", "reload", "return", "ride", "rotate", "save-all", "save-off", "save-on", "say", "schedule", "scoreboard",
  "seed", "setblock", "setidletimeout", "setworldspawn", "spawnpoint", "spectate", "spreadplayers", "stop", "stopsound", "summon", "tag", "team",
  "teammsg", "tm", "teleport", "tp", "tellraw", "test", "tick", "time", "title", "transfer", "trigger", "weather", "whitelist", "worldborder", "waypoint",
]);
export const PLATFORM_COMMANDS = new Set(["version", "ver", "about", "plugins", "pl", "timings", "restart", "tps", "paper", "mspt", "spigot", "?", "rl"]);

/** Namespaces that are not owned by any one mod. */
export const SHARED_NAMESPACES = new Set(["minecraft", "c", "forge", "neoforge", "fabric", "paper", "bukkit"]);

/** Function tags that run every pack's entries in pack order. */
export const ORDERED_FUNCTION_TAGS = new Set(["minecraft:load", "minecraft:tick"]);

/** Single-owner resources: two owners is blocking for these (money / permissions), a warning for the rest. */
export const BLOCKING_SINGLE_OWNER = new Set(["economy_provider", "permission_provider"]);

/** Compare dotted versions numerically ("1.21.4" vs "1.21.11", "26.2"). Missing parts count as 0. */
export function cmpVersion(a: string, b: string): number {
  const pa = a.split(/[.\-]/).map((x) => parseInt(x, 10) || 0), pb = b.split(/[.\-]/).map((x) => parseInt(x, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) { const d = (pa[i] ?? 0) - (pb[i] ?? 0); if (d) return d < 0 ? -1 : 1; }
  return 0;
}

