// Pure, deterministic merges for the file types Minecraft lets several packs contribute to. Inputs are ordered from
// LOWEST to HIGHEST priority (like stacked packs: a later input sits on top). Every merge returns the merged value
// plus a list of conflicts; nothing is lost silently.
// Laws (tested with seeded property tests in test/cyrus-conflicts.test.ts):
//  - idempotent: merge([a, a]) == merge([a]) and merge([merge(xs)]) == merge(xs)
//  - no key loss: every key of every input is in the output (tags: every value, unless a replace:true input
//    removes lower ones, which is then reported as a conflict)
//  - order-stable: when a merge reports NO conflicts, any input order gives the same output
//  - deterministic: output object keys are sorted; same inputs, same bytes.
export type MergeConflict = { key: string; kind: "replace" | "differs" | "override" | "invalid" | "codepoint" | "order"; winner: number; detail: string };
export type MergeResult<T> = { value: T; conflicts: MergeConflict[] };

/** Canonical JSON (sorted object keys), for equality and stable output. */
export function canonical(v: unknown): string {
  if (v === null || typeof v !== "object") return JSON.stringify(v) ?? "null";
  if (Array.isArray(v)) return `[${v.map(canonical).join(",")}]`;
  const o = v as Record<string, unknown>;
  return `{${Object.keys(o).filter((k) => o[k] !== undefined).sort().map((k) => `${JSON.stringify(k)}:${canonical(o[k])}`).join(",")}}`;
}
export const sortKeys = <T>(v: T): T => JSON.parse(canonical(v)) as T;
const isObj = (v: unknown): v is Record<string, unknown> => !!v && typeof v === "object" && !Array.isArray(v);
const dedupe = (xs: unknown[]) => { const seen = new Set<string>(); const out: unknown[] = []; for (const x of xs) { const k = canonical(x); if (!seen.has(k)) { seen.add(k); out.push(x); } } return out; };

// ---- sounds.json ------------------------------------------------------------------------------------------------
export type SoundEvent = { sounds: unknown[]; replace?: boolean; subtitle?: string };
export type SoundsJson = Record<string, SoundEvent>;

/** Merge sounds.json files: same event in two inputs -> sounds concatenated (deduped, canonical order); a later
 *  `replace: true` drops the lower inputs' sounds (conflict `replace`); differing subtitles: the later one (conflict). */
export function mergeSoundsJson(inputs: unknown[]): MergeResult<SoundsJson> {
  const out: SoundsJson = {};
  const conflicts: MergeConflict[] = [];
  inputs.forEach((inp, idx) => {
    if (!isObj(inp)) { conflicts.push({ key: "*", kind: "invalid", winner: -1, detail: `input ${idx} is not a JSON object` }); return; }
    for (const key of Object.keys(inp).sort()) {
      const raw = inp[key];
      if (!isObj(raw) || !Array.isArray(raw.sounds)) { conflicts.push({ key, kind: "invalid", winner: -1, detail: `input ${idx}: event has no sounds array` }); continue; }
      const ev: SoundEvent = { sounds: [...raw.sounds] };
      if (raw.replace === true) ev.replace = true;
      if (typeof raw.subtitle === "string") ev.subtitle = raw.subtitle;
      const cur = out[key];
      if (!cur) { out[key] = { ...ev, sounds: dedupe(ev.sounds).sort((a, b) => (canonical(a) < canonical(b) ? -1 : 1)) }; continue; }
      if (ev.replace) {
        const same = canonical(dedupe(ev.sounds).sort((a, b) => (canonical(a) < canonical(b) ? -1 : 1))) === canonical(cur.sounds) && cur.replace === true && cur.subtitle === ev.subtitle;
        if (!same) conflicts.push({ key, kind: "replace", winner: idx, detail: `input ${idx} sets replace:true and drops ${cur.sounds.length} sound(s) from lower inputs` });
        out[key] = { ...ev, sounds: dedupe(ev.sounds).sort((a, b) => (canonical(a) < canonical(b) ? -1 : 1)) };
        continue;
      }
      cur.sounds = dedupe([...cur.sounds, ...ev.sounds]).sort((a, b) => (canonical(a) < canonical(b) ? -1 : 1));
      if (ev.subtitle !== undefined && cur.subtitle !== undefined && ev.subtitle !== cur.subtitle) { conflicts.push({ key, kind: "differs", winner: idx, detail: `subtitle '${cur.subtitle}' vs '${ev.subtitle}'` }); cur.subtitle = ev.subtitle; }
      else if (ev.subtitle !== undefined) cur.subtitle = ev.subtitle;
    }
  });
  return { value: sortKeys(out), conflicts };
}

// ---- lang ---------------------------------------------------------------------------------------------------------
/** Merge lang files (key -> string): union; a key with different strings -> the later input (conflict `differs`). */
export function mergeLang(inputs: unknown[]): MergeResult<Record<string, string>> {
  const out: Record<string, string> = {};
  const conflicts: MergeConflict[] = [];
  inputs.forEach((inp, idx) => {
    if (!isObj(inp)) { conflicts.push({ key: "*", kind: "invalid", winner: -1, detail: `input ${idx} is not a JSON object` }); return; }
    for (const k of Object.keys(inp).sort()) {
      const v = inp[k];
      if (typeof v !== "string") { conflicts.push({ key: k, kind: "invalid", winner: -1, detail: `input ${idx}: value is not a string` }); continue; }
      if (k in out && out[k] !== v) conflicts.push({ key: k, kind: "differs", winner: idx, detail: `'${out[k].slice(0, 60)}' vs '${v.slice(0, 60)}'` });
      out[k] = v;
    }
  });
  return { value: sortKeys(out), conflicts };
}

// ---- tags (datapack tags/<registry>/*.json) ----------------------------------------------------------------------
export type TagJson = { replace?: boolean; values: unknown[] };
const tagId = (v: unknown) => (typeof v === "string" ? v : isObj(v) && typeof v.id === "string" ? v.id : canonical(v));

/** Exactly Minecraft's stacking rule, evaluated in input order: replace:true clears what lower inputs added
 *  (conflict `replace` listing the dropped values), otherwise values are appended (deduped by id, first wins). */
export function mergeTag(inputs: unknown[]): MergeResult<TagJson> {
  let values: unknown[] = [];
  let replace = false;
  const conflicts: MergeConflict[] = [];
  inputs.forEach((inp, idx) => {
    if (!isObj(inp) || !Array.isArray(inp.values)) { conflicts.push({ key: "values", kind: "invalid", winner: -1, detail: `input ${idx} is not a tag` }); return; }
    if (inp.replace === true) {
      const incoming = new Set(inp.values.map(tagId));
      const dropped = values.filter((v) => !incoming.has(tagId(v))).map(tagId);
      if (dropped.length) conflicts.push({ key: "values", kind: "replace", winner: idx, detail: `replace:true drops ${dropped.slice(0, 8).join(", ")}${dropped.length > 8 ? "..." : ""}` });
      values = [];
      replace = true;
    }
    const have = new Set(values.map(tagId));
    for (const v of inp.values) { const id = tagId(v); if (!have.has(id)) { have.add(id); values.push(v); } }
  });
  return { value: replace ? { replace: true, values } : { values }, conflicts };
}

// ---- whole-file JSON (recipes, loot tables, models, blockstates, items...) ---------------------------------------
/** No merge possible: identical inputs collapse; otherwise the highest input wins (conflict `override`). */
export function mergeWholeFile(inputs: unknown[]): MergeResult<unknown> {
  const conflicts: MergeConflict[] = [];
  let value: unknown = inputs[0];
  for (let i = 1; i < inputs.length; i++) {
    if (canonical(inputs[i]) !== canonical(value)) conflicts.push({ key: "file", kind: "override", winner: i, detail: `input ${i} replaces the whole file` });
    value = inputs[i];
  }
  return { value: value === undefined ? value : sortKeys(value), conflicts };
}

// ---- atlases ------------------------------------------------------------------------------------------------------
/** Atlas sources are additive: concatenated, deduped (first occurrence kept). */
export function mergeAtlas(inputs: unknown[]): MergeResult<{ sources: unknown[] }> {
  const conflicts: MergeConflict[] = [];
  const all: unknown[] = [];
  inputs.forEach((inp, idx) => { if (isObj(inp) && Array.isArray(inp.sources)) all.push(...inp.sources); else conflicts.push({ key: "sources", kind: "invalid", winner: -1, detail: `input ${idx} is not an atlas` }); });
  return { value: { sources: dedupe(all).map(sortKeys) }, conflicts };
}

// ---- fonts --------------------------------------------------------------------------------------------------------
/** Font providers are additive; a codepoint provided by two different inputs is reported (conflict `codepoint`). */
export function mergeFont(inputs: unknown[]): MergeResult<{ providers: unknown[] }> {
  const conflicts: MergeConflict[] = [];
  const all: unknown[] = [];
  const owner = new Map<number, number>();
  inputs.forEach((inp, idx) => {
    if (!isObj(inp) || !Array.isArray(inp.providers)) { conflicts.push({ key: "providers", kind: "invalid", winner: -1, detail: `input ${idx} is not a font` }); return; }
    for (const p of inp.providers) {
      all.push(p);
      if (!isObj(p) || !Array.isArray(p.chars)) continue;
      for (const row of p.chars) {
        if (typeof row !== "string") continue;
        for (const ch of row) {
          const cp = ch.codePointAt(0)!;
          if (cp === 0 || cp === 0x20) continue; // padding
          const prev = owner.get(cp);
          if (prev !== undefined && prev !== idx) conflicts.push({ key: `U+${cp.toString(16).toUpperCase().padStart(4, "0")}`, kind: "codepoint", winner: -1, detail: `inputs ${prev} and ${idx} both provide this codepoint` });
          else owner.set(cp, idx);
        }
      }
    }
  });
  const seen = new Set<string>();
  const dedupedConf = conflicts.filter((c) => { const k = `${c.kind}|${c.key}`; if (seen.has(k)) return false; seen.add(k); return true; });
  return { value: { providers: dedupe(all).map(sortKeys) }, conflicts: dedupedConf };
}

