// Resource packs: index (paths + sha1, JSON for mergeable files), per-path class, and the pure composer that turns an
// ORDERED list of packs (lowest priority first) into ONE merged pack, or says why it cannot. Format-aware per file type:
// sounds.json / lang / atlases / fonts merge; pack.mcmeta is written by the composer; everything else is a whole-file
// override where the higher pack wins (the same result stacking would give), reported; shaders never merge.
import { createHash } from "node:crypto";
import { canonical, mergeAtlas, mergeFont, mergeLang, mergeSoundsJson, type MergeConflict } from "./merge";
import type { ResourcePackIndex } from "./types";

export type RpFileClass = "mcmeta" | "pack_png" | "sounds" | "lang" | "atlas" | "font" | "shader" | "whole";
export const RP_LIMITS = { maxFiles: 20_000, maxJsonBytes: 512 * 1024 };

export function rpFileClass(p: string): RpFileClass {
  if (p === "pack.mcmeta") return "mcmeta";
  if (p === "pack.png") return "pack_png";
  if (/^assets\/[^/]+\/sounds\.json$/.test(p)) return "sounds";
  if (/^assets\/[^/]+\/lang\/[^/]+\.json$/.test(p)) return "lang";
  if (/^assets\/[^/]+\/atlases\/.+\.json$/.test(p)) return "atlas";
  if (/^assets\/[^/]+\/font\/.+\.json$/.test(p)) return "font";
  if (/^assets\/[^/]+\/shaders\//.test(p)) return "shader";
  return "whole";
}
const MERGEABLE = new Set<RpFileClass>(["mcmeta", "sounds", "lang", "atlas", "font"]);

const sha1 = (b: Buffer) => createHash("sha1").update(b).digest("hex");
function parseJson(b: Buffer): unknown { try { return JSON.parse(b.toString("utf8").replace(/^﻿/, "")); } catch { return undefined; } }

export function indexResourcePack(name: string, files: { path: string; data: Buffer }[]): ResourcePackIndex {
  const idx: ResourcePackIndex = { name, bytes: 0, files: [], json: {}, issues: [] };
  const sorted = [...files].sort((a, b) => (a.path < b.path ? -1 : 1));
  if (sorted.length > RP_LIMITS.maxFiles) idx.issues.push(`only the first ${RP_LIMITS.maxFiles} files were indexed`);
  for (const f of sorted.slice(0, RP_LIMITS.maxFiles)) {
    idx.bytes += f.data.length;
    idx.files.push({ path: f.path, sha1: sha1(f.data) });
    const c = rpFileClass(f.path);
    if (MERGEABLE.has(c) && f.path.endsWith(".json") || c === "mcmeta") {
      if (f.data.length > RP_LIMITS.maxJsonBytes) { idx.issues.push(`${f.path}: too large to inspect`); continue; }
      const j = parseJson(f.data);
      if (j === undefined) idx.issues.push(`${f.path}: invalid JSON`);
      else idx.json[f.path] = j;
    }
  }
  if (!idx.files.some((f) => f.path === "pack.mcmeta")) idx.issues.push("pack.mcmeta missing");
  return idx;
}

export type ComposeInput = { name: string; files: { path: string; data: Buffer }[] };
export type ComposeResult = {
  ok: boolean;
  files: { path: string; data: Buffer }[];
  /** path -> which input won and why. */
  conflicts: { path: string; cls: RpFileClass; conflicts: MergeConflict[]; inputs: string[] }[];
  /** Files that cannot be merged into one pack (shaders from more than one input). Non-empty -> ok:false. */
  unmergeable: { path: string; inputs: string[] }[];
};

/** Compose one pack. `packMcmeta` is the composer's own pack.mcmeta (format from the version registry). */
export function composeResourcePacks(inputs: ComposeInput[], packMcmeta: Record<string, unknown>): ComposeResult {
  const byPath = new Map<string, { input: number; data: Buffer }[]>();
  inputs.forEach((inp, i) => { for (const f of inp.files) { if (!byPath.has(f.path)) byPath.set(f.path, []); byPath.get(f.path)!.push({ input: i, data: f.data }); } });
  const res: ComposeResult = { ok: true, files: [], conflicts: [], unmergeable: [] };
  const shaderInputs = new Set<number>();
  for (const [p, list] of byPath) if (rpFileClass(p) === "shader") for (const l of list) shaderInputs.add(l.input);
  if (shaderInputs.size > 1) {
    for (const [p, list] of byPath) if (rpFileClass(p) === "shader") res.unmergeable.push({ path: p, inputs: [...new Set(list.map((l) => inputs[l.input].name))] });
  }
  for (const p of [...byPath.keys()].sort()) {
    const list = byPath.get(p)!;
    const cls = rpFileClass(p);
    const names = list.map((l) => inputs[l.input].name);
    if (cls === "mcmeta") continue;
    if (list.length === 1 || list.every((l) => l.data.equals(list[0].data))) { res.files.push({ path: p, data: list[list.length - 1].data }); continue; }
    if (cls === "sounds" || cls === "lang" || cls === "atlas" || cls === "font") {
      const parsed = list.map((l) => parseJson(l.data));
      const m = cls === "sounds" ? mergeSoundsJson(parsed) : cls === "lang" ? mergeLang(parsed) : cls === "atlas" ? mergeAtlas(parsed) : mergeFont(parsed);
      res.files.push({ path: p, data: Buffer.from(JSON.stringify(m.value, null, 2) + "\n") });
      if (m.conflicts.length) res.conflicts.push({ path: p, cls, conflicts: m.conflicts.map((c) => ({ ...c, detail: c.winner >= 0 ? `${c.detail} (winner: ${names[c.winner]})` : c.detail })), inputs: names });
      continue;
    }
    // whole-file (and pack.png): highest input wins, like stacking
    const top = list[list.length - 1];
    res.files.push({ path: p, data: top.data });
    res.conflicts.push({ path: p, cls, conflicts: [{ key: p, kind: "override", winner: list.length - 1, detail: `${inputs[top.input].name} wins over ${names.slice(0, -1).join(", ")}` }], inputs: names });
  }
  res.files.push({ path: "pack.mcmeta", data: Buffer.from(JSON.stringify(JSON.parse(canonical(packMcmeta)), null, 2) + "\n") });
  res.files.sort((a, b) => (a.path < b.path ? -1 : 1));
  res.ok = res.unmergeable.length === 0;
  return res;
}

