// Cyrus static conflict engine (R2). PURE and DETERMINISTIC: same mods + context -> byte-identical report (mods are
// sorted by id first, findings sorted by severity/class/subject, ids are hashes of class+subject+mods).
// Each detector below is one conflict class from MASTER-PLAN 4.8 / GAPS section D, with its severity rule and a
// resolution suggestion. Data a detector needs but does not have (no bytecode summary, unknown server version) is
// listed in `notChecked`: not checked is never reported as clean.
import { createHash } from "node:crypto";
import { getVersion, hasCapability } from "../versions/registry";
import { canonical } from "./merge";
import { rpFileClass } from "./resourcepack";
import { BLOCKING_SINGLE_OWNER, cmpVersion, ORDERED_FUNCTION_TAGS, PLATFORM_COMMANDS, SHARED_NAMESPACES, VANILLA_COMMANDS } from "./vanilla";
import type { ConflictClass, ConflictContext, ConflictReport, Finding, FindingItem, ModEntry, Resolution, Severity } from "./types";

export const DEFAULT_BUDGETS = { maxDisplayEntities: 1000, maxRepeatingTasks: 64, maxPackBytes: 100 * 1024 * 1024 };
const SEV_ORDER: Record<Severity, number> = { blocking: 0, warn: 1, info: 2 };

const fid = (cls: string, subject: string, mods: string[]) => createHash("sha1").update(`${cls}|${subject}|${[...new Set(mods)].sort().join(",")}`).digest("hex").slice(0, 12);
const res = (kind: Resolution["kind"], auto: boolean, text: string, proposal?: Record<string, unknown>): Resolution => (proposal ? { kind, auto, text, proposal } : { kind, auto, text });
const USER = (text = "cannot resolve automatically: user decision (keep one, or accept the overlap)") => res("user_decision", false, text);

/** Short, readable prefix for alias rewrites: the 8 random chars of a Cyrus namespace (`nx_ab12cd34` -> `ab12`). */
const nsShort = (ns: string) => ns.replace(/^nx_/, "").slice(0, 4);

class Collector {
  findings = new Map<string, Finding>();
  add(cls: ConflictClass, severity: Severity, subject: string, items: FindingItem[], message: string, resolution: Resolution) {
    const id = fid(cls, subject, items.map((i) => i.mod));
    const sorted = [...items].sort((a, b) => (a.mod < b.mod ? -1 : a.mod > b.mod ? 1 : a.evidence < b.evidence ? -1 : 1));
    if (!this.findings.has(id)) this.findings.set(id, { id, class: cls, severity, subject, items: sorted, message, resolution });
  }
}

type Group<T> = Map<string, { mod: ModEntry; v: T }[]>;
function group<T>(entries: { key: string; mod: ModEntry; v: T }[]): Group<T> {
  const g: Group<T> = new Map();
  for (const e of entries) { if (!g.has(e.key)) g.set(e.key, []); g.get(e.key)!.push({ mod: e.mod, v: e.v }); }
  return g;
}
const distinctMods = <T>(xs: { mod: ModEntry; v: T }[]) => new Set(xs.map((x) => x.mod.id)).size;
const item = (m: ModEntry, evidence: string): FindingItem => ({ mod: m.id, label: m.label, evidence });

export function detectConflicts(input: readonly ModEntry[], ctx: ConflictContext = {}): ConflictReport {
  const mods = [...input].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const C = new Collector();
  const notChecked: string[] = [];
  const plugins = mods.filter((m) => m.kind === "plugin" && m.plugin);
  const desc = (m: ModEntry) => m.plugin?.descriptor ?? null;
  const bc = (m: ModEntry) => m.plugin?.bytecode ?? null;
  for (const m of plugins) {
    if (!desc(m)) notChecked.push(`${m.label}: no plugin descriptor, so names, commands, permissions and dependencies were not checked`);
    if (!bc(m)) notChecked.push(`${m.label}: no bytecode summary, so events, keys, item models, recipes, sounds and single-owner resources were not checked`);
  }

  // ---- policy + jar safety ------------------------------------------------------------------------------------
  for (const m of mods) {
    const f = m.plugin?.jarFlags;
    if (m.kind === "serverjar" || f?.serverJar) {
      C.add("policy.server_jar", ctx.modPack ? "blocking" : "warn", m.label, [item(m, f?.serverJarEvidence ?? "declared as a server jar")],
        ctx.modPack ? "A Mod Pack may never contain a Minecraft or Paper server jar." : "A server jar sits in the plugins folder; Paper cannot load it as a plugin.",
        res("remove_one", false, "Remove the server jar from the pack; the server software is installed by Nxeon, never shipped in a pack."));
    }
    if (f && (f.unsafeNames.length || f.bombEntries.length || f.unreadable)) {
      const ev = [f.unreadable && `unreadable: ${f.unreadable}`, f.unsafeNames.length && `unsafe entry names: ${f.unsafeNames.slice(0, 3).join(", ")}`, f.bombEntries.length && `refused entries (size/ratio): ${f.bombEntries.slice(0, 3).join(", ")}`].filter(Boolean).join("; ");
      C.add("safety.jar_flags", ctx.modPack ? "blocking" : "warn", m.label, [item(m, ev)], "This jar is malformed or carries entries a normal plugin never has.", res("remove_one", false, "Do not install this jar; get a clean build from its author."));
    }
  }

  // ---- plugin identity ----------------------------------------------------------------------------------------
  const byName = group(plugins.filter((m) => desc(m)?.name).map((m) => ({ key: desc(m)!.name!.toLowerCase(), mod: m, v: desc(m)!.name! })));
  for (const [name, xs] of byName) if (xs.length > 1)
    C.add("plugin.duplicate_name", "blocking", name, xs.map((x) => item(x.mod, `plugin.yml name: ${x.v} ${desc(x.mod)!.version ?? ""}`.trim())), `Two jars declare the plugin name '${xs[0].v}'. Paper loads only one of them.`,
      res("remove_one", false, "Keep one copy (usually the newer version) and remove the other.", { keepOneOf: xs.map((x) => x.mod.id) }));
  const byMain = group(plugins.filter((m) => desc(m)?.main).map((m) => ({ key: desc(m)!.main!, mod: m, v: desc(m)!.name ?? "" })));
  for (const [main, xs] of byMain) if (xs.length > 1 && new Set(xs.map((x) => x.v.toLowerCase())).size > 1)
    C.add("plugin.duplicate_main", "warn", main, xs.map((x) => item(x.mod, `main: ${main} (name ${x.v})`)), "Two differently named plugins share one main class: probably the same plugin twice (renamed), or a copied template.", res("remove_one", false, "Check whether these are the same plugin; keep one."));

  // ---- commands -----------------------------------------------------------------------------------------------
  type Cmd = { kind: "label" | "alias" | "brigadier"; label: string };
  const cmds: { key: string; mod: ModEntry; v: Cmd }[] = [];
  for (const m of plugins) {
    for (const c of desc(m)?.commands ?? []) {
      cmds.push({ key: c.name, mod: m, v: { kind: "label", label: c.name } });
      for (const a of c.aliases) cmds.push({ key: a, mod: m, v: { kind: "alias", label: c.name } });
    }
    for (const r of bc(m)?.brigadierRoots ?? []) cmds.push({ key: r, mod: m, v: { kind: "brigadier", label: r } });
  }
  for (const [key, xs0] of group(cmds)) {
    // one mod declaring the same name twice (label + alias of itself) is not a collision
    const perMod = new Map<string, { mod: ModEntry; v: Cmd }>();
    for (const x of xs0) { const cur = perMod.get(x.mod.id); if (!cur || (cur.v.kind === "alias" && x.v.kind !== "alias")) perMod.set(x.mod.id, x); }
    const xs = [...perMod.values()];
    const ev = (x: { mod: ModEntry; v: Cmd }) => item(x.mod, x.v.kind === "alias" ? `alias /${key} of /${x.v.label}` : x.v.kind === "brigadier" ? `Brigadier root /${key} (bytecode)` : `command /${key} (plugin.yml)`);
    if (VANILLA_COMMANDS.has(key) || PLATFORM_COMMANDS.has(key)) {
      const vanilla = VANILLA_COMMANDS.has(key);
      C.add("command.vanilla_override", vanilla ? "warn" : "info", `/${key}`, xs.map(ev), vanilla ? `/${key} replaces the vanilla command (players then get the plugin's version; /minecraft:${key} still reaches vanilla).` : `/${key} replaces a server platform command.`,
        xs.some((x) => x.mod.cyrus) ? res("alias_rewrite", false, `Rename the Cyrus mod's /${key} (rebuild needed).`, { rewrites: xs.filter((x) => x.mod.cyrus).map((x) => ({ mod: x.mod.id, from: key, to: `${nsShort(x.mod.cyrus!.namespace)}${key}` })) }) : res("none", false, "Usually intended (e.g. an essentials plugin); review."));
    }
    if (xs.length < 2) continue;
    const labels = xs.filter((x) => x.v.kind !== "alias");
    const cls: ConflictClass = labels.length >= 1 ? "command.label_collision" : "command.alias_collision";
    const sev: Severity = labels.length >= 1 ? "warn" : "info";
    const rewrites = xs.filter((x) => x.mod.cyrus).map((x) => ({ mod: x.mod.id, from: key, to: `${nsShort(x.mod.cyrus!.namespace)}${key}` }));
    C.add(cls, sev, `/${key}`, xs.map(ev), labels.length >= 1 ? `/${key} is claimed by ${xs.length} plugins; only one answers /${key}, the others only as /<plugin>:${key}.` : `Alias /${key} is claimed by ${xs.length} plugins; one alias is shadowed.`,
      rewrites.length ? res("alias_rewrite", false, `Rewrite the Cyrus mod's command so the names no longer overlap (rebuild needed): ${rewrites.map((r) => `/${r.from} -> /${r.to}`).join(", ")}.`, { rewrites }) : USER("cannot resolve automatically: user decision (pick which plugin keeps /" + key + "; the other stays reachable as /<plugin>:" + key + ")"));
  }

  // ---- permissions --------------------------------------------------------------------------------------------
  const perms = group(plugins.flatMap((m) => (desc(m)?.permissions ?? []).map((p) => ({ key: p.name, mod: m, v: p }))));
  for (const [name, xs] of perms) {
    if (distinctMods(xs) < 2) continue;
    C.add("permission.duplicate", "warn", name, xs.map((x) => item(x.mod, `defines ${name} (default ${x.v.default})`)), `${xs.length} plugins define the permission ${name}; Paper keeps the first definition and logs a warning for the next.`,
      xs.some((x) => x.mod.cyrus) ? res("reserved_namespace", false, "Cyrus mods should define permissions under their own namespace (nx_xxx.*); rebuild the Cyrus mod with a namespaced node.") : USER());
    const defaults = new Set(xs.map((x) => x.v.default));
    if (defaults.size > 1) C.add("permission.default_mismatch", "warn", name, xs.map((x) => item(x.mod, `default: ${x.v.default}${x.v.explicitDefault ? "" : " (implicit)"}`)), `${name} has different defaults (${[...defaults].join(" vs ")}); who gets it depends on load order.`, USER("cannot resolve automatically: user decision (set the default explicitly in a permissions plugin such as LuckPerms)"));
  }

  // ---- dependencies (DAG) -------------------------------------------------------------------------------------
  const present = new Set<string>();
  for (const m of plugins) { const d = desc(m); if (d?.name) present.add(d.name.toLowerCase()); for (const p of d?.provides ?? []) present.add(p.toLowerCase()); }
  for (const m of plugins) {
    const d = desc(m);
    if (!d) continue;
    for (const dep of d.depend) if (!present.has(dep.toLowerCase()))
      C.add("dependency.missing", "blocking", `${d.name ?? m.label} -> ${dep}`, [item(m, `depend: ${dep}`)], `${d.name ?? m.label} needs ${dep}, which is not installed; Paper will not enable it.`, res("upgrade_or_replace", false, `Add ${dep} to the pack/server, or remove ${d.name ?? m.label}.`, { add: dep }));
    for (const dep of d.softdepend) if (!present.has(dep.toLowerCase()))
      C.add("dependency.missing", "info", `${d.name ?? m.label} -> ${dep} (optional)`, [item(m, `softdepend: ${dep}`)], `${d.name ?? m.label} can use ${dep} (optional, not installed).`, res("none", false, "Nothing to do unless the optional feature is wanted."));
  }
  // hard edges: A depends on B => B before A. loadbefore: A loadbefore B => A before B. softdepend: B before A (if present).
  const nameOf = new Map(plugins.filter((m) => desc(m)?.name).map((m) => [desc(m)!.name!.toLowerCase(), m]));
  const cycles = (edges: Map<string, Set<string>>) => {
    const out: string[][] = [];
    const state = new Map<string, number>();
    const stack: string[] = [];
    const visit = (n: string) => {
      state.set(n, 1); stack.push(n);
      for (const t of [...(edges.get(n) ?? [])].sort()) {
        if (state.get(t) === 1) out.push(stack.slice(stack.indexOf(t)));
        else if (!state.get(t)) visit(t);
      }
      stack.pop(); state.set(n, 2);
    };
    for (const n of [...edges.keys()].sort()) if (!state.get(n)) visit(n);
    return out;
  };
  const hard = new Map<string, Set<string>>(), all = new Map<string, Set<string>>();
  const edge = (m: Map<string, Set<string>>, a: string, b: string) => { if (!m.has(a)) m.set(a, new Set()); m.get(a)!.add(b); };
  for (const m of plugins) {
    const d = desc(m);
    if (!d?.name) continue;
    const me = d.name.toLowerCase();
    for (const dep of d.depend) if (nameOf.has(dep.toLowerCase())) { edge(hard, me, dep.toLowerCase()); edge(all, me, dep.toLowerCase()); }
    for (const dep of d.softdepend) if (nameOf.has(dep.toLowerCase())) edge(all, me, dep.toLowerCase());
    for (const lb of d.loadbefore) if (nameOf.has(lb.toLowerCase())) edge(all, lb.toLowerCase(), me);
  }
  const hardCycles = cycles(hard);
  for (const cy of hardCycles) C.add("dependency.cycle", "blocking", cy.join(" -> "), cy.map((n) => item(nameOf.get(n)!, `depends on ${[...(hard.get(n) ?? [])].filter((t) => cy.includes(t)).join(", ")}`)), `Circular hard dependency (${cy.join(" -> ")} -> ${cy[0]}); Paper refuses to load these plugins.`, USER("cannot resolve automatically: user decision (one of these plugins must drop the dependency; ask its author)"));
  const hardKeys = new Set(hardCycles.map((c) => [...c].sort().join(",")));
  for (const cy of cycles(all)) if (!hardKeys.has([...cy].sort().join(",")))
    C.add("dependency.loadbefore_cycle", "warn", cy.join(" -> "), cy.map((n) => item(nameOf.get(n)!, "softdepend/loadbefore edge")), `Load-order loop through softdepend/loadbefore (${cy.join(" -> ")}); Paper breaks it arbitrarily.`, res("load_order", false, "Remove one loadbefore/softdepend edge so the order is defined."));

  // ---- platform -----------------------------------------------------------------------------------------------
  const mc = ctx.mcVersion ?? null;
  const row = mc ? getVersion(mc) : null;
  const javaRel = ctx.javaRelease ?? row?.javaRelease ?? null;
  const folia = (ctx.software ?? "").toLowerCase() === "folia";
  if (!mc) notChecked.push("server Minecraft version unknown: api-version, Java and item-model version checks were not run");
  for (const m of plugins) {
    const d = desc(m), b = bc(m);
    if (mc && d?.apiVersion && /^\d+\.\d+/.test(d.apiVersion) && cmpVersion(d.apiVersion, mc) > 0)
      C.add("platform.api_version", "blocking", `${d.name ?? m.label} api-version ${d.apiVersion}`, [item(m, `api-version: ${d.apiVersion}; server ${mc}`)], `${d.name ?? m.label} is built for Minecraft ${d.apiVersion} or newer; this server runs ${mc}, so Paper refuses to load it.`, res("upgrade_or_replace", false, `Use a build of ${d.name ?? m.label} for ${mc}, or update the server.`));
    if (javaRel && b?.javaRelease && b.javaRelease > javaRel)
      C.add("platform.java", "blocking", `${d?.name ?? m.label} Java ${b.javaRelease}`, [item(m, `class files need Java ${b.javaRelease} (major ${b.maxClassMajor}); server runs Java ${javaRel}`)], `${d?.name ?? m.label} needs Java ${b.javaRelease}; this server runs Java ${javaRel}.`, res("upgrade_or_replace", false, "Use a build compiled for the server's Java release."));
    if (folia && d && !d.foliaSupported)
      C.add("platform.folia", "blocking", `${d.name ?? m.label} on Folia`, [item(m, "plugin.yml has no folia-supported: true")], `${d.name ?? m.label} does not declare Folia support; Folia will not load it.`, res("upgrade_or_replace", false, "Use a Folia-compatible build, or run Paper."));
    if (d?.foliaSupported && b && b.bukkitSchedulerSites > 0)
      C.add("platform.folia", "warn", `${d.name ?? m.label} Bukkit scheduler`, [item(m, `${b.bukkitSchedulerSites} BukkitScheduler call site(s) despite folia-supported: true`)], `${d.name ?? m.label} claims Folia support but uses the Bukkit scheduler, which throws on Folia.`, res("upgrade_or_replace", false, "Use the region/entity/global schedulers."));
    if (mc && b?.usesItemModelApi && getVersion(mc) && !hasCapability(mc, "itemModelDefinitions"))
      C.add("platform.item_model_version", "blocking", `${d?.name ?? m.label} item_model`, [item(m, "calls setItemModel / the ITEM_MODEL data component")], `${d?.name ?? m.label} uses item models, which need Minecraft 1.21.4+; this server runs ${mc}.`, res("upgrade_or_replace", false, "Update the server to 1.21.4 or newer."));
  }

  // ---- events -------------------------------------------------------------------------------------------------
  const ev = group(plugins.flatMap((m) => (bc(m)?.events ?? []).map((e) => ({ key: `${e.event}@${e.priority}`, mod: m, v: e }))));
  for (const [key, xs] of ev) {
    const writers = xs.filter((x) => x.v.mutates || x.v.cancels);
    if (new Set(writers.map((w) => w.mod.id)).size >= 2)
      C.add("event.overlap", "warn", key, writers.map((w) => item(w.mod, `${w.v.where} ${w.v.cancels ? "cancels" : "changes"} ${w.v.event.split(".").pop()} at ${w.v.priority}${w.v.ignoreCancelled ? " (ignoreCancelled)" : ""}`)),
        `${new Set(writers.map((w) => w.mod.id)).size} plugins change or cancel ${key.split("@")[0].split(".").pop()} at the same priority (${key.split("@")[1]}); the result depends on plugin load order.`, res("load_order", false, "Move one handler to a different EventPriority (rebuild for a Cyrus mod), or define the load order with loadbefore."));
    for (const x of xs) if (x.v.priority === "MONITOR" && (x.v.mutates || x.v.cancels))
      C.add("event.monitor_mutation", "warn", `${key} ${x.mod.id}`, [item(x.mod, `${x.v.where} changes the event at MONITOR`)], "A MONITOR handler changes the event; MONITOR is meant for observing only, so every other plugin already decided.", res("load_order", false, "Use HIGHEST instead of MONITOR for handlers that change the event."));
  }

  // ---- keys, item models, custom_model_data, recipes, sounds -------------------------------------------------
  const keyGroups: { cls: ConflictClass; label: string; get: (m: ModEntry) => { key: string; where: string }[] }[] = [
    { cls: "key.namespacedkey", label: "NamespacedKey / PDC key", get: (m) => bc(m)?.namespacedKeys.filter((k) => !k.key.startsWith("minecraft:")) ?? [] },
    { cls: "item.item_model", label: "item_model key", get: (m) => bc(m)?.itemModels ?? [] },
    { cls: "recipe.key", label: "recipe key", get: (m) => bc(m)?.recipes ?? [] },
  ];
  for (const g of keyGroups) {
    for (const [key, xs] of group(plugins.flatMap((m) => g.get(m).map((k) => ({ key: k.key, mod: m, v: k.where }))))) {
      if (distinctMods(xs) < 2) continue;
      const uniq = [...new Map(xs.map((x) => [x.mod.id, x])).values()];
      const sev: Severity = g.cls === "recipe.key" ? "warn" : "warn";
      C.add(g.cls, sev, key, uniq.map((x) => item(x.mod, `${g.label} ${key} in ${x.v}`)), g.cls === "recipe.key" ? `Two plugins register the recipe ${key}; the second registration is refused.` : g.cls === "item.item_model" ? `Two plugins use the item model ${key}; their items look the same and one pack's model wins.` : `Two plugins use the key ${key}; they read and overwrite each other's stored data.`,
        uniq.some((x) => x.mod.cyrus) ? res("reserved_namespace", false, "Cyrus mods keep their keys under their reserved namespace; rebuild the Cyrus mod so the key moves under it.") : USER());
    }
  }
  for (const m of plugins) {
    if (!m.cyrus) continue;
    const own = m.cyrus.namespace;
    for (const k of [...(bc(m)?.namespacedKeys ?? []), ...(bc(m)?.itemModels ?? []), ...(bc(m)?.soundKeys ?? [])]) {
      const ns = k.key.split(":")[0];
      if (ns !== own && /^nx_[a-z0-9]{8}$/.test(ns))
        C.add("key.namespace_foreign", "warn", `${m.id} ${k.key}`, [item(m, `${k.key} in ${k.where}`)], `This Cyrus mod uses ${k.key}, which belongs to another Cyrus project's reserved namespace.`, res("reserved_namespace", false, `Rebuild so the key uses ${own}.`));
    }
  }
  const cmd = group(plugins.flatMap((m) => (bc(m)?.customModelData ?? []).map((n) => ({ key: String(n), mod: m, v: n }))));
  for (const [n, xs] of cmd) if (distinctMods(xs) >= 2)
    C.add("item.custom_model_data", "warn", `custom_model_data ${n}`, xs.map((x) => item(x.mod, `setCustomModelData(${n})`)), `custom_model_data ${n} is used by ${distinctMods(xs)} plugins; on the same base item they show the same model (legacy 1.21.1-style models).`,
      xs.some((x) => x.mod.cyrus) ? res("reserved_namespace", false, "Cyrus mods use item_model keys in their own namespace (1.21.4+), never bare integers; rebuild on 1.21.4+.") : USER());

  // ---- single-owner resources --------------------------------------------------------------------------------
  const so = group(plugins.flatMap((m) => (bc(m)?.singleOwner ?? []).map((s) => ({ key: s.resource, mod: m, v: s }))));
  for (const [resource, xs] of so) {
    if (distinctMods(xs) < 2) continue;
    const uniq = [...new Map(xs.map((x) => [x.mod.id, x])).values()];
    C.add("resource.single_owner", BLOCKING_SINGLE_OWNER.has(resource) ? "blocking" : "warn", resource, uniq.map((x) => item(x.mod, `${x.v.evidence} (${x.v.where})`)),
      `${uniq.length} plugins want to own the ${resource.replace(/_/g, " ")}; only one can (${BLOCKING_SINGLE_OWNER.has(resource) ? "two providers split balances/permissions" : "they overwrite each other"}).`, USER(`cannot resolve automatically: user decision (keep one ${resource.replace(/_/g, " ")} owner)`));
  }

  // ---- datapacks ---------------------------------------------------------------------------------------------
  const dps = mods.filter((m) => m.datapack);
  const ids = group(dps.flatMap((m) => m.datapack!.files.filter((f) => !f.type.startsWith("tags/")).map((f) => ({ key: `${f.type} ${f.id}`, mod: m, v: f }))));
  for (const [key, xs] of ids) {
    const n = distinctMods(xs);
    const vanilla = xs[0].v.id.startsWith("minecraft:");
    if (vanilla && n === 1) C.add("datapack.vanilla_override", "info", key, xs.map((x) => item(x.mod, `overrides ${x.v.id}`)), `${xs[0].mod.label} replaces the vanilla ${xs[0].v.type} ${xs[0].v.id}.`, res("none", false, "Intended override; nothing to do."));
    else if (vanilla && n > 1) C.add("datapack.vanilla_override", "warn", key, xs.map((x) => item(x.mod, `overrides ${x.v.id}`)), `${n} datapacks replace the vanilla ${xs[0].v.type} ${xs[0].v.id}; only the last enabled pack's version is used.`, res("stacking_order", false, "The pack enabled last wins; choose the order (or keep one override).", { order: xs.map((x) => x.mod.id) }));
    else if (n > 1) C.add("datapack.id_collision", "warn", key, xs.map((x) => item(x.mod, `defines ${x.v.id}`)), `${n} datapacks define ${xs[0].v.type} ${xs[0].v.id}; the last enabled pack wins.`, xs.some((x) => x.mod.cyrus) ? res("reserved_namespace", false, "Cyrus datapacks write under their reserved namespace; rebuild the Cyrus pack.") : res("stacking_order", false, "The pack enabled last wins; choose the order."));
  }
  const tags = group(dps.flatMap((m) => m.datapack!.tags.map((t) => ({ key: `${t.registry} ${t.id}`, mod: m, v: t }))));
  for (const [key, xs] of tags) {
    const replacers = xs.filter((x) => x.v.replace);
    const n = distinctMods(xs);
    if (replacers.length && (n > 1 || xs[0].v.id.startsWith("minecraft:")))
      C.add("datapack.tag_replace", "warn", key, xs.map((x) => item(x.mod, `${x.v.replace ? "replace: true, " : ""}${x.v.values.length} value(s)`)), `A replace:true tag (${key}) wipes the entries ${n > 1 ? "other packs" : "vanilla"} add to it.`, res("merge", true, "The Mod Pack builder can merge the tag files in pack order (replace semantics kept and reported); otherwise ask the author to use replace:false."));
    const fn = xs[0].v.registry.startsWith("function") ? xs[0].v.id : "";
    if (ORDERED_FUNCTION_TAGS.has(fn) && n > 1)
      C.add("datapack.function_tag_order", "info", key, xs.map((x) => item(x.mod, `adds ${x.v.values.join(", ").slice(0, 120)}`)), `${n} datapacks add functions to #${fn}; they run in pack order.`, res("stacking_order", true, "Pack order decides; the Mod Pack keeps its member order."));
  }

  // ---- resource packs ----------------------------------------------------------------------------------------
  const rps = mods.filter((m) => m.resourcePack);
  const paths = group(rps.flatMap((m) => m.resourcePack!.files.map((f) => ({ key: f.path, mod: m, v: f.sha1 }))));
  const shaderMods = new Set<string>();
  for (const [p, xs] of paths) {
    if (distinctMods(xs) < 2) continue;
    const cls = rpFileClass(p);
    const same = new Set(xs.map((x) => x.v)).size === 1;
    if (cls === "mcmeta") { C.add("rp.pack_mcmeta", "info", p, xs.map((x) => item(x.mod, "pack.mcmeta")), "Every pack has its own pack.mcmeta.", res("merge", true, "The Mod Pack writes one pack.mcmeta with the format from the version registry.")); continue; }
    if (cls === "shader") { for (const x of xs) shaderMods.add(x.mod.id); if (!same) C.add("rp.shader", "warn", p, xs.map((x) => item(x.mod, `ships ${p}`)), `${distinctMods(xs)} packs override the shader ${p}; shaders cannot be merged.`, USER("cannot resolve: user decision (keep one shader pack)")); continue; }
    if (same) continue;
    if (cls === "sounds") {
      const merged = rps.filter((m) => xs.some((x) => x.mod.id === m.id)).map((m) => m.resourcePack!.json[p]);
      const keys = merged.map((j) => (j && typeof j === "object" ? Object.keys(j as object) : []));
      const overlap = keys.flat().filter((k, i, a) => a.indexOf(k) !== i);
      C.add("rp.sounds_json", overlap.length ? "warn" : "info", p, xs.map((x) => item(x.mod, `sounds.json (${Object.keys((rps.find((m) => m.id === x.mod.id)!.resourcePack!.json[p] as object) ?? {}).length} events)`)),
        overlap.length ? `Both packs define sound events ${[...new Set(overlap)].slice(0, 5).join(", ")} in ${p}.` : `Two packs ship ${p} with different events; Minecraft keeps only the top pack's file unless merged.`,
        res("merge", true, "Merged by the Mod Pack builder: events unioned, sounds concatenated; replace:true and subtitle differences are reported."));
      continue;
    }
    if (cls === "lang") { C.add("rp.lang", "info", p, xs.map((x) => item(x.mod, p)), `Two packs ship ${p}.`, res("merge", true, "Merged by key; a key with different text: the later member wins (reported).")); continue; }
    if (cls === "atlas") { C.add("rp.atlas", "info", p, xs.map((x) => item(x.mod, p)), `Two packs ship the atlas ${p}.`, res("merge", true, "Atlas sources are concatenated by the Mod Pack builder.")); continue; }
    if (cls === "font") continue; // handled per codepoint below
    C.add("rp.whole_file", "warn", p, xs.map((x) => item(x.mod, `${p} sha1 ${x.v.slice(0, 10)}`)), `${distinctMods(xs)} packs replace ${p} with different files; only one can show.`,
      res("stacking_order", true, "The higher pack wins (Mod Pack member order; the same rule as Pack Loader stacking). Change the member order to pick the other.", { order: xs.map((x) => x.mod.id) }));
  }
  // vanilla sound events touched by sounds.json
  for (const m of rps) for (const [p, j] of Object.entries(m.resourcePack!.json)) {
    if (rpFileClass(p) !== "sounds" || !j || typeof j !== "object") continue;
    const ns = p.split("/")[1];
    for (const [k, v] of Object.entries(j as Record<string, { replace?: unknown }>)) {
      if (ns === "minecraft") C.add("sound.vanilla_replace", v && v.replace === true ? "warn" : "info", `minecraft:${k}`, [item(m, `${p} ${k}${v?.replace === true ? " replace:true" : ""}`)], v && v.replace === true ? `Replaces the vanilla sound minecraft:${k} for everything that plays it.` : `Adds variants to the vanilla sound minecraft:${k}.`, res("none", false, v?.replace === true ? "Make sure this is intended: it changes every mob/block using the sound." : "Nothing to do."));
    }
  }
  // same custom sound event defined in two packs (any namespace other than minecraft)
  const sev = group(rps.flatMap((m) => Object.entries(m.resourcePack!.json).filter(([p]) => rpFileClass(p) === "sounds" && p.split("/")[1] !== "minecraft").flatMap(([p, j]) => Object.keys((j as object) ?? {}).map((k) => ({ key: `${p.split("/")[1]}:${k}`, mod: m, v: canonical((j as Record<string, unknown>)[k]) })))));
  for (const [k, xs] of sev) if (distinctMods(xs) >= 2 && new Set(xs.map((x) => x.v)).size > 1)
    C.add("sound.key", "warn", k, xs.map((x) => item(x.mod, `defines sound event ${k}`)), `The sound event ${k} is defined by ${distinctMods(xs)} packs differently.`, res("merge", true, "Merged (sounds concatenated) by the Mod Pack builder; to keep them apart, rebuild one under its own namespace."));
  // font codepoints
  const cps = group(rps.flatMap((m) => Object.entries(m.resourcePack!.json).filter(([p]) => rpFileClass(p) === "font").flatMap(([p, j]) => {
    const out: { key: string; mod: ModEntry; v: string }[] = [];
    const provs = (j as { providers?: unknown[] })?.providers;
    if (!Array.isArray(provs)) return out;
    for (const pr of provs) for (const row of ((pr as { chars?: unknown[] })?.chars ?? [])) if (typeof row === "string") for (const ch of row) { const cp = ch.codePointAt(0)!; if (cp > 0x20) out.push({ key: `${p} U+${cp.toString(16).toUpperCase().padStart(4, "0")}`, mod: m, v: p }); }
    return out;
  })));
  const cpByMods = new Map<string, { mods: ModEntry[]; cps: string[] }>();
  for (const [k, xs] of cps) if (distinctMods(xs) >= 2) { const ms = [...new Map(xs.map((x) => [x.mod.id, x.mod])).values()]; const gk = `${k.split(" ")[0]}|${ms.map((m) => m.id).join(",")}`; if (!cpByMods.has(gk)) cpByMods.set(gk, { mods: ms, cps: [] }); cpByMods.get(gk)!.cps.push(k.split(" ")[1]); }
  for (const [gk, v] of cpByMods)
    C.add("rp.font_codepoint", "warn", `${gk.split("|")[0]} ${v.cps[0]}${v.cps.length > 1 ? ` (+${v.cps.length - 1})` : ""}`, v.mods.map((m) => item(m, `provides ${v.cps.slice(0, 6).join(", ")}${v.cps.length > 6 ? "..." : ""}`)), `${v.mods.length} packs draw different glyphs on the same codepoints in ${gk.split("|")[0]}; text shows one of them.`,
      v.mods.some((m) => m.cyrus) ? res("reserved_namespace", false, "Cyrus glyphs come from the per-project block in the supplementary Private Use Area; rebuild the Cyrus pack with its allocated codepoints.") : USER());
  // existing pack owners on the server
  const addsPack = rps.some((m) => m.origin === "candidate");
  for (const o of ctx.packOwners ?? []) if (addsPack && o.kind !== "pack-loader")
    C.add("rp.existing_owner", "warn", `${o.kind}:${o.name}`, rps.filter((m) => m.origin === "candidate").map((m) => item(m, `adds a resource pack; ${o.detail}`)), `${o.name} already manages a resource pack on this server; it may replace or drop Nxeon's packs on join.`, USER("cannot resolve automatically: user decision (merge into the existing pack by hand, or let the Pack Loader send ours as extra packs)"));

  // ---- budgets -----------------------------------------------------------------------------------------------
  const B = { ...DEFAULT_BUDGETS, ...(ctx.budgets ?? {}) };
  const sum = (f: (m: ModEntry) => { n: number; est: boolean } | null) => { let n = 0; let est = false; const parts: FindingItem[] = []; for (const m of mods) { const v = f(m); if (!v || !v.n) continue; n += v.n; est ||= v.est; parts.push(item(m, `${v.n}${v.est ? " (estimated from bytecode call sites)" : " (declared)"}`)); } return { n, est, parts }; };
  const disp = sum((m) => m.budgets?.displayEntities != null ? { n: m.budgets.displayEntities, est: false } : bc(m) ? { n: bc(m)!.displayEntitySpawnSites, est: true } : null);
  if (disp.n > B.maxDisplayEntities) C.add("budget.display_entities", "warn", "display entities", disp.parts, `Together these mods spawn up to ${disp.n} display entities (budget ${B.maxDisplayEntities}).`, USER());
  const tasks = sum((m) => m.budgets?.repeatingTasks != null ? { n: m.budgets.repeatingTasks, est: false } : bc(m) ? { n: bc(m)!.repeatingTaskSites, est: true } : null);
  if (tasks.n > B.maxRepeatingTasks) C.add("budget.tasks", "warn", "repeating tasks", tasks.parts, `Together these mods schedule ${tasks.n} repeating tasks (budget ${B.maxRepeatingTasks}).`, USER());
  const packs = sum((m) => m.budgets?.packBytes != null ? { n: m.budgets.packBytes, est: false } : m.resourcePack ? { n: m.resourcePack.bytes, est: false } : null);
  if (packs.n > B.maxPackBytes) C.add("budget.pack_size", ctx.modPack ? "blocking" : "warn", "resource pack size", packs.parts, `Resource packs total ${packs.n} bytes (cap ${B.maxPackBytes}); every player downloads them on join.`, res("remove_one", false, "Drop or shrink a pack."));

  const findings = [...C.findings.values()].sort((a, b) => SEV_ORDER[a.severity] - SEV_ORDER[b.severity] || (a.class < b.class ? -1 : a.class > b.class ? 1 : 0) || (a.subject < b.subject ? -1 : a.subject > b.subject ? 1 : 0) || (a.id < b.id ? -1 : 1));
  const counts = { blocking: 0, warn: 0, info: 0 } as Record<Severity, number>;
  for (const f of findings) counts[f.severity]++;
  void shaderMods; void SHARED_NAMESPACES;
  return {
    engine: "cyrus-conflicts-1",
    mods: mods.map((m) => ({ id: m.id, label: m.label, kind: m.kind, origin: m.origin, cyrus: !!m.cyrus })),
    findings, counts, blocking: counts.blocking > 0, notChecked: [...new Set(notChecked)].sort(),
  };
}

