// Test helper: assemble REAL JVM class files (constant pool + methods + Code + RuntimeVisibleAnnotations) and jars,
// so the inventory's class reader is tested against the actual format, plus raw zip writers for malicious archives.
import { crc32, deflateRawSync } from "node:zlib";
import { zip } from "../lib/cyrus/textures/zip";

export type Ins =
  | ["ldc", string] | ["int", number] | ["ldcClass", string] | ["getstatic", string, string, string]
  | ["invoke", "virtual" | "special" | "static" | "interface", string, string, string]
  | ["new", string] | ["dup"] | ["aload0"] | ["pop"] | ["return"];
export type Ann = { type: string; values?: Record<string, ["e", string, string] | ["Z", boolean] | ["s", string]> };
export type MethodDef = { name: string; desc: string; annotations?: Ann[]; code: Ins[] };
export type ClassDef = { name: string; superName?: string; interfaces?: string[]; major?: number; methods: MethodDef[] };

export function genClass(def: ClassDef): Buffer {
  const pool: Buffer[] = [];
  const keys = new Map<string, number>();
  let next = 1;
  const add = (key: string, bytes: Buffer, slots = 1) => { const k = keys.get(key); if (k) return k; const i = next; next += slots; keys.set(key, i); pool.push(bytes); return i; };
  const u2 = (n: number) => { const b = Buffer.alloc(2); b.writeUInt16BE(n); return b; };
  const u4 = (n: number) => { const b = Buffer.alloc(4); b.writeUInt32BE(n >>> 0); return b; };
  const utf8 = (s: string) => { const d = Buffer.from(s, "utf8"); return add(`u:${s}`, Buffer.concat([Buffer.from([1]), u2(d.length), d])); };
  const cls = (s: string) => add(`c:${s}`, Buffer.concat([Buffer.from([7]), u2(utf8(s))]));
  const str = (s: string) => add(`s:${s}`, Buffer.concat([Buffer.from([8]), u2(utf8(s))]));
  const int = (n: number) => add(`i:${n}`, Buffer.concat([Buffer.from([3]), u4(n)]));
  const nat = (n: string, d: string) => add(`n:${n}:${d}`, Buffer.concat([Buffer.from([12]), u2(utf8(n)), u2(utf8(d))]));
  const mref = (tag: number, o: string, n: string, d: string) => add(`m${tag}:${o}.${n}:${d}`, Buffer.concat([Buffer.from([tag]), u2(cls(o)), u2(nat(n, d))]));

  const thisI = cls(def.name), superI = cls(def.superName ?? "java/lang/Object");
  const ifaces = (def.interfaces ?? []).map(cls);
  const codeAttr = utf8("Code"), annAttr = utf8("RuntimeVisibleAnnotations");
  const methods: Buffer[] = [];
  for (const m of def.methods) {
    const code: Buffer[] = [];
    for (const ins of m.code) {
      switch (ins[0]) {
        case "ldc": { const i = str(ins[1]); code.push(i < 256 ? Buffer.from([0x12, i]) : Buffer.concat([Buffer.from([0x13]), u2(i)])); break; }
        case "ldcClass": code.push(Buffer.concat([Buffer.from([0x13]), u2(cls(ins[1]))])); break;
        case "int": { const n = ins[1]; if (n >= -1 && n <= 5) code.push(Buffer.from([0x03 + n])); else if (n >= -128 && n <= 127) code.push(Buffer.from([0x10, n & 0xff])); else if (n >= -32768 && n <= 32767) { const b = Buffer.alloc(3); b[0] = 0x11; b.writeInt16BE(n, 1); code.push(b); } else code.push(Buffer.concat([Buffer.from([0x13]), u2(int(n))])); break; }
        case "getstatic": code.push(Buffer.concat([Buffer.from([0xb2]), u2(mref(9, ins[1], ins[2], ins[3]))])); break;
        case "invoke": {
          const op = { virtual: 0xb6, special: 0xb7, static: 0xb8, interface: 0xb9 }[ins[1]];
          const r = mref(ins[1] === "interface" ? 11 : 10, ins[2], ins[3], ins[4]);
          code.push(ins[1] === "interface" ? Buffer.concat([Buffer.from([op]), u2(r), Buffer.from([1, 0])]) : Buffer.concat([Buffer.from([op]), u2(r)]));
          break;
        }
        case "new": code.push(Buffer.concat([Buffer.from([0xbb]), u2(cls(ins[1]))])); break;
        case "dup": code.push(Buffer.from([0x59])); break;
        case "aload0": code.push(Buffer.from([0x2a])); break;
        case "pop": code.push(Buffer.from([0x57])); break;
        case "return": code.push(Buffer.from([0xb1])); break;
      }
    }
    const body = Buffer.concat(code);
    const codeBody = Buffer.concat([u2(16), u2(16), u4(body.length), body, u2(0), u2(0)]);
    const attrs: Buffer[] = [Buffer.concat([u2(codeAttr), u4(codeBody.length), codeBody])];
    if (m.annotations?.length) {
      const anns = m.annotations.map((a) => {
        const vals = Object.entries(a.values ?? {}).map(([k, v]) => {
          if (v[0] === "e") return Buffer.concat([u2(utf8(k)), Buffer.from("e"), u2(utf8(v[1])), u2(utf8(v[2]))]);
          if (v[0] === "Z") return Buffer.concat([u2(utf8(k)), Buffer.from("Z"), u2(int(v[1] ? 1 : 0))]);
          return Buffer.concat([u2(utf8(k)), Buffer.from("s"), u2(utf8(v[1]))]);
        });
        return Buffer.concat([u2(utf8(a.type)), u2(vals.length), ...vals]);
      });
      const ab = Buffer.concat([u2(anns.length), ...anns]);
      attrs.push(Buffer.concat([u2(annAttr), u4(ab.length), ab]));
    }
    methods.push(Buffer.concat([u2(0x0001), u2(utf8(m.name)), u2(utf8(m.desc)), u2(attrs.length), ...attrs]));
  }
  return Buffer.concat([u4(0xcafebabe), u2(0), u2(def.major ?? 65), u2(next), ...pool, u2(0x0021), u2(thisI), u2(superI), u2(ifaces.length), ...ifaces.map(u2), u2(0), u2(methods.length), ...methods, u2(0)]);
}

export type FixturePlugin = { name: string; version?: string; main?: string; api?: string; yml?: string; extraYml?: string; classes?: ClassDef[]; files?: { path: string; data: Buffer }[]; paperYml?: string };

export function pluginYml(p: FixturePlugin): string {
  return p.yml ?? `name: ${p.name}\nversion: ${p.version ?? "1.0.0"}\nmain: ${p.main ?? `dev.fx.${p.name.toLowerCase()}.Main`}\napi-version: "${p.api ?? "1.21"}"\n${p.extraYml ?? ""}`;
}

export function genJar(p: FixturePlugin): Buffer {
  const files = [{ path: "plugin.yml", data: Buffer.from(pluginYml(p)) }, ...(p.paperYml ? [{ path: "paper-plugin.yml", data: Buffer.from(p.paperYml) }] : []), ...(p.classes ?? []).map((c) => ({ path: `${c.name}.class`, data: genClass(c) })), ...(p.files ?? [])];
  return zip(files);
}

/** Raw zip writer that lets a test lie: names, declared sizes, method, CRC. */
export function rawZip(entries: { name: string; data: Buffer; method?: 0 | 8; declaredSize?: number; badCrc?: boolean }[]): Buffer {
  const parts: Buffer[] = [], central: Buffer[] = [];
  let off = 0;
  for (const e of entries) {
    const name = Buffer.from(e.name, "utf8");
    const comp = (e.method ?? 8) === 8 ? deflateRawSync(e.data) : e.data;
    const crc = e.badCrc ? (crc32(e.data) ^ 1) >>> 0 : crc32(e.data) >>> 0;
    const usize = e.declaredSize ?? e.data.length;
    const lh = Buffer.alloc(30); lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0x0800, 6); lh.writeUInt16LE(e.method ?? 8, 8); lh.writeUInt32LE(crc, 14); lh.writeUInt32LE(comp.length, 18); lh.writeUInt32LE(usize, 22); lh.writeUInt16LE(name.length, 26);
    parts.push(lh, name, comp);
    const ch = Buffer.alloc(46); ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6); ch.writeUInt16LE(0x0800, 8); ch.writeUInt16LE(e.method ?? 8, 10); ch.writeUInt32LE(crc, 16); ch.writeUInt32LE(comp.length, 20); ch.writeUInt32LE(usize, 24); ch.writeUInt16LE(name.length, 28); ch.writeUInt32LE(off, 42);
    central.push(ch, name);
    off += 30 + name.length + comp.length;
  }
  const cd = Buffer.concat(central);
  const end = Buffer.alloc(22); end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(entries.length, 8); end.writeUInt16LE(entries.length, 10); end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(off, 16);
  return Buffer.concat([...parts, cd, end]);
}

// ---- common Bukkit/Paper call shapes ---------------------------------------------------------------------------
export const EH = "Lorg/bukkit/event/EventHandler;";
export const handler = (name: string, event: string, priority: string, body: Ins[], ignoreCancelled = false): MethodDef => ({
  name, desc: `(L${event};)V`,
  annotations: [{ type: EH, values: { priority: ["e", "Lorg/bukkit/event/EventPriority;", priority], ...(ignoreCancelled ? { ignoreCancelled: ["Z", true] as ["Z", boolean] } : {}) } }],
  code: [...body, ["return"]],
});
export const pluginKey = (key: string): Ins[] => [["new", "org/bukkit/NamespacedKey"], ["dup"], ["aload0"], ["ldc", key], ["invoke", "special", "org/bukkit/NamespacedKey", "<init>", "(Lorg/bukkit/plugin/Plugin;Ljava/lang/String;)V"]];
