// Cyrus R2 server inventory: YAML subset, descriptors, class-file reader, jar inspection (incl. malicious zips),
// datapacks, level.dat, and the read-only server scan over a fake server tree. Pure / temp dirs only.
//   tsx --test test/cyrus-inventory.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { gzipSync, deflateRawSync } from "node:zlib";
import { parseYaml } from "../lib/cyrus/inventory/yaml";
import { readDescriptor } from "../lib/cyrus/inventory/descriptor";
import { parseClass } from "../lib/cyrus/inventory/classfile";
import { inspectJar } from "../lib/cyrus/inventory/jar";
import { indexZip, readEntry } from "../lib/cyrus/inventory/zipread";
import { classifyDataPath } from "../lib/cyrus/inventory/datapack";
import { readLevelDatDatapacks } from "../lib/cyrus/inventory/nbt";
import { detectSoftware, parseProperties, scanServer } from "../lib/cyrus/inventory/scan";
import type { ReadOnlyServerFs } from "../lib/cyrus/inventory/types";
import { LocalGuestFs } from "../lib/mods/guest-fs";
import { zip } from "../lib/cyrus/textures/zip";
import { cmd, fullKey, genClass, genJar, handler, pluginKey, rawZip, setItemModel, type ClassDef } from "./_cyrus-jarfixture";

// ---- a fixture plugin that exercises every bytecode rule ---------------------------------------------------------
export const RICH_CLASSES: ClassDef[] = [
  {
    name: "dev/fx/rich/Main", superName: "org/bukkit/plugin/java/JavaPlugin", major: 65,
    methods: [
      { name: "onEnable", desc: "()V", code: [
        ...pluginKey("mana"), ["pop"],
        ...fullKey("rich", "shared_key"), ["pop"],
        ["ldcClass", "net/milkbowl/vault/economy/Economy"], ["invoke", "interface", "org/bukkit/plugin/ServicesManager", "register", "(Ljava/lang/Class;Ljava/lang/Object;Lorg/bukkit/plugin/Plugin;Lorg/bukkit/plugin/ServicePriority;)V"],
        ["ldc", "richcmd"], ["invoke", "static", "io/papermc/paper/command/brigadier/Commands", "literal", "(Ljava/lang/String;)Lcom/mojang/brigadier/builder/LiteralArgumentBuilder;"],
        ["ldc", "sub"], ["invoke", "static", "io/papermc/paper/command/brigadier/Commands", "literal", "(Ljava/lang/String;)Lcom/mojang/brigadier/builder/LiteralArgumentBuilder;"],
        ["invoke", "interface", "io/papermc/paper/command/brigadier/Commands", "register", "(Lcom/mojang/brigadier/tree/LiteralCommandNode;)Ljava/util/Set;"],
        ["invoke", "interface", "org/bukkit/scheduler/BukkitScheduler", "runTaskTimer", "(Lorg/bukkit/plugin/Plugin;Ljava/lang/Runnable;JJ)Lorg/bukkit/scheduler/BukkitTask;"],
        ["ldcClass", "org/bukkit/entity/TextDisplay"], ["invoke", "interface", "org/bukkit/World", "spawn", "(Lorg/bukkit/Location;Ljava/lang/Class;)Lorg/bukkit/entity/Entity;"],
        ["invoke", "interface", "org/bukkit/World", "setTime", "(J)V"],
        ["return"],
      ] },
      { name: "items", desc: "()V", code: [
        ...fullKey("nx_abcd1234", "ruby_sword"), setItemModel,
        ...cmd(1001),
        ...fullKey("rich", "ruby_recipe"), ["new", "org/bukkit/inventory/ShapedRecipe"], ["invoke", "special", "org/bukkit/inventory/ShapedRecipe", "<init>", "(Lorg/bukkit/NamespacedKey;Lorg/bukkit/inventory/ItemStack;)V"],
        ["ldc", "rich.zap"], ["invoke", "interface", "org/bukkit/entity/Player", "playSound", "(Lorg/bukkit/Location;Ljava/lang/String;FF)V"],
        ["invoke", "interface", "org/bukkit/persistence/PersistentDataContainer", "set", "(Lorg/bukkit/NamespacedKey;Lorg/bukkit/persistence/PersistentDataType;Ljava/lang/Object;)V"],
        ["return"],
      ] },
    ],
  },
  {
    name: "dev/fx/rich/Listen", interfaces: ["org/bukkit/event/Listener"],
    methods: [
      handler("onJoin", "org/bukkit/event/player/PlayerJoinEvent", "HIGH", [["ldc", "hi"], ["invoke", "virtual", "org/bukkit/event/player/PlayerJoinEvent", "setJoinMessage", "(Ljava/lang/String;)V"]]),
      handler("onBreak", "org/bukkit/event/block/BlockBreakEvent", "NORMAL", [["int", 1], ["invoke", "virtual", "org/bukkit/event/block/BlockBreakEvent", "setCancelled", "(Z)V"]], true),
      handler("onWatch", "org/bukkit/event/player/PlayerMoveEvent", "MONITOR", [["invoke", "virtual", "org/bukkit/event/player/PlayerMoveEvent", "getPlayer", "()Lorg/bukkit/entity/Player;"]]),
    ],
  },
];
export const RICH_YML = `name: Rich
version: '1.10'
main: dev.fx.rich.Main
api-version: "1.21"
depend: [Vault]
softdepend: PlaceholderAPI
commands:
  rich:
    description: Rich command
    aliases: [r, riches]
    permission: rich.use
  richadmin:
    aliases: ra
permissions:
  rich.use:
    default: true
  rich.admin:
    default: op
    children:
      rich.use: true
      rich.admin.reload:
        default: not op
`;

describe("YAML subset", () => {
  it("reads a typical plugin.yml, keeps scalars as strings", () => {
    const { value, issues } = parseYaml(RICH_YML);
    assert.deepEqual(issues, []);
    const v = value as Record<string, any>;
    assert.equal(v.version, "1.10");
    assert.deepEqual(v.depend, ["Vault"]);
    assert.deepEqual(v.commands.rich.aliases, ["r", "riches"]);
    assert.equal(v.permissions["rich.admin"].children["rich.admin.reload"].default, "not op");
  });
  it("handles sequences at the key's indent, quoting, comments, block scalars and flow maps", () => {
    const { value, issues } = parseYaml(`a:\n- x\n- "y # not a comment"\n- 'it''s'\nb: | \n  line1\n  line2\nc: {k: v, l: [1, 2]}  # trailing\nd:\n  - name: n1\n    v: 1\n  - name: n2\n`);
    assert.deepEqual(issues, []);
    assert.deepEqual(value, { a: ["x", "y # not a comment", "it's"], b: "line1\nline2", c: { k: "v", l: ["1", "2"] }, d: [{ name: "n1", v: "1" }, { name: "n2" }] });
  });
  it("refuses anchors/aliases/merge keys and pathological input without throwing", () => {
    const r = parseYaml(`a: &x [1,2]\nb: *x\n<<: *x\n__proto__: 1\n`);
    assert.ok(r.issues.some((i) => /anchors/.test(i)));
    assert.equal(Object.getPrototypeOf(r.value), Object.prototype);
    assert.equal(({} as Record<string, unknown>).polluted, undefined);
    const deep = Array.from({ length: 60 }, (_, i) => `${" ".repeat(i * 2)}k${i}:`).join("\n") + " x";
    assert.ok(parseYaml(deep).issues.some((i) => /deeper/.test(i)));
    for (const junk of ["\0\0\0", ": : :", "[[[[[[", "{a: [}", "- - - -", "a:\n\t\tb: c", "x".repeat(600 * 1024), "\"unterminated"]) assert.doesNotThrow(() => parseYaml(junk));
    assert.ok(parseYaml("x".repeat(600 * 1024)).issues[0].includes("larger"));
  });
});

describe("plugin descriptors", () => {
  it("normalizes commands, aliases, permissions (defaults + children) and dependencies", () => {
    const d = readDescriptor(RICH_YML, "plugin.yml");
    assert.equal(d.name, "Rich"); assert.equal(d.version, "1.10"); assert.equal(d.apiVersion, "1.21");
    assert.deepEqual(d.depend, ["Vault"]); assert.deepEqual(d.softdepend, ["PlaceholderAPI"]);
    assert.deepEqual(d.commands.map((c) => [c.name, c.aliases, c.permission]), [["rich", ["r", "riches"], "rich.use"], ["richadmin", ["ra"], null]]);
    assert.deepEqual(d.permissions.map((p) => [p.name, p.default]), [["rich.use", "true"], ["rich.admin", "op"], ["rich.admin.reload", "not op"]]);
  });
  it("uses default-permission and Bukkit's default aliases", () => {
    const d = readDescriptor(`name: P\nmain: a.B\ndefault-permission: notop\npermissions:\n  p.a: {}\n  p.b:\n    default: isop\n  p.c:\n    default: "!op"\n`, "plugin.yml");
    assert.deepEqual(d.permissions.map((p) => [p.name, p.default, p.explicitDefault]), [["p.a", "not op", false], ["p.b", "op", true], ["p.c", "not op", true]]);
  });
  it("maps paper-plugin.yml dependencies and flags fields Paper ignores", () => {
    const d = readDescriptor(`name: PP\nmain: a.B\nfolia-supported: true\ndependencies:\n  server:\n    Vault:\n      load: BEFORE\n    LuckPerms:\n      required: true\n    Opt:\n      required: false\ncommands:\n  x: {}\n`, "paper-plugin.yml");
    assert.deepEqual([d.loadbefore, d.depend, d.softdepend, d.foliaSupported], [["Vault"], ["LuckPerms"], ["Opt"], true]);
    assert.equal(d.commands.length, 0);
    assert.ok(d.issues.some((i) => /cannot declare commands/.test(i)));
  });
});

describe("class files", () => {
  it("parses constant pool, annotations and call windows", () => {
    const c = parseClass(genClass(RICH_CLASSES[1]));
    assert.ok(c.ok);
    if (!c.ok) return;
    assert.equal(c.cls.name, "dev/fx/rich/Listen");
    const onJoin = c.cls.methods.find((m) => m.name === "onJoin")!;
    assert.equal(onJoin.annotations[0].values.priority, "HIGH");
    assert.deepEqual(onJoin.calls.map((x) => [x.name, x.strs]), [["setJoinMessage", ["hi"]]]);
    assert.equal(c.cls.methods.find((m) => m.name === "onBreak")!.annotations[0].values.ignoreCancelled, "1");
  });
  it("never throws on garbage or truncated class bytes", () => {
    const good = genClass(RICH_CLASSES[0]);
    for (let cut = 0; cut < good.length; cut += 7) assert.doesNotThrow(() => parseClass(good.subarray(0, cut)));
    assert.equal(parseClass(good.subarray(0, 40)).ok, false);
    assert.equal(parseClass(Buffer.from("not a class")).ok, false);
    let seed = 7; const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) & 0xff;
    for (let i = 0; i < 200; i++) { const b = Buffer.from(good); for (let k = 0; k < 6; k++) b[10 + (rnd() * 97 + k * 31) % (b.length - 10)] = rnd(); assert.doesNotThrow(() => parseClass(b)); }
  });
});

describe("jar inspection", () => {
  const jar = inspectJar("Rich.jar", "plugins/Rich.jar", genJar({ name: "Rich", yml: RICH_YML, classes: RICH_CLASSES }));
  const b = jar.bytecode!;
  it("reads the descriptor and a bytecode summary", () => {
    assert.equal(jar.descriptor?.name, "Rich");
    assert.equal(b.classesParsed, 2); assert.equal(b.javaRelease, 21);
    assert.deepEqual(b.events.map((e) => [e.event.split(".").pop(), e.priority, e.mutates, e.cancels, e.ignoreCancelled]), [
      ["BlockBreakEvent", "NORMAL", false, true, true], ["PlayerJoinEvent", "HIGH", true, false, false], ["PlayerMoveEvent", "MONITOR", false, false, false],
    ]);
    assert.deepEqual(b.brigadierRoots, ["richcmd"]);
    assert.deepEqual(b.services.map((s) => s.service), ["economy"]);
    assert.deepEqual([...new Set(b.singleOwner.map((s) => s.resource))].sort(), ["economy_provider", "join_quit_messages", "world_rules"]);
    assert.deepEqual([...new Set(b.namespacedKeys.map((k) => k.key))].sort(), ["nx_abcd1234:ruby_sword", "rich:mana", "rich:ruby_recipe", "rich:shared_key"]);
    assert.deepEqual(b.itemModels.map((k) => k.key), ["nx_abcd1234:ruby_sword"]);
    assert.deepEqual(b.customModelData, [1001]);
    assert.deepEqual(b.recipes.map((k) => k.key), ["rich:ruby_recipe"]);
    assert.deepEqual(b.soundKeys.map((k) => k.key), ["minecraft:rich.zap"]);
    assert.equal(b.pdcUsed, true); assert.equal(b.usesItemModelApi, true);
    assert.equal(b.repeatingTaskSites, 1); assert.equal(b.displayEntitySpawnSites, 1); assert.equal(b.bukkitSchedulerSites, 1);
    assert.ok(b.undetermined.some((u) => /helper methods/.test(u)));
  });
  it("is deterministic regardless of class order", () => {
    const again = inspectJar("Rich.jar", "plugins/Rich.jar", genJar({ name: "Rich", yml: RICH_YML, classes: [...RICH_CLASSES].reverse() }));
    assert.deepEqual(again.bytecode, b);
  });
  it("reports computed keys and Java 25 classes", () => {
    const j = inspectJar("C.jar", "plugins/C.jar", genJar({ name: "C", classes: [{ name: "c/M", major: 69, methods: [{ name: "x", desc: "()V", code: [["new", "org/bukkit/NamespacedKey"], ["dup"], ["aload0"], ["invoke", "virtual", "java/lang/Object", "toString", "()Ljava/lang/String;"], ["invoke", "special", "org/bukkit/NamespacedKey", "<init>", "(Lorg/bukkit/plugin/Plugin;Ljava/lang/String;)V"], ["return"]] }] }] }));
    assert.equal(j.bytecode!.javaRelease, 25);
    assert.ok(j.bytecode!.undetermined.some((u) => /computed/.test(u)));
  });
  it("prefers paper-plugin.yml when both exist", () => {
    const j = inspectJar("P.jar", "plugins/P.jar", genJar({ name: "Legacy", paperYml: "name: Modern\nmain: a.B\nversion: 2\n" }));
    assert.equal(j.descriptor?.name, "Modern");
    assert.ok(j.descriptor?.issues.some((i) => /both/.test(i)));
  });
  it("flags server jars", () => {
    const j = inspectJar("paper.jar", "plugins/paper.jar", zip([{ path: "META-INF/versions.list", data: Buffer.from("x") }, { path: "io/papermc/paperclip/Main.class", data: genClass({ name: "io/papermc/paperclip/Main", methods: [] }) }]));
    assert.equal(j.flags.serverJar, true);
    assert.equal(j.descriptor, null);
  });
});

describe("malicious archives (never throw, never extract, flag)", () => {
  const yml = Buffer.from("name: Evil\nmain: e.M\nversion: 1\n");
  it("zip bomb: a highly compressed entry is refused by ratio and flagged", () => {
    const bomb = Buffer.alloc(3 * 1024 * 1024, 0);
    const j = inspectJar("Bomb.jar", "plugins/Bomb.jar", rawZip([{ name: "plugin.yml", data: yml }, { name: "e/M.class", data: bomb }]));
    assert.deepEqual(j.flags.bombEntries, ["e/M.class"]);
    assert.equal(j.descriptor?.name, "Evil");
  });
  it("lying header: inflates past its declared size -> refused", () => {
    const big = Buffer.alloc(200_000, 0x41);
    const z = indexZip(rawZip([{ name: "a.class", data: big, declaredSize: 100 }]));
    assert.ok(z.ok);
    if (!z.ok) return;
    const r = readEntry(z.zip, z.zip.entries[0]);
    assert.equal(r.ok, false);
  });
  it("traversal and absolute names are reported (not extracted)", () => {
    const j = inspectJar("T.jar", "plugins/T.jar", rawZip([{ name: "plugin.yml", data: yml }, { name: "../../etc/cron.d/x", data: Buffer.from("x") }, { name: "/abs", data: Buffer.from("y") }, { name: "a\\b", data: Buffer.from("z") }]));
    assert.deepEqual(j.flags.unsafeNames, ["../../etc/cron.d/x", "/abs", "a\\b"]);
  });
  it("huge declared entries, bad CRC, duplicates, truncation and garbage", () => {
    const huge = indexZip(rawZip([{ name: "h.class", data: Buffer.alloc(10), method: 0, declaredSize: 900 * 1024 * 1024 }]));
    assert.ok(huge.ok && !readEntry(huge.zip, huge.zip.entries[0]).ok);
    const crc = indexZip(rawZip([{ name: "c.class", data: Buffer.from("abc"), badCrc: true }]));
    assert.ok(crc.ok && !readEntry(crc.zip, crc.zip.entries[0]).ok);
    const dup = inspectJar("D.jar", "plugins/D.jar", rawZip([{ name: "plugin.yml", data: yml }, { name: "plugin.yml", data: Buffer.from("name: Other\n") }]));
    assert.deepEqual(dup.flags.duplicateNames, ["plugin.yml"]);
    const good = genJar({ name: "Rich", yml: RICH_YML, classes: RICH_CLASSES });
    for (let cut = 0; cut < good.length; cut += Math.max(1, Math.floor(good.length / 60))) {
      const j = inspectJar("cut.jar", "plugins/cut.jar", good.subarray(0, cut));
      assert.ok(j.flags.unreadable || j.descriptor || j.bytecode);
    }
    assert.match(inspectJar("g.jar", "plugins/g.jar", Buffer.from("PK\x03\x04 garbage garbage garbage")).flags.unreadable!, /not a zip/);
    const shared = indexZip(rawZip([{ name: "a", data: Buffer.alloc(40_000, 1) }, { name: "b", data: Buffer.alloc(40_000, 2) }]), { maxEntries: 10, maxEntryBytes: 1e6, maxTotalBytes: 50_000, maxRatio: 1e9, maxNameBytes: 100 });
    assert.ok(shared.ok);
    if (shared.ok) { assert.ok(readEntry(shared.zip, shared.zip.entries[0]).ok); const r2 = readEntry(shared.zip, shared.zip.entries[1]); assert.ok(!r2.ok && /budget/.test(r2.error)); }
  });
  it("encrypted entries are refused", () => {
    const z = rawZip([{ name: "x.class", data: Buffer.from("x") }]);
    const cd = z.indexOf(Buffer.from([0x50, 0x4b, 0x01, 0x02]));
    z.writeUInt16LE(z.readUInt16LE(cd + 8) | 1, cd + 8);
    const idx = indexZip(z);
    assert.ok(idx.ok && !readEntry(idx.zip, idx.zip.entries[0]).ok);
    void deflateRawSync;
  });
});

// ---- NBT writer (tests only) -------------------------------------------------------------------------------------
function nbtString(s: string) { const b = Buffer.from(s); const l = Buffer.alloc(2); l.writeUInt16BE(b.length); return Buffer.concat([l, b]); }
function nbtList(name: string, items: string[]) { const n = Buffer.alloc(4); n.writeInt32BE(items.length); return Buffer.concat([Buffer.from([9]), nbtString(name), Buffer.from([8]), n, ...items.map(nbtString)]); }
export function levelDat(enabled: string[], disabled: string[]): Buffer {
  const dataPacks = Buffer.concat([Buffer.from([10]), nbtString("DataPacks"), nbtList("Enabled", enabled), nbtList("Disabled", disabled), Buffer.from([0])]);
  const intTag = Buffer.concat([Buffer.from([3]), nbtString("version"), Buffer.from([0, 0, 0x4a, 0xbd])]);
  const data = Buffer.concat([Buffer.from([10]), nbtString("Data"), intTag, dataPacks, Buffer.from([0])]);
  return gzipSync(Buffer.concat([Buffer.from([10]), nbtString(""), data, Buffer.from([0])]));
}

describe("datapacks + level.dat", () => {
  it("classifies data paths (singular/plural, tags, worldgen)", () => {
    assert.deepEqual(classifyDataPath("data/minecraft/loot_tables/blocks/stone.json"), { type: "loot_table", id: "minecraft:blocks/stone" });
    assert.deepEqual(classifyDataPath("data/a/tags/functions/load.json"), { type: "tags/function", id: "a:load" });
    assert.deepEqual(classifyDataPath("data/a/tags/worldgen/biome/x.json"), { type: "tags/worldgen/biome", id: "a:x" });
    assert.deepEqual(classifyDataPath("data/a/worldgen/biome/x.json"), { type: "worldgen/biome", id: "a:x" });
    assert.equal(classifyDataPath("assets/a/x.json"), null);
  });
  it("reads registered datapacks and survives junk", () => {
    assert.deepEqual(readLevelDatDatapacks(levelDat(["vanilla", "file/dp1.zip"], ["file/old"])), { ok: true, enabled: ["vanilla", "file/dp1.zip"], disabled: ["file/old"] });
    for (const junk of [Buffer.alloc(0), Buffer.from("garbage"), gzipSync(Buffer.from([10, 0, 0, 9, 0, 1, 65, 8, 0x7f, 0xff, 0xff, 0xff]))]) assert.equal(readLevelDatDatapacks(junk).ok, false);
    const bomb = gzipSync(Buffer.alloc(40 * 1024 * 1024, 0));
    assert.equal(readLevelDatDatapacks(bomb).ok, false);
  });
});

// ---- the whole scan over a fake server -------------------------------------------------------------------------
class MemFs implements ReadOnlyServerFs {
  constructor(readonly files: Map<string, Buffer>) {}
  async stat(p: string) {
    const f = this.files.get(p);
    if (f) return { type: "file" as const, size: f.length };
    return [...this.files.keys()].some((k) => k.startsWith(p + "/")) ? { type: "dir" as const, size: 0 } : null;
  }
  async readFile(p: string, max = Infinity) { const f = this.files.get(p); return f && f.length <= max ? f : null; }
  async list(d: string) { return [...new Set([...this.files.keys()].filter((k) => k.startsWith(d + "/")).map((k) => k.slice(d.length + 1).split("/")[0]))]; }
}

export function fakeServer(extra: Record<string, Buffer> = {}): Map<string, Buffer> {
  const m = new Map<string, Buffer>();
  const put = (p: string, d: Buffer | string) => m.set(`/opt/mc/${p}`, Buffer.isBuffer(d) ? d : Buffer.from(d));
  put("server.properties", "#Minecraft server properties\nlevel-name=world\nrcon.password=hunter2-secret\nmanagement-server-secret=xyz\nresource-pack=https\\://example.invalid/p.zip\nrequire-resource-pack=true\nmotd=hello\n");
  put("logs/latest.log", "[12:00:00 INFO]: Starting minecraft server version 1.21.11\n[12:00:00 INFO]: This server is running Paper version 1.21.11-132-main@abc (2026-05-11T00:00:00Z) (Implementing API version 1.21.11-R0.1-SNAPSHOT)\n");
  put("version_history.json", JSON.stringify({ currentVersion: "1.21.11-132-main@abc (MC: 1.21.11)" }));
  put("paper-1.21.11-132.jar", "jar");
  put("plugins/Rich.jar", genJar({ name: "Rich", yml: RICH_YML, classes: RICH_CLASSES }));
  put("plugins/Oraxen.jar", genJar({ name: "Oraxen" }));
  put("plugins/Geyser-Spigot.jar", genJar({ name: "Geyser-Spigot" }));
  put("plugins/floodgate.jar", genJar({ name: "floodgate" }));
  put("plugins/notes.txt", "not a jar");
  put("plugins/NxeonPackLoader/packs.json", JSON.stringify({ schema: 1, packs: [{ id: "8f0e2b7c-1d2a-5e3f-9a4b-6c7d8e9f0a1b", url: "https://packs.example.invalid/p/" + "a".repeat(40) + ".zip", sha1: "a".repeat(40), prompt: "x", required: false }] }));
  put("world/datapacks/dp1.zip", zip([{ path: "pack.mcmeta", data: Buffer.from('{"pack":{"pack_format":94,"description":"one"}}') }, { path: "data/minecraft/tags/block/mineable/pickaxe.json", data: Buffer.from('{"replace":true,"values":["minecraft:stone"]}') }, { path: "data/minecraft/loot_table/blocks/stone.json", data: Buffer.from("{}") }]));
  put("world/datapacks/dp2/pack.mcmeta", '{"pack":{"min_format":[94,1],"max_format":[94,1],"description":"two"}}');
  put("world/datapacks/dp2/data/two/function/hello.mcfunction", "say hi");
  put("world/datapacks/dp2/data/minecraft/tags/function/load.json", '{"values":["two:hello"]}');
  put("world/level.dat", levelDat(["vanilla", "file/dp1.zip", "file/dp2"], []));
  for (const [k, v] of Object.entries(extra)) put(k, v);
  return m;
}

describe("scanServer (read-only)", () => {
  it("produces a typed report and never copies secrets", async () => {
    const rep = await scanServer(new MemFs(fakeServer()));
    assert.deepEqual([rep.software.name, rep.software.mcVersion, rep.software.build], ["paper", "1.21.11", "132"]);
    assert.deepEqual(rep.plugins.map((p) => p.descriptor?.name), ["Geyser-Spigot", "Oraxen", "Rich", "floodgate"]);
    assert.equal(rep.serverProperties.keys["resource-pack"], "https://example.invalid/p.zip");
    assert.equal(rep.serverProperties.redacted, 3);
    const text = JSON.stringify(rep);
    assert.ok(!text.includes("hunter2") && !text.includes("xyz"));
    assert.deepEqual(rep.datapacks.folder.map((d) => [d.name, d.container, d.files.length]), [["dp1.zip", "zip", 2], ["dp2", "dir", 2]]);
    assert.deepEqual(rep.datapacks.folder[0].tags, [{ registry: "block", id: "minecraft:mineable/pickaxe", replace: true, values: ["minecraft:stone"] }]);
    assert.deepEqual(rep.datapacks.registered, { enabled: ["vanilla", "file/dp1.zip", "file/dp2"], disabled: [] });
    assert.deepEqual(rep.resourcePackOwners.map((o) => [o.kind, o.name]), [["server.properties", "server.properties"], ["pack-loader", "NxeonPackLoader"], ["plugin", "Oraxen"]]);
    assert.deepEqual(rep.bedrock, { geyser: true, floodgate: true });
    assert.equal(rep.packLoader.packs.length, 1);
  });
  it("is bounded and tolerant: jar caps, unreadable files, missing everything", async () => {
    const rep = await scanServer(new MemFs(fakeServer({ "plugins/zz-junk.jar": Buffer.from("garbage") })), { limits: { maxJars: 2 } });
    assert.equal(rep.plugins.length, 2);
    assert.ok(rep.limits.truncated[0].includes("only 2 of 5"));
    const big = await scanServer(new MemFs(fakeServer()), { limits: { maxJarBytes: 1000 } });
    assert.ok(big.limits.truncated.some((t) => /scan cap/.test(t)));
    const empty = await scanServer(new MemFs(new Map()));
    assert.equal(empty.software.name, "unknown");
    assert.ok(empty.undetermined.length >= 3);
    const junk = await scanServer(new MemFs(fakeServer({ "plugins/zz-junk.jar": Buffer.from("garbage"), "world/level.dat": Buffer.from("x"), "plugins/NxeonPackLoader/packs.json": Buffer.from("{") })));
    assert.equal(junk.packLoader.error, "packs.json is not JSON");
    assert.ok(junk.plugins.find((p) => p.file === "zz-junk.jar")!.flags.unreadable);
    assert.ok(junk.datapacks.issues.some((i) => /level.dat/.test(i)));
  });
  it("runs over Nxeon's GuestFs unchanged (structural seam: LocalGuestFs satisfies ReadOnlyServerFs)", async () => {
    const dir = mkdtempSync(path.join(tmpdir(), "cyrus-inv-"));
    try {
      const g = new LocalGuestFs(dir);
      for (const [p, d] of fakeServer()) await g.writeFile(p, d);
      const ro: ReadOnlyServerFs = g;
      const rep = await scanServer(ro);
      assert.equal(rep.plugins.length, 4);
      assert.equal(rep.datapacks.folder.length, 2);
    } finally { rmSync(dir, { recursive: true, force: true }); }
  });
  it("detects software from partial evidence", () => {
    assert.equal(detectSoftware({ rootFiles: ["purpur-1.21.4-2400.jar"], versionHistory: null, logHead: null, hasMods: false }).name, "purpur");
    assert.equal(detectSoftware({ rootFiles: [], versionHistory: null, logHead: null, hasMods: true }).name, "fabric");
    assert.deepEqual(parseProperties("a\\:b=c\\u0041\n! c\nx : y\n"), { "a:b": "cA", x: "y" });
  });
});

