  });
  it("detects software from partial evidence", () => {
    assert.equal(detectSoftware({ rootFiles: ["purpur-1.21.4-2400.jar"], versionHistory: null, logHead: null, hasMods: false }).name, "purpur");
    assert.equal(detectSoftware({ rootFiles: [], versionHistory: null, logHead: null, hasMods: true }).name, "fabric");
    assert.deepEqual(parseProperties("a\\:b=c\\u0041\n! c\nx : y\n"), { "a:b": "cA", x: "y" });
  });
});

