export function validateLoaderConfig(raw: unknown, opts: { requireHttps?: boolean } = {}): { ok: true; config: LoaderConfig } | { ok: false; errors: Issue[] } {
  const errors: Issue[] = [];
  const o = raw as Record<string, unknown>;
  if (!o || typeof o !== "object" || Array.isArray(o)) return { ok: false, errors: [{ code: "not_object", message: "config must be a JSON object" }] };
  if (o.schema !== LOADER_CONFIG_SCHEMA) errors.push({ code: "schema", message: `schema must be ${LOADER_CONFIG_SCHEMA}` });
  if (!Array.isArray(o.packs)) return { ok: false, errors: [...errors, { code: "packs", message: "packs must be an array" }] };
  if (o.packs.length > MAX_PACKS) errors.push({ code: "too_many", message: `at most ${MAX_PACKS} packs` });
  const ids = new Set<string>();
  const packs: LoaderPack[] = [];
  for (const [i, p] of (o.packs as Record<string, unknown>[]).entries()) {
    const at = `packs[${i}]`;
    if (!p || typeof p !== "object") { errors.push({ code: "pack", message: `${at} must be an object` }); continue; }
    const id = String(p.id ?? "");
    if (!UUID_RE.test(id)) errors.push({ code: "id", message: `${at}.id must be a lower-case UUID` });
    else if (ids.has(id)) errors.push({ code: "duplicate_id", message: `${at}.id ${id} appears twice` });
    ids.add(id);
    const url = String(p.url ?? "");
    let u: URL | null = null;
    try { u = new URL(url); } catch { /* invalid */ }
    const okProto = u && (u.protocol === "https:" || (!opts.requireHttps && u.protocol === "http:"));
    if (!u || !okProto || url.length > MAX_URL || u.username || u.password) errors.push({ code: "url", message: `${at}.url must be an ${opts.requireHttps ? "https" : "http(s)"} URL of at most ${MAX_URL} chars` });
    const sha1 = String(p.sha1 ?? "");
    if (!SHA1_RE.test(sha1)) errors.push({ code: "sha1", message: `${at}.sha1 must be 40 lower-case hex chars` });
    if (p.prompt != null && (typeof p.prompt !== "string" || p.prompt.length > MAX_PROMPT)) errors.push({ code: "prompt", message: `${at}.prompt must be a string of at most ${MAX_PROMPT} chars` });
    if (typeof p.required !== "boolean") errors.push({ code: "required", message: `${at}.required must be true or false` });
    packs.push({ id, url, sha1, ...(typeof p.prompt === "string" ? { prompt: p.prompt } : {}), required: p.required === true, ...(typeof p.owner === "string" ? { owner: p.owner } : {}), ...(typeof p.role === "string" ? { role: p.role } : {}) });
  }
  if (errors.length) return { ok: false, errors };
  return { ok: true, config: { schema: 1, packs } };
}

/** Deterministic bytes (stable key order, 2-space JSON, trailing newline): unchanged config = identical file. */
export function serializeLoaderConfig(c: LoaderConfig): string {
/**
 * Path safety for the mod installer. Every path that reaches a customer's
 * server — an entry inside a downloaded archive, a filename an upstream API
 * hands us, a path inside a Modrinth modpack index — goes through here first.
 *
 * The rule is an ALLOWLIST, not a blocklist: a segment is accepted only if it
 * is made of characters that are inert in a shell (even though we quote
 * everything anyway), cannot be an option (`-rf`), cannot climb (`..`), and
 * cannot be absolute. Anything else rejects the WHOLE package rather than
 * being "cleaned" — a silently renamed file is a file the mod can't find, and
 * an archive that ships `../../etc/cron.d/x` is not a mod we want anyway.
 */

/** One path segment: no leading dash, never `.`/`..`, printable set (`$` and a leading dot are
 *  allowed — Java inner classes and dot-folders are real; every use is single-quoted anyway). */
const SEGMENT = /^[A-Za-z0-9_+@\[\]().$][A-Za-z0-9 ._+@\[\]()~#&=!,$-]{0,254}$/;
const MAX_REL_LEN = 1024;

export function isSafeSegment(s: string): boolean {
  if (!s || s === "." || s === "..") return false;
  if (s.endsWith(" ") || s.endsWith(".")) return false; // ambiguous on Windows-built archives, and never needed
  return SEGMENT.test(s);
}

/**
 * Normalize an archive entry name to safe relative segments, or null when it
 * must be refused. Accepts Windows separators (many mod zips are built on
 * Windows) and a leading "./"; refuses absolute paths, drive letters, `..`,
 * NUL, empty middle segments and anything outside the segment allowlist.
 */

