// Test helper: a declarative "good mod" (plugin jar + datapack + resource pack) and the conflict-engine entries built
// from it. The mutation corpus (test/cyrus-conflicts.test.ts) edits these specs to collide ids/commands/keys.
import { zip } from "../lib/cyrus/textures/zip";
import { candidateJar, datapackEntry, resourcePackEntry } from "../lib/cyrus/conflicts/normalize";
import { indexDatapack } from "../lib/cyrus/inventory/datapack";
import type { ModEntry } from "../lib/cyrus/conflicts/types";
import { fullKey, genClass, handler, setItemModel, type ClassDef, type Ins, type MethodDef } from "./_cyrus-jarfixture";

export type EventFx = { event: string; priority: string; kind: "read" | "mutate" | "cancel" };
export type ModFx = {
  id: string; ns: string | null; name: string; tag: string;
  main?: string; api?: string; folia?: boolean; major?: number;
  commands: { name: string; aliases: string[] }[];
