// Cyrus R2 conflict engine: false-positive guard (clean sets -> zero findings), the mutation corpus (take a good mod,
// mechanically collide one thing, expect exactly that class + severity + a resolution), determinism, notChecked
// honesty, merge laws (seeded property tests) and the resource-pack composer. Pure.
//   tsx --test test/cyrus-conflicts.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { detectConflicts } from "../lib/cyrus/conflicts/engine";
import { canonical, mergeAtlas, mergeFont, mergeLang, mergeSoundsJson, mergeTag, mergeWholeFile } from "../lib/cyrus/conflicts/merge";
import { composeResourcePacks } from "../lib/cyrus/conflicts/resourcepack";
import { inventoryEntries } from "../lib/cyrus/conflicts/normalize";
import type { ConflictClass, ConflictContext, ConflictReport, ModEntry, Severity } from "../lib/cyrus/conflicts/types";
import { entriesOf, goodMod, shopPlugin, type ModFx } from "./_cyrus-modfixture";
import { scanServer } from "../lib/cyrus/inventory/scan";

const A = "nx_aaaa1111", B = "nx_bbbb2222";
const CTX: ConflictContext = { mcVersion: "1.21.11", software: "paper", modPack: true };
async function run(mods: ModFx[], ctx: ConflictContext = CTX): Promise<ConflictReport> {
  const entries: ModEntry[] = [];
  for (const m of mods) entries.push(...(await entriesOf(m)));
  return detectConflicts(entries, ctx);
}
const brief = (r: ConflictReport) => r.findings.map((f) => `${f.severity} ${f.class} ${f.subject}`);

describe("false-positive guard", () => {
  it("two good Cyrus mods (own namespaces) + a clean third-party plugin -> zero findings", async () => {
    const r = await run([goodMod(A, "alpha"), goodMod(B, "beta"), shopPlugin()]);
    assert.deepEqual(brief(r), []);
    assert.equal(r.blocking, false);
    assert.deepEqual(r.notChecked, []);
  });
  it("one mod alone, and the same set on 26.2 -> zero findings", async () => {
    assert.deepEqual(brief(await run([goodMod(A, "alpha")])), []);
    assert.deepEqual(brief(await run([goodMod(A, "alpha"), goodMod(B, "beta")], { ...CTX, mcVersion: "26.2" })), []);
  });
});

type Mutation = { name: string; mutate: (a: ModFx, b: ModFx) => ModFx[] | void; expect: [ConflictClass, Severity][]; ctx?: Partial<ConflictContext>; resolution?: string };
const MUTATIONS: Mutation[] = [
  { name: "same plugin name", mutate: (_a, b) => { b.name = "NxAlpha"; }, expect: [["plugin.duplicate_name", "blocking"]], resolution: "remove_one" },
  { name: "same main class, different name", mutate: (a, b) => { b.main = `dev.cyrus.${a.tag}.Main`; }, expect: [["plugin.duplicate_main", "warn"]] },
  { name: "same command label", mutate: (_a, b) => { b.commands[0].name = "alphagem"; }, expect: [["command.label_collision", "warn"]], resolution: "alias_rewrite" },
  { name: "alias vs alias", mutate: (_a, b) => { b.commands[0].aliases = ["alphag"]; }, expect: [["command.alias_collision", "info"]] },
  { name: "vanilla command override", mutate: (_a, b) => { b.commands[0].name = "give"; }, expect: [["command.vanilla_override", "warn"]], resolution: "alias_rewrite" },
  { name: "Brigadier root vs plugin.yml label", mutate: (_a, b) => { b.brigadier = ["alphagem"]; }, expect: [["command.label_collision", "warn"]] },
  { name: "same permission node", mutate: (a, b) => { b.perms.push({ name: `${a.ns}.use`, default: "true" }); }, expect: [["permission.duplicate", "warn"]] },
  { name: "same permission, different default", mutate: (a, b) => { b.perms.push({ name: `${a.ns}.use`, default: "op" }); }, expect: [["permission.default_mismatch", "warn"], ["permission.duplicate", "warn"]] },
  { name: "missing hard dependency", mutate: (_a, b) => { b.depend = ["Vault"]; }, expect: [["dependency.missing", "blocking"]] },
  { name: "dependency cycle", mutate: (a, b) => { a.depend = [b.name]; b.depend = [a.name]; }, expect: [["dependency.cycle", "blocking"]] },
  { name: "loadbefore cycle", mutate: (a, b) => { a.loadbefore = [b.name]; b.loadbefore = [a.name]; }, expect: [["dependency.loadbefore_cycle", "warn"]] },
  { name: "api-version newer than the server", mutate: (_a, b) => { b.api = "1.21.11"; }, ctx: { mcVersion: "1.21.8" }, expect: [["platform.api_version", "blocking"]] },
  { name: "Java 25 classes on a Java 21 server", mutate: (_a, b) => { b.major = 69; }, expect: [["platform.java", "blocking"]] },
  { name: "Folia without folia-supported", mutate: () => {}, ctx: { software: "folia" }, expect: [["platform.folia", "blocking"], ["platform.folia", "blocking"]] },
  { name: "item models on 1.21.1", mutate: (a) => { a.api = "1.21"; return [a]; }, ctx: { mcVersion: "1.21.1" }, expect: [["platform.item_model_version", "blocking"]] },
  { name: "two plugins mutate the same event at the same priority", mutate: (a, b) => { const e = { event: "org/bukkit/event/player/PlayerJoinEvent", priority: "HIGH", kind: "mutate" as const }; a.events.push(e); b.events.push({ ...e }); }, expect: [["event.overlap", "warn"]], resolution: "load_order" },
  { name: "MONITOR handler mutates", mutate: (_a, b) => { b.events.push({ event: "org/bukkit/event/player/PlayerQuitEvent", priority: "MONITOR", kind: "mutate" }); }, expect: [["event.monitor_mutation", "warn"]] },
  { name: "same explicit NamespacedKey", mutate: (_a, b) => { const s = shopPlugin(); s.keys = [["shared", "coins"]]; b.keys.push(["shared", "coins"]); return [_a, b, s]; }, expect: [["key.namespacedkey", "warn"]], resolution: "reserved_namespace" },
  { name: "Cyrus mod uses another project's namespace", mutate: (a, b) => { b.keys.push([a.ns!, "stolen"]); }, expect: [["key.namespace_foreign", "warn"]] },
