describe("mutation corpus: each collision is caught with the right class and severity", () => {
  for (const mu of MUTATIONS) {
    it(mu.name, async () => {
      const a = goodMod(A, "alpha"), b = goodMod(B, "beta");
      const set = mu.mutate(a, b) ?? [a, b];
      const r = await run(set, { ...CTX, ...(mu.ctx ?? {}) });
      const got = r.findings.map((f) => [f.class, f.severity] as [ConflictClass, Severity]).sort();
      assert.deepEqual(got, [...mu.expect].sort(), `findings: ${JSON.stringify(brief(r))}`);
      for (const f of r.findings) {
        assert.ok(f.items.length >= 1 && f.items.every((i) => i.evidence), "every finding has evidence");
        assert.ok(f.resolution.text.length > 0, "every finding has a resolution suggestion");
      }
      if (mu.resolution) assert.ok(r.findings.some((f) => f.resolution.kind === mu.resolution), `resolution ${mu.resolution} in ${r.findings.map((f) => f.resolution.kind)}`);
      assert.equal(r.blocking, mu.expect.some(([, s]) => s === "blocking"));
    });
  }
  it("covers every conflict class at least once", async () => {
    const { CONFLICT_CLASSES } = await import("../lib/cyrus/conflicts/types");
    const covered = new Set(MUTATIONS.flatMap((m) => m.expect.map(([c]) => c)));
    assert.deepEqual(CONFLICT_CLASSES.filter((c) => !covered.has(c)), []);
  });
});

describe("engine properties", () => {
  it("is deterministic: any input order gives the identical report", async () => {
    const a = goodMod(A, "alpha"), b = goodMod(B, "beta");
    b.commands[0].name = "alphagem"; b.perms.push({ name: `${A}.use`, default: "op" }); a.economy = b.economy = true;
    const entries: ModEntry[] = [...(await entriesOf(a)), ...(await entriesOf(b)), ...(await entriesOf(shopPlugin()))];
    const ref = canonical(detectConflicts(entries, CTX));
    let seed = 42; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    for (let i = 0; i < 20; i++) assert.equal(canonical(detectConflicts([...entries].sort(() => rnd() - 0.5), CTX)), ref);
  });
  it("finding ids are stable and alias rewrites propose a namespaced label", async () => {
    const a = goodMod(A, "alpha"), b = goodMod(B, "beta"); b.commands[0].name = "alphagem";
    const r1 = await run([a, b]), r2 = await run([b, a]);
    assert.deepEqual(r1.findings.map((f) => f.id), r2.findings.map((f) => f.id));
    const f = r1.findings.find((x) => x.class === "command.label_collision")!;
    assert.deepEqual(f.resolution.proposal, { rewrites: [{ mod: "member:alpha", from: "alphagem", to: "aaaaalphagem" }, { mod: "member:beta", from: "alphagem", to: "bbbbalphagem" }] });
  });
  it("missing data is reported as not checked, never as clean", () => {
    const e: ModEntry = { id: "server:plugins/X.jar", label: "X", kind: "plugin", origin: "server", cyrus: null, plugin: { descriptor: null, bytecode: null } };
    const r = detectConflicts([e], {});
    assert.equal(r.findings.length, 0);
    assert.equal(r.notChecked.length, 3);
    assert.ok(r.notChecked.some((n) => /version unknown/.test(n)));
  });
  it("runs on a real inventory report (server-origin entries)", async () => {
    const { fakeServer } = await import("./cyrus-inventory.test");
    const fs = { files: fakeServer(), async stat(p: string) { const f = this.files.get(p); return f ? { type: "file" as const, size: f.length } : [...this.files.keys()].some((k) => k.startsWith(p + "/")) ? { type: "dir" as const, size: 0 } : null; }, async readFile(p: string) { return this.files.get(p) ?? null; }, async list(d: string) { return [...new Set([...this.files.keys()].filter((k) => k.startsWith(d + "/")).map((k) => k.slice(d.length + 1).split("/")[0]))]; } };
    const inv = await scanServer(fs);
    const { mods, ctx } = inventoryEntries(inv);
    const cand = await entriesOf(goodMod(A, "alpha"));
    const r = detectConflicts([...mods, ...cand], ctx);
    assert.ok(r.findings.some((f) => f.class === "rp.existing_owner" && f.subject === "plugin:Oraxen"));
    assert.ok(r.findings.some((f) => f.class === "dependency.missing" && f.subject.startsWith("Rich -> Vault")));
    assert.ok(r.findings.some((f) => f.class === "datapack.vanilla_override"));
  });
});

// ---- merge laws: seeded property tests ---------------------------------------------------------------------------
function prng(seed: number) { let s = seed >>> 0; return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; }
const pick = <T>(r: () => number, xs: T[]) => xs[Math.floor(r() * xs.length)];
function genSounds(r: () => number, keys: string[]) { const o: Record<string, unknown> = {}; for (const k of keys) if (r() < 0.6) o[k] = { sounds: Array.from({ length: 1 + Math.floor(r() * 3) }, () => pick(r, ["a:x", "a:y", { name: "b:z", volume: 0.5 }, "c:w"])), ...(r() < 0.15 ? { replace: true } : {}), ...(r() < 0.3 ? { subtitle: pick(r, ["s.one", "s.two"]) } : {}) }; return o; }
function genLang(r: () => number, keys: string[]) { const o: Record<string, string> = {}; for (const k of keys) if (r() < 0.6) o[k] = pick(r, ["A", "B", "C"]); return o; }
function genTag(r: () => number) { return { ...(r() < 0.2 ? { replace: true } : {}), values: Array.from({ length: Math.floor(r() * 4) }, () => pick(r, ["minecraft:a", "minecraft:b", "x:c", "#x:t", { id: "y:d", required: false }])) }; }
function permute<T>(r: () => number, xs: T[]) { const a = [...xs]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

describe("merge laws (property tests, 300 seeded cases each)", () => {
  const keys = ["k1", "k2", "k3", "k4", "k5"];
  for (const [name, gen, merge, keysOf] of [
    ["sounds.json", (r: () => number) => genSounds(r, keys), mergeSoundsJson, (v: unknown) => Object.keys(v as object)],
    ["lang", (r: () => number) => genLang(r, keys), mergeLang, (v: unknown) => Object.keys(v as object)],
  ] as const) {
    it(`${name}: idempotent, no key loss, order-stable when conflict-free, deterministic`, () => {
      for (let seed = 1; seed <= 300; seed++) {
        const r = prng(seed);
        const xs = Array.from({ length: 1 + Math.floor(r() * 4) }, () => gen(r));
        const m = (merge as (i: unknown[]) => { value: unknown; conflicts: unknown[] })(xs);
        assert.equal(canonical((merge as (i: unknown[]) => { value: unknown })([xs[0], xs[0]]).value), canonical((merge as (i: unknown[]) => { value: unknown })([xs[0]]).value), `idempotent a,a seed ${seed}`);
        assert.equal(canonical((merge as (i: unknown[]) => { value: unknown })([m.value]).value), canonical(m.value), `idempotent merge(merge) seed ${seed}`);
        const union = new Set(xs.flatMap((x) => keysOf(x)));
        assert.deepEqual(new Set(keysOf(m.value)), union, `no key loss seed ${seed}`);
        assert.equal(canonical((merge as (i: unknown[]) => { value: unknown })(xs).value), canonical(m.value), "deterministic");
        if (m.conflicts.length === 0) for (let k = 0; k < 3; k++) assert.equal(canonical((merge as (i: unknown[]) => { value: unknown })(permute(r, xs)).value), canonical(m.value), `order-stable seed ${seed}`);
      }
    });
  }
  it("tags: Minecraft replace semantics; idempotent; values kept unless a replace:true reports dropping them", () => {
    for (let seed = 1; seed <= 300; seed++) {
      const r = prng(seed);
      const xs = Array.from({ length: 1 + Math.floor(r() * 4) }, () => genTag(r));
      const m = mergeTag(xs);
      assert.equal(canonical(mergeTag([xs[0], xs[0]]).value), canonical(mergeTag([xs[0]]).value));
      assert.equal(canonical(mergeTag([m.value]).value), canonical(m.value));
      const id = (v: unknown) => (typeof v === "string" ? v : (v as { id: string }).id);
      const lastReplace = xs.map((x) => !!(x as { replace?: boolean }).replace).lastIndexOf(true);
      const expected = new Set(xs.slice(Math.max(0, lastReplace)).flatMap((x) => x.values.map(id)));
      assert.deepEqual(new Set(m.value.values.map(id)), expected, `values seed ${seed}`);
      const lost = new Set(xs.flatMap((x) => x.values.map(id))).size > expected.size;
      if (lost) assert.ok(m.conflicts.some((c) => c.kind === "replace"), `loss reported seed ${seed}`);
      if (!xs.some((x) => (x as { replace?: boolean }).replace)) for (let k = 0; k < 3; k++) assert.deepEqual(new Set(mergeTag(permute(r, xs)).value.values.map(id)), expected, "same value set in any order");
    }
  });
  it("whole files, atlases and fonts", () => {
    assert.deepEqual(mergeWholeFile([{ a: 1 }, { a: 1 }]).conflicts, []);
    assert.equal(mergeWholeFile([{ a: 1 }, { a: 2 }]).conflicts[0].kind, "override");
    assert.deepEqual(mergeWholeFile([{ a: 1 }, { a: 2 }]).value, { a: 2 });
    assert.equal(mergeAtlas([{ sources: [{ type: "d", source: "a" }] }, { sources: [{ source: "a", type: "d" }, { type: "d", source: "b" }] }]).value.sources.length, 2);
    const f = mergeFont([{ providers: [{ type: "bitmap", chars: ["\uE001\uE002"] }] }, { providers: [{ type: "bitmap", chars: ["\uE002"] }] }]);
    assert.deepEqual(f.conflicts.map((c) => c.key), ["U+E002"]);
    assert.equal(mergeSoundsJson(["x" as unknown]).conflicts[0].kind, "invalid");
  });
});

describe("resource-pack composer", () => {
  const mk = (files: Record<string, string>) => Object.entries(files).map(([path, d]) => ({ path, data: Buffer.from(d) }));
  it("merges sounds/lang, keeps the top whole file, writes its own pack.mcmeta, deterministic", () => {
    const lo = { name: "lo", files: mk({ "pack.mcmeta": "{}", "assets/a/sounds.json": '{"x":{"sounds":["a:1"]}}', "assets/a/lang/en_us.json": '{"k":"lo"}', "assets/a/models/m.json": '{"v":"lo"}' }) };
    const hi = { name: "hi", files: mk({ "pack.mcmeta": "{}", "assets/a/sounds.json": '{"x":{"sounds":["a:2"]},"y":{"sounds":["a:3"]}}', "assets/a/lang/en_us.json": '{"k":"hi","j":"x"}', "assets/a/models/m.json": '{"v":"hi"}' }) };
    const mcmeta = { pack: { pack_format: 75, description: "Mod Pack" } };
    const r = composeResourcePacks([lo, hi], mcmeta);
    assert.equal(r.ok, true);
    const get = (p: string) => JSON.parse(r.files.find((f) => f.path === p)!.data.toString());
    assert.deepEqual(get("assets/a/sounds.json"), { x: { sounds: ["a:1", "a:2"] }, y: { sounds: ["a:3"] } });
    assert.deepEqual(get("assets/a/lang/en_us.json"), { j: "x", k: "hi" });
    assert.deepEqual(get("assets/a/models/m.json"), { v: "hi" });
    assert.deepEqual(get("pack.mcmeta"), mcmeta);
    assert.deepEqual(r.conflicts.map((c) => [c.path, c.cls]), [["assets/a/lang/en_us.json", "lang"], ["assets/a/models/m.json", "whole"]]);
    assert.equal(canonical(composeResourcePacks([lo, hi], mcmeta).files.map((f) => [f.path, f.data.toString("hex")])), canonical(r.files.map((f) => [f.path, f.data.toString("hex")])));
  });
  it("refuses to merge shaders from two packs", () => {
    const r = composeResourcePacks([{ name: "a", files: mk({ "assets/minecraft/shaders/core/x.fsh": "a" }) }, { name: "b", files: mk({ "assets/minecraft/shaders/core/y.fsh": "b" }) }], {});
    assert.equal(r.ok, false);
    assert.equal(r.unmergeable.length, 2);
  });
});

