// Cyrus Mod Packs (R2): the `nxpack.json` manifest. Shaped like Modrinth's mrpack (formatVersion, files[] with
// path/hashes/downloads/env/fileSize, an overrides dir, dependencies.minecraft) but for a Paper SERVER:
//  - third-party jars are included BY REFERENCE (https download + sha1 + sha512), never embedded or re-hosted;
//  - only Cyrus-built artifacts are embedded (under `overrides/` in the .nxpack archive), each with its hashes;
//  - it can never contain a Minecraft/Paper server jar (path rules + the registry's pinned server sha256s);
//  - it carries what the builder decided: members in priority order, resource-pack mode (one merged pack or an
//    ordered list for the Pack Loader), the conflict report summary, a compatibility matrix and a changelog.
// Pure + client-safe. Zod is the code contract; `nxPackJsonSchema()` / nxpack.v1.schema.json the portable one.
import { z } from "zod";
import { VERSIONS, getVersion } from "../versions/registry";

export const NXPACK_FORMAT_VERSION = 1 as const;
export const NXPACK_FILE = "nxpack.json";
export const OVERRIDES_DIR = "overrides";

const sha1 = z.string().regex(/^[0-9a-f]{40}$/);
const sha256 = z.string().regex(/^[0-9a-f]{64}$/);
const sha512 = z.string().regex(/^[0-9a-f]{128}$/);
const memberId = z.string().regex(/^[a-z0-9][a-z0-9_-]{0,63}$/);
const semver = z.string().regex(/^(0|[1-9]\d{0,5})\.(0|[1-9]\d{0,5})\.(0|[1-9]\d{0,5})$/);
const fileName = z.string().regex(/^[A-Za-z0-9][A-Za-z0-9 ._+()-]{0,120}$/);
/** Where a file goes, relative to the server root: plugin jars, world datapacks, plugin config files. */
export const SERVER_PATH_RE = /^(plugins\/[A-Za-z0-9][A-Za-z0-9 ._+()-]{0,120}\.jar|datapacks\/[A-Za-z0-9][A-Za-z0-9 ._+()-]{0,120}\.zip|config\/[A-Za-z0-9][A-Za-z0-9_-]{0,63}\/[A-Za-z0-9][A-Za-z0-9 ._-]{0,120})$/;
