}

export async function buildModPack(input: BuildInput): Promise<BuildOk | BuildFail> {
  const errors: string[] = [];
  if (!/^mp_[a-z0-9]{12}$/.test(input.packId)) errors.push("packId must be mp_ + 12 lowercase letters/digits");
  const ver = getVersion(input.mcVersion);
  if (!ver) errors.push(`Minecraft ${input.mcVersion} is not in the version registry`);
  if (!input.members.length) errors.push("a Mod Pack needs at least one member");
  const ids = new Set<string>();
  for (const m of input.members) {
    if (ids.has(m.id)) errors.push(`member ${m.id} appears twice`);
    ids.add(m.id);
    if (m.origin === "cyrus" && (!m.artifact || !m.project)) errors.push(`${m.id}: a Cyrus member needs its artifact and project revision`);
    if (m.origin === "thirdparty" && !m.ref) errors.push(`${m.id}: a third-party member is included by reference (url + sha1 + sha512)`);
    if (m.origin === "thirdparty" && m.kind === "resourcepack") errors.push(`${m.id}: third-party resource packs are not supported in a Mod Pack yet`);
    const name = m.artifact?.name ?? m.ref?.name ?? "";
    if (!SAFE_NAME.test(name)) errors.push(`${m.id}: file name '${name.slice(0, 60)}' is not allowed`);
    if (m.kind === "plugin" && !/\.jar$/i.test(name)) errors.push(`${m.id}: a plugin must be a .jar`);
    if (m.kind !== "plugin" && !/\.zip$/i.test(name)) errors.push(`${m.id}: datapacks and resource packs are .zip files`);
    if (SERVER_JAR_NAME_RE.test(`plugins/${name}`)) errors.push(`${m.id}: ${name} looks like a server jar; a Mod Pack never contains server software`);
    if (m.ref && m.artifact) {
      if (h("sha1", m.artifact.bytes) !== m.ref.sha1 || h("sha512", m.artifact.bytes) !== m.ref.sha512 || m.artifact.bytes.length !== m.ref.size) return { ok: false, code: "hash_mismatch", errors: [`${m.id}: downloaded bytes do not match the declared hashes/size`], report: null };
    }
    if (m.ref && !/^https:\/\//.test(m.ref.url)) errors.push(`${m.id}: downloads must be https`);
  }
  if (errors.length) return { ok: false, code: "invalid_input", errors, report: null };

  // ---- inspect members -> conflict entries -----------------------------------------------------------------
  const prevMembers = new Map((input.previous?.members ?? []).map((m) => [m.id, m]));
  const prevHash = new Map([...(input.previous?.files ?? []), ...(input.previous?.embedded ?? [])].map((f) => [f.member, f.hashes.sha1]));
  const entries: ModEntry[] = [];
  const rpInputs: { member: MemberInput; files: { path: string; data: Buffer }[] }[] = [];
  for (const m of input.members) {
    const bytes = m.artifact?.bytes ?? null;
    const sha1 = bytes ? h("sha1", bytes) : m.ref!.sha1;
    const changed = !prevMembers.has(m.id) || prevHash.get(m.id) !== sha1;
    const cyrus = m.project ? { namespace: m.project.namespace, projectId: m.project.projectId } : null;
    const id = `member:${m.id}`;
    if (m.kind === "plugin") {
      if (bytes) entries.push(candidateJar(m.artifact!.name, bytes, { id, cyrus, changed, budgets: m.budgets }));
      else entries.push({ id, label: m.label, kind: "plugin", origin: "candidate", cyrus, changed, plugin: { descriptor: null, bytecode: null }, budgets: m.budgets });
      entries[entries.length - 1].label = m.label;
    } else {
      const files = unzipAll(bytes!);
      if (typeof files === "string") return { ok: false, code: "invalid_input", errors: [`${m.id}: ${files}`], report: null };
      if (m.kind === "datapack") {
        const mc = files.find((f) => f.path === "pack.mcmeta")?.data ?? null;
        entries.push(datapackEntry(await indexDatapack(m.artifact!.name, "candidate", "zip", files.filter((f) => f.path.startsWith("data/")).map((f) => ({ path: f.path, read: () => f.data })), mc), "candidate", { id, cyrus, changed }));
      } else {
        entries.push(resourcePackEntry(m.artifact!.name, files, "candidate", { id, cyrus, changed }));
        rpInputs.push({ member: m, files });
      }
      entries[entries.length - 1].label = m.label;
    }
  }
  const inv = input.inventory ? inventoryEntries(input.inventory, { exclude: (p) => (input.ownedPaths ?? []).includes(p) }) : null;
  const report = detectConflicts([...entries, ...(inv?.mods ?? [])], { ...(inv?.ctx ?? {}), mcVersion: input.mcVersion, javaRelease: ver!.javaRelease, modPack: true });

  // ---- policy: blocking refuses; user decisions refuse when asked ------------------------------------------
  if (report.blocking) return { ok: false, code: "blocking_conflicts", errors: report.findings.filter((f) => f.severity === "blocking").map((f) => `${f.class}: ${f.message}`), report };
  const ack = new Set(input.acknowledge ?? []);
  const needs = report.findings.filter((f) => f.severity === "warn" && !f.resolution.auto && f.resolution.kind === "user_decision" && !ack.has(f.id));
  if (input.requireAcknowledged && needs.length) return { ok: false, code: "needs_decision", errors: needs.map((f) => `${f.id} ${f.class}: ${f.message}`), report };

  // ---- resource packs: one merged pack, or an ordered list --------------------------------------------------
  const rpZips: { sha1: string; zip: Buffer }[] = [];
  const packs: NxPack["resourcePacks"]["packs"] = [];
  let mode: NxPack["resourcePacks"]["mode"] = "none";
  const archive: { path: string; data: Buffer }[] = [];
  if (rpInputs.length) {
    if (ver!.status === "preview" && !input.allowPreview) return { ok: false, code: "invalid_input", errors: [`${input.mcVersion} is a preview version: resource packs for it are not verified in a real client yet`], report };
    const pf = resourcePackFormat(input.mcVersion);
    if (!pf.ok) return { ok: false, code: "invalid_input", errors: [pf.error], report };
    const mcmeta = { pack: { pack_format: pf.format.major, supported_formats: { min_inclusive: 46, max_inclusive: 999 }, min_format: 46, max_format: 999, description: `${input.name} (Nxeon Mod Pack ${input.packId})`.slice(0, 100) } };
    const composed = composeResourcePacks(rpInputs.map((r) => ({ name: r.member.id, files: r.files })), mcmeta);
    const groups = composed.ok ? [{ role: "modpack", members: rpInputs.map((r) => r.member.id), files: composed.files }] : rpInputs.map((r, i) => ({ role: `modpack-${i + 1}`, members: [r.member.id], files: r.files }));
    mode = composed.ok ? "merged" : "stacked";
    for (const g of groups) {
      const z = zip(g.files);
      const s1 = h("sha1", z);
      rpZips.push({ sha1: s1, zip: z });
      const embedded = `${OVERRIDES_DIR}/resourcepacks/${s1}.zip`;
      archive.push({ path: embedded, data: z });
      packs.push({ id: packIdFor(input.packId, g.role), role: g.role, sha1: s1, sha256: h("sha256", z), bytes: z.length, embedded, members: g.members, required: false });
    }
  }

  // ---- files ------------------------------------------------------------------------------------------------
  const files: NxPackFile[] = [];
  const embedded: NxPackEmbedded[] = [];
  for (const m of input.members) {
    if (m.kind === "resourcepack") continue;
    const name = m.artifact?.name ?? m.ref!.name;
    const path = m.kind === "plugin" ? `plugins/${name}` : `datapacks/${name}`;
    if (m.origin === "cyrus") {
      const b = m.artifact!.bytes;
      embedded.push({ path, member: m.id, role: m.kind, hashes: { sha1: h("sha1", b), sha512: h("sha512", b), sha256: h("sha256", b) }, fileSize: b.length, env: ENV_SERVER, embedded: `${OVERRIDES_DIR}/${path}` });
      archive.push({ path: `${OVERRIDES_DIR}/${path}`, data: b });
    } else {
      const r = m.ref!;
      files.push({ path, member: m.id, role: m.kind, hashes: { sha1: r.sha1, sha512: r.sha512, ...(m.artifact ? { sha256: h("sha256", m.artifact.bytes) } : {}) }, fileSize: r.size, env: ENV_SERVER, downloads: [r.url] });
    }
    for (const c of m.configs ?? []) {
      if (m.origin !== "cyrus") continue;
      const cp = `config/${c.plugin}/${c.file}`;
      embedded.push({ path: cp, member: m.id, role: "config", hashes: { sha1: h("sha1", c.data), sha512: h("sha512", c.data), sha256: h("sha256", c.data) }, fileSize: c.data.length, env: ENV_SERVER, embedded: `${OVERRIDES_DIR}/${cp}` });
      archive.push({ path: `${OVERRIDES_DIR}/${cp}`, data: c.data });
    }
  }

  // ---- version + changelog ----------------------------------------------------------------------------------
  const prev = input.previous ?? null;
  let versionId = input.versionId ?? (prev ? bumpSemver(prev.versionId, input.bump ?? "patch") : "1.0.0");
  if (prev && cmpSemver(versionId, prev.versionId) <= 0) return { ok: false, code: "invalid_input", errors: [`version ${versionId} must be newer than ${prev.versionId}`], report };
  const members: NxPackMember[] = input.members.map((m) => ({ id: m.id, kind: m.kind, origin: m.origin, label: m.label.slice(0, 120), version: m.version, ...(m.project ? { project: m.project } : {}), ...(m.ref?.provider ? { source: { provider: m.ref.provider } } : {}) }));
  const changes: NxPack["changelog"][number]["changes"] = [];
  const nowHash = new Map([...files, ...embedded].filter((f) => f.role !== "config").map((f) => [f.member, f.hashes.sha1]));
  for (const r of rpInputs) nowHash.set(r.member.id, h("sha1", zip(r.files)));
  for (const m of members) {
    const p = prevMembers.get(m.id);
    if (!p) changes.push({ type: "added", member: m.id, to: m.version });
    else if (p.version !== m.version || (prevHash.has(m.id) && prevHash.get(m.id) !== nowHash.get(m.id))) changes.push({ type: "updated", member: m.id, from: p.version, to: m.version });
  }
  for (const p of prev?.members ?? []) if (!ids.has(p.id)) changes.push({ type: "removed", member: p.id, from: p.version });
  const prevOrder = (prev?.members ?? []).map((m) => m.id).filter((id) => ids.has(id));
  const nowOrder = members.map((m) => m.id).filter((id) => prevMembers.has(id));
  if (prev && canonical(prevOrder) !== canonical(nowOrder)) for (const id of nowOrder.filter((id, i) => prevOrder[i] !== id)) changes.push({ type: "reordered", member: id });
  if (prev && !changes.length && !input.versionId) versionId = prev.versionId;
  if (prev && !changes.length && cmpSemver(versionId, prev.versionId) === 0) return { ok: false, code: "invalid_input", errors: ["nothing changed since the previous version"], report };
  const changelog = [{ versionId, changes }, ...(prev?.changelog ?? [])].slice(0, 50);

  // ---- conflicts summary + compatibility --------------------------------------------------------------------
  const ref = (f: Finding) => ({ findingId: f.id, class: f.class, severity: f.severity, subject: f.subject.slice(0, 300) });
  const conflicts: NxPack["conflicts"] = {
    engine: report.engine, counts: report.counts,
    resolved: report.findings.filter((f) => f.resolution.auto || f.resolution.kind === "none").map((f) => ({ ...ref(f), resolution: f.resolution.text.slice(0, 400) })),
    open: report.findings.filter((f) => !(f.resolution.auto || f.resolution.kind === "none")).map((f) => ({ ...ref(f), acknowledged: ack.has(f.id), resolution: f.resolution.text.slice(0, 400) })),
    notChecked: report.notChecked.map((n) => n.slice(0, 400)),
  };
  const staticStatus = report.counts.warn > 0 ? "warnings" : "clean";
  const versions = [...new Set([input.mcVersion, ...(input.dynamic?.versions.map((v) => v.mcVersion) ?? [])])];
  const compatibility = versions.map((v) => {
    const d = input.dynamic?.versions.find((x) => x.mcVersion === v);
    return { mcVersion: v, static: v === input.mcVersion ? staticStatus : "warnings", dynamic: d?.overall ?? "not_run", evidence: (d?.evidence ?? ["no Test Flight evidence supplied: not run (not a pass)"]).slice(0, 40).map((e) => e.slice(0, 400)) } as NxPack["compatibility"][number];
  });

  const body = {
    formatVersion: NXPACK_FORMAT_VERSION, game: "minecraft" as const, platform: "paper" as const, packId: input.packId, name: input.name.slice(0, 80), ...(input.summary ? { summary: input.summary.slice(0, 500) } : {}),
    versionId, dependencies: { minecraft: input.mcVersion }, members, files, embedded, overrides: archive.length ? [OVERRIDES_DIR as "overrides"] : [],
    resourcePacks: { mode, packs }, datapackOrder: input.members.filter((m) => m.kind === "datapack").map((m) => m.id), conflicts, compatibility, changelog,
  };
  const manifest = { ...body, build: { builder: BUILDER_ID, inputsSha256: h("sha256", Buffer.from(canonical(body))) } };
  const v = validateNxPack(manifest);
  if (!v.ok) return { ok: false, code: "manifest_invalid", errors: v.errors.map((e) => `${e.path}: ${e.message}`), report };
  const all = [{ path: NXPACK_FILE, data: Buffer.from(JSON.stringify(JSON.parse(canonical(v.pack)), null, 2) + "\n") }, ...archive].sort((a, b) => (a.path < b.path ? -1 : 1));
  return { ok: true, manifest: v.pack, archive: all, archiveZip: zip(all), report, resourcePackZips: rpZips };
}

