const check = (r: TestFlightReport | null, id: string) => r?.checks.find((c) => c.id === id) ?? null;
/** Startup-log hit lines without the line number, so two boots can be compared. */
const logHits = (r: TestFlightReport | null) => (check(r, "startup_log_clean")?.evidence ?? []).filter((e) => /^L\d+ \[/.test(e)).map((e) => e.replace(/^L\d+ /, "").replace(/\d{2}:\d{2}:\d{2}/g, "hh:mm:ss"));
/** Reply text of the RCON check `id` (as the runner records it: "<id> '<cmd>': ok|FAILED ... -> <reply>"). */
function rconReply(r: TestFlightReport | null, id: string): string | null {
  const ev = check(r, "rcon_checks")?.evidence.find((e) => e.startsWith(`${id} '`));
  if (!ev) return null;
  const i = ev.indexOf(" -> ");
  return i < 0 ? "" : ev.slice(i + 4);
}

export function mergeDynamic(report: ConflictReport, plan: PlannedFlight[], outcomes: FlightOutcome[], members: DynamicMember[]): DynamicResult {
  const byKey = new Map(outcomes.map((o) => [o.key, o]));
  const desc = new Map(members.map((m) => [m.member, m.descriptor]));
  const res: DynamicResult = { versions: [], findings: [], dynamicOnly: [], flights: [] };
  const ran = (o: FlightOutcome | undefined) => !!o?.summary && !!o.report && o.report.status === "completed";
  for (const p of plan) {
    const o = byKey.get(p.key);
    res.flights.push({ key: p.key, role: p.role, mcVersion: p.mcVersion, without: p.without, overall: o?.summary?.overall ?? (o?.error ? "error" : "not_run"), runId: o?.report?.runId ?? null, bootMs: o?.report?.bootMs ?? null, peakRssKb: o?.report?.peakRssKb ?? null });
  }
  const owner = (reply: string | null, label: string): string | null => {
    if (reply == null) return null;
    const hits = members.filter((m) => (m.descriptor?.commands ?? []).some((c) => c.name === label && c.description && reply.includes(c.description)));
    return hits.length === 1 ? hits[0].member : null;
  };
