    const comb = plan.find((p) => p.mcVersion === v && p.role === "combined")!;
    const co = byKey.get(comb.key);
    const ev: string[] = [];
    let overall: DynamicResult["versions"][number]["overall"];
    if (!co) { overall = "not_run"; ev.push(`${v}: combined boot not run`); }
    else if (!ran(co)) { overall = "incomplete"; ev.push(`${v}: combined boot did not complete (${co.report?.status ?? co.error ?? "no report"})`); }
    else {
      overall = co.summary!.success ? "passed" : co.summary!.overall === "failed" ? "failed" : "incomplete";
      ev.push(`${v}: combined boot ${co.summary!.overall} (${co.summary!.passed.length} checks passed${co.summary!.failed.length ? `, failed: ${co.summary!.failed.join(", ")}` : ""})`);
