      const o = byKey.get(p.key);
      if (!ran(o)) { if (overall === "passed") overall = "incomplete"; ev.push(`${v}: differential boot without ${p.without} did not run (${o?.report?.status ?? o?.error ?? "not run"}): not a pass`); continue; }
      ev.push(`${v}: differential boot without ${p.without}: ${o!.summary!.overall}`);
      if (ran(co)) {
        const base = new Set(logHits(o!.report));
        for (const line of logHits(co!.report)) if (!base.has(line)) res.dynamicOnly.push({ kind: "new_error_line", mcVersion: v, member: p.without, evidence: `only with ${p.without}: ${line}` });
        for (const c of p.spec.rcon ?? []) {
          if (!c.id?.startsWith("help-")) continue;
          const label = c.id.slice(5);
          const withM = owner(rconReply(co!.report, c.id), label), without = owner(rconReply(o!.report, c.id), label);
          if (withM && without && withM !== without) res.dynamicOnly.push({ kind: "command_owner_changed", mcVersion: v, member: p.without, evidence: `/${label} is answered by ${withM} with ${p.without} installed, by ${without} without it` });
        }
      }
    }
    if (ran(co)) for (const c of comb.spec.rcon ?? []) {
      if (!c.id?.startsWith("help-")) continue;
      const label = c.id.slice(5);
      const reply = rconReply(co!.report, c.id);
      commandOwners.set(`${v}|${label}`, owner(reply, label));
      if (reply != null && /No help for/i.test(reply)) res.dynamicOnly.push({ kind: "command_missing", mcVersion: v, member: null, evidence: `/${label}: ${reply.slice(0, 160)}` });
    }
    res.versions.push({ mcVersion: v, overall, evidence: ev });
  }
