  for (const f of report.findings) {
    const fd: FindingDynamic = { findingId: f.id, class: f.class, subject: f.subject, dynamic: "not_run", evidence: [] };
    if (!OBSERVABLE.has(f.class)) { fd.dynamic = "not_observable"; fd.evidence.push("a server boot without players cannot show this class"); res.findings.push(fd); continue; }
    const combined = versions.map((v) => byKey.get(`${v}:combined`)).filter((o) => ran(o));
    if (!combined.length) { res.findings.push(fd); continue; }
    fd.dynamic = "not_observed";
    for (const v of versions) {
      const co = byKey.get(`${v}:combined`);
      if (!ran(co)) continue;
      if (f.class.startsWith("command.")) {
        const label = f.subject.replace(/^\//, "");
        const ow = commandOwners.get(`${v}|${label}`);
        const involved = [...new Set(f.items.map((i) => i.mod.replace(/^member:/, "")))];
        if (ow && involved.length >= 2 && involved.includes(ow)) { fd.dynamic = "confirmed"; fd.evidence.push(`${v}: /${label} is answered by ${ow} only; ${involved.filter((x) => x !== ow).join(", ")} reachable only as /<plugin>:${label}`); }
        else if (ow === null && commandOwners.has(`${v}|${label}`)) fd.evidence.push(`${v}: help /${label} did not name a single owner`);
      } else {
        const needle = f.class.startsWith("permission.") ? f.subject : f.class === "plugin.duplicate_name" ? f.subject : null;
        const lines = [...logHits(co!.report), ...(check(co!.report, "startup_log_clean")?.evidence ?? [])];
        const hit = needle ? lines.find((l) => l.toLowerCase().includes(needle.toLowerCase())) : null;
        const notEnabled = res.dynamicOnly.find((d) => d.kind === "plugin_not_enabled" && d.mcVersion === v && f.items.some((i) => d.evidence.includes(desc.get(i.mod.replace(/^member:/, ""))?.name ?? "\u0000")));
        if (hit) { fd.dynamic = "confirmed"; fd.evidence.push(`${v}: log ${hit.slice(0, 240)}`); }
        else if (notEnabled) { fd.dynamic = "confirmed"; fd.evidence.push(`${v}: ${notEnabled.evidence.slice(0, 240)}`); }
      }
    }
    if (fd.dynamic === "not_observed") fd.evidence.push("the boots ran but showed nothing for this finding");
    res.findings.push(fd);
  }
  return res;
}

