export type FlightOutcome = { key: string; summary: TestFlightSummary | null; report: TestFlightReport | null; error?: string };

export type FindingDynamic = { findingId: string; class: string; subject: string; dynamic: "confirmed" | "not_observed" | "not_observable" | "not_run"; evidence: string[] };
export type DynamicOnly = { kind: "new_error_line" | "plugin_not_enabled" | "command_owner_changed" | "command_missing"; mcVersion: string; member: string | null; evidence: string };
export type DynamicResult = {
  versions: { mcVersion: string; overall: "passed" | "failed" | "incomplete" | "not_run"; evidence: string[] }[];
  findings: FindingDynamic[];
  dynamicOnly: DynamicOnly[];
  flights: { key: string; role: PlannedFlight["role"]; mcVersion: string; without: string | null; overall: string; runId: string | null; bootMs: number | null; peakRssKb: number | null }[];
};

const MAX_HELP_CHECKS = 12;
/** Finding classes a server boot (no player) can show evidence for. */
const OBSERVABLE = new Set(["command.label_collision", "command.alias_collision", "command.vanilla_override", "permission.duplicate", "permission.default_mismatch", "plugin.duplicate_name", "dependency.missing", "dependency.cycle", "platform.api_version", "platform.java", "recipe.key"]);

export function planDynamicChecks(input: { mcVersions: string[]; members: DynamicMember[]; datapacks?: (ArtifactRef & { name: string })[]; report: ConflictReport; extraRcon?: RconCheck[] }): PlannedFlight[] {
  const members = [...input.members].sort((a, b) => (a.member < b.member ? -1 : 1));
  const names = members.map((m) => m.descriptor?.name).filter((n): n is string => !!n);
  const labels = [...new Set(members.flatMap((m) => (m.descriptor?.commands ?? []).map((c) => c.name)))].sort().slice(0, MAX_HELP_CHECKS);
  const flagged = new Set<string>();
  for (const f of input.report.findings) {
    if (f.severity === "info") continue;
    const ids = [...new Set(f.items.map((i) => i.mod.replace(/^member:/, "")))];
    if (ids.length >= 2) for (const id of ids) flagged.add(id);
  }
  const rcon = (present: DynamicMember[]): RconCheck[] => [
    { id: "plugins", command: "plugins", expect: present.map((m) => m.descriptor?.name).filter((n): n is string => !!n) },
    ...labels.map((l) => ({ id: `help-${l}`, command: `help ${l}`, expectNot: ["No help for"], required: false })),
    ...(input.extraRcon ?? []),
  ];
  const out: PlannedFlight[] = [];
  for (const v of input.mcVersions) {
    out.push({ key: `${v}:combined`, role: "combined", mcVersion: v, without: null, members: members.map((m) => m.member), spec: { version: v, plugins: members.map((m) => m.artifact), datapacks: input.datapacks, rcon: rcon(members) } });
    for (const m of members) {
      if (!m.changed || !flagged.has(m.member) || members.length < 2) continue;
      const rest = members.filter((x) => x.member !== m.member);
      out.push({ key: `${v}:without:${m.member}`, role: "differential", mcVersion: v, without: m.member, members: rest.map((x) => x.member), spec: { version: v, plugins: rest.map((x) => x.artifact), datapacks: input.datapacks, rcon: rcon(rest) } });
    }
