// Cyrus Mod Packs (R2): install / update / uninstall a pack AS ONE UNIT. All-or-nothing:
//   validate -> fetch + verify every artifact (and publish resource packs) BEFORE touching the server ->
//   preflight (never overwrite a file the pack does not own) -> snapshot every path the change can touch
//   (backup copies) -> remove dropped members -> place members -> Pack Loader entries -> unit record -> verify.
// Any failure after the snapshot restores the exact previous bytes of every snapshotted path (and removes paths that
// did not exist), then re-verifies the restore and reports it honestly.
// HOST SEAM: everything goes through injected interfaces: `UnitFs` (a GuestFs-shaped subset: Nxeon's SshGuestFs /
// LocalGuestFs satisfy it structurally), `MemberPlacer` (default: staged writes; ./engine-placer.ts places through
// the Mods engine), `ArtifactFetcher` (third-party downloads) and `PackPublisher` (pack hosting). Nothing here
// imports Nxeon code; nothing here is called by any live route or job yet.
import { createHash } from "node:crypto";
import { LOADER_CONFIG_PATH, serializeLoaderConfig, validateLoaderConfig, type LoaderConfig } from "../packhost/loader-config";
import { canonical } from "../conflicts/merge";
import { validateNxPack, type NxPack, type NxPackFile, type NxPackMember } from "./manifest";

export interface UnitFs {
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  rename(from: string, to: string): Promise<void>;
  remove(p: string): Promise<void>;
  list(dir: string): Promise<string[]>;
  copy(from: string, to: string): Promise<void>;
}
export type PlacedFile = { target: string; data: Buffer; sha256: string; role: "plugin" | "datapack" | "config" };
export interface MemberPlacer {
  /** Extra state files the placer itself writes (e.g. the Mods engine's state.json); snapshotted and restored too. */
  readonly statePaths: string[];
  place(m: { member: NxPackMember; files: PlacedFile[] }): Promise<void>;
  remove(m: { memberId: string; targets: string[] }): Promise<void>;
}
export type ArtifactFetcher = (f: NxPackFile) => Promise<Buffer>;
export type PackPublisher = (zip: Buffer, sha1: string) => Promise<{ url: string }>;

export type UnitRecord = { schema: 1; packId: string; versionId: string; manifestSha256: string; files: { path: string; sha256: string; member: string }[]; loaderIds: string[]; installedAt: string };
export type UnitStep = "validate" | "fetch" | "preflight" | "snapshot" | "remove" | "place" | "packloader" | "record" | "verify";
export type RollbackReport = { attempted: boolean; ok: boolean; restored: number; removed: number; mismatches: string[] };
export type UnitResult =
  | { ok: true; action: "installed" | "updated" | "unchanged" | "uninstalled"; record: UnitRecord | null; changed: string[]; restartRequired: boolean }
  | { ok: false; step: UnitStep; error: string; rollback: RollbackReport };

export type UnitDeps = { fs: UnitFs; placer?: MemberPlacer; fetch?: ArtifactFetcher; publish?: PackPublisher; now?: () => Date; recordDir?: string; backupDir?: string };
