const sha = (alg: "sha1" | "sha256" | "sha512", b: Buffer) => createHash(alg).update(b).digest("hex");
const NO_ROLLBACK: RollbackReport = { attempted: false, ok: true, restored: 0, removed: 0, mismatches: [] };
const errMsg = (e: unknown) => (e instanceof Error ? e.message : String(e)).slice(0, 400);

/** Staged writes (part file + rename) straight through the fs. */
export function fsPlacer(fs: UnitFs): MemberPlacer {
