  const v = validateNxPack(args.manifest);
  if (!v.ok) return fail("validate", v.errors.map((e) => `${e.path}: ${e.message}`).join("; "));
  const pack: NxPack = v.pack;
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(level)) return fail("validate", "level name is not a plain folder name");
  const rec = `${recordPath}/${pack.packId}.json`;
  const manifestSha256 = sha("sha256", Buffer.from(canonical(pack)));

  // 2. fetch + verify everything (no server writes yet), publish resource packs (immutable, content-addressed)
  const placed = new Map<string, PlacedFile[]>();
  try {
    for (const f of pack.embedded) {
      const b = args.archive.get(f.embedded);
      if (!b) throw new Error(`${f.embedded} is missing from the pack archive`);
      if (sha("sha1", b) !== f.hashes.sha1 || sha("sha512", b) !== f.hashes.sha512 || sha("sha256", b) !== f.hashes.sha256 || b.length !== f.fileSize) throw new Error(`${f.path}: embedded bytes do not match the manifest hashes`);
      if (!placed.has(f.member)) placed.set(f.member, []);
      placed.get(f.member)!.push({ target: targetPath(f.path, base, level), data: b, sha256: sha("sha256", b), role: f.role });
    }
    for (const f of pack.files) {
      if (!args.deps.fetch) throw new Error("no artifact fetcher for third-party files");
      const b = await args.deps.fetch(f);
      if (sha("sha1", b) !== f.hashes.sha1 || sha("sha512", b) !== f.hashes.sha512 || b.length !== f.fileSize) throw new Error(`${f.path}: downloaded bytes do not match the manifest hashes`);
      if (!placed.has(f.member)) placed.set(f.member, []);
      placed.get(f.member)!.push({ target: targetPath(f.path, base, level), data: b, sha256: sha("sha256", b), role: f.role });
    }
  } catch (e) { return fail("fetch", errMsg(e)); }
  const loaderEntries: { id: string; url: string; sha1: string; required: boolean; role: string }[] = [];
  try {
    for (const rp of pack.resourcePacks.packs) {
      const b = args.archive.get(rp.embedded);
      if (!b || sha("sha1", b) !== rp.sha1 || sha("sha256", b) !== rp.sha256) throw new Error(`resource pack ${rp.role} is missing or does not match its hashes`);
      if (!args.deps.publish) throw new Error("no pack publisher configured (resource packs need hosting)");
      const { url } = await args.deps.publish(b, rp.sha1);
      if (!/^https:\/\//.test(url)) throw new Error("pack URL must be https");
      loaderEntries.push({ id: rp.id, url, sha1: rp.sha1, required: rp.required, role: rp.role });
    }
  } catch (e) { return fail("fetch", errMsg(e)); }

  // 3. preflight: previous unit record, ownership, idempotency
  const prev = await readRecord(fs, rec);
  const newTargets = [...placed.values()].flat();
  const owned = new Set(prev?.files.map((f) => f.path) ?? []);
  for (const t of newTargets) {
    if (owned.has(t.target)) continue;
    const cur = await fs.readFile(t.target).catch(() => null);
    const st = await fs.stat(t.target);
    if (st?.type === "dir") return fail("preflight", `${t.target} is a folder`);
    if (cur && sha("sha256", cur) !== t.sha256) return fail("preflight", `${t.target} already exists and does not belong to this Mod Pack; nothing was changed`);
  }
  const loaderPath = `${base}/${LOADER_CONFIG_PATH}`;
  let currentLoader: LoaderConfig | null = null;
  if (loaderEntries.length || prev?.loaderIds.length) {
    const raw = await fs.readFile(loaderPath, 1024 * 1024);
    if (raw) {
      let j: unknown;
      try { j = JSON.parse(raw.toString("utf8")); } catch { return fail("preflight", "the server's packs.json is not valid JSON; nothing was changed"); }
      const lv = validateLoaderConfig(j);
      if (!lv.ok) return fail("preflight", `the server's packs.json is invalid (${lv.errors[0].message}); nothing was changed`);
      currentLoader = lv.config;
    }
  }
  const nextLoader = loaderEntries.length || prev?.loaderIds.length ? loaderWith(currentLoader, pack.packId, loaderEntries) : null;
  if (nextLoader) { const lv = validateLoaderConfig(nextLoader, { requireHttps: true }); if (!lv.ok) return fail("preflight", lv.errors.map((e) => e.message).join("; ")); }
  const record: UnitRecord = { schema: 1, packId: pack.packId, versionId: pack.versionId, manifestSha256, files: newTargets.map((t) => ({ path: t.target, sha256: t.sha256, member: [...placed.entries()].find(([, fs2]) => fs2.includes(t))![0] })).sort((a, b) => (a.path < b.path ? -1 : 1)), loaderIds: loaderEntries.map((e) => e.id), installedAt: now.toISOString() };
  if (prev && prev.manifestSha256 === manifestSha256) {
    let intact = true;
    for (const f of prev.files) { const b = await fs.readFile(f.path).catch(() => null); if (!b || sha("sha256", b) !== f.sha256) { intact = false; break; } }
    const loaderOk = !nextLoader || (await fs.readFile(loaderPath).catch(() => null))?.toString("utf8") === serializeLoaderConfig(nextLoader);
    if (intact && loaderOk) return { ok: true, action: "unchanged", record: prev, changed: [], restartRequired: false };
  }

  // 4. snapshot
  const removedTargets = (prev?.files ?? []).filter((f) => !newTargets.some((t) => t.target === f.path));
  const touch = [...newTargets.map((t) => t.target), ...removedTargets.map((f) => f.path), rec, ...(nextLoader ? [loaderPath] : []), ...placer.statePaths];
  const backupDir = `${args.deps.backupDir ?? DEFAULT_BACKUP_DIR}/${stamp(now)}-${pack.packId}`;
  let snaps: Snap[];
  try { snaps = await snapshot(fs, touch, backupDir); } catch (e) { await fs.remove(backupDir).catch(() => {}); return fail("snapshot", errMsg(e)); }

  let step: UnitStep = "remove";
  const changed: string[] = [];
  try {
    // 5. remove members (or files) the new version no longer has
    const byMember = new Map<string, string[]>();
    for (const f of removedTargets) { if (!byMember.has(f.member)) byMember.set(f.member, []); byMember.get(f.member)!.push(f.path); }
    for (const [memberId, targets] of [...byMember.entries()].sort()) { await placer.remove({ memberId, targets }); changed.push(`removed ${memberId}`); }
    // 6. place members in manifest order
    step = "place";
    const prevSha = new Map((prev?.files ?? []).map((f) => [f.path, f.sha256]));
    for (const m of pack.members) {
      const files = placed.get(m.id);
      if (!files?.length) continue;
      const todo = files.filter((f) => prevSha.get(f.target) !== f.sha256 || true);
      await placer.place({ member: m, files: todo });
      changed.push(`${prev?.files.some((f) => f.member === m.id) ? "updated" : "installed"} ${m.id} ${m.version}`);
    }
    // 7. Pack Loader entries
    step = "packloader";
    if (nextLoader) { await fs.mkdirp(loaderPath.slice(0, loaderPath.lastIndexOf("/"))); await writeStaged(fs, loaderPath, Buffer.from(serializeLoaderConfig(nextLoader))); }
    // 8. unit record
    step = "record";
    await fs.mkdirp(recordPath);
    await writeStaged(fs, rec, Buffer.from(JSON.stringify(record, null, 2) + "\n"));
    // 9. verify what is on disk now
    step = "verify";
    for (const t of newTargets) { const b = await fs.readFile(t.target); if (!b || sha("sha256", b) !== t.sha256) throw new Error(`${t.target} does not verify after install`); }
    for (const f of removedTargets) if (await fs.stat(f.path)) throw new Error(`${f.path} is still present after removal`);
    if (nextLoader && (await fs.readFile(loaderPath))?.toString("utf8") !== serializeLoaderConfig(nextLoader)) throw new Error("packs.json does not verify after install");
  } catch (e) {
    const rb = await restore(fs, snaps);
    if (rb.ok) await fs.remove(backupDir).catch(() => {});
    return fail(step, `${errMsg(e)}; ${rb.ok ? "the change was rolled back and the previous state verified" : "ROLLBACK INCOMPLETE: the backup is kept at " + backupDir}`, rb);
  }
  await fs.remove(backupDir).catch(() => {});
  return { ok: true, action: prev ? "updated" : "installed", record, changed, restartRequired: newTargets.some((t) => t.role === "plugin") || removedTargets.length > 0 };
}

export async function uninstallModPackUnit(args: { packId: string; base?: string; deps: UnitDeps }): Promise<UnitResult> {
  const { fs } = args.deps;
  const base = (args.base ?? "/opt/mc").replace(/\/$/, "");
  const placer = args.deps.placer ?? fsPlacer(fs);
  const now = (args.deps.now ?? (() => new Date()))();
  const rec = `${args.deps.recordDir ?? DEFAULT_RECORD_DIR}/${args.packId}.json`;
  const prev = await readRecord(fs, rec);
  if (!prev) return { ok: true, action: "unchanged", record: null, changed: [], restartRequired: false };
  const loaderPath = `${base}/${LOADER_CONFIG_PATH}`;
  let nextLoader: LoaderConfig | null = null;
  if (prev.loaderIds.length) {
    const raw = await fs.readFile(loaderPath, 1024 * 1024);
    if (raw) {
      let j: unknown;
      try { j = JSON.parse(raw.toString("utf8")); } catch { return { ok: false, step: "preflight", error: "the server's packs.json is not valid JSON; nothing was changed", rollback: NO_ROLLBACK }; }
      const lv = validateLoaderConfig(j);
      if (!lv.ok) return { ok: false, step: "preflight", error: "the server's packs.json is invalid; nothing was changed", rollback: NO_ROLLBACK };
      nextLoader = loaderWith(lv.config, args.packId, []);
    }
  }
  const backupDir = `${args.deps.backupDir ?? DEFAULT_BACKUP_DIR}/${stamp(now)}-${args.packId}-uninstall`;
  let snaps: Snap[];
  try { snaps = await snapshot(fs, [...prev.files.map((f) => f.path), rec, ...(nextLoader ? [loaderPath] : []), ...placer.statePaths], backupDir); }
  catch (e) { await fs.remove(backupDir).catch(() => {}); return { ok: false, step: "snapshot", error: errMsg(e), rollback: NO_ROLLBACK }; }
  let step: UnitStep = "remove";
  try {
    const byMember = new Map<string, string[]>();
    for (const f of prev.files) { if (!byMember.has(f.member)) byMember.set(f.member, []); byMember.get(f.member)!.push(f.path); }
    for (const [memberId, targets] of [...byMember.entries()].sort()) await placer.remove({ memberId, targets });
    step = "packloader";
    if (nextLoader) await writeStaged(fs, loaderPath, Buffer.from(serializeLoaderConfig(nextLoader)));
    step = "record";
    await fs.remove(rec);
    step = "verify";
    for (const f of prev.files) if (await fs.stat(f.path)) throw new Error(`${f.path} is still present`);
  } catch (e) {
    const rb = await restore(fs, snaps);
    if (rb.ok) await fs.remove(backupDir).catch(() => {});
    return { ok: false, step, error: `${errMsg(e)}; ${rb.ok ? "rolled back and verified" : "ROLLBACK INCOMPLETE: backup kept at " + backupDir}`, rollback: rb };
  }
  await fs.remove(backupDir).catch(() => {});
  return { ok: true, action: "uninstalled", record: null, changed: prev.files.map((f) => `removed ${f.path}`), restartRequired: true };
}

