// Writes the portable ModSpec contract (JSON Schema) next to its Zod source.
// Run after changing lib/cyrus/engine-core/spec.ts:  npx tsx scripts/cyrus-modspec-schema.ts
// test/cyrus-engine-core.test.ts fails while the committed file is out of date.
import { writeFileSync } from "node:fs";
import path from "node:path";
import { modSpecJsonSchema } from "../lib/cyrus/engine-core/spec";

const out = path.join(import.meta.dirname, "..", "lib/cyrus/engine-core/modspec.v1.schema.json");
writeFileSync(out, JSON.stringify(modSpecJsonSchema(), null, 2) + "\n");
console.log(`wrote ${out}`);

