// Writes the portable Mod Pack manifest contract (JSON Schema for nxpack.json) next to its Zod source.
// Run after changing lib/cyrus/modpack/manifest.ts:  npx tsx scripts/cyrus-nxpack-schema.ts
// test/cyrus-modpack.test.ts fails while the committed file is out of date.
