// Cyrus R2 Mod Packs: manifest schema + policy, the pure builder (merge, refusals, versions/changelog, determinism),
// install/update/uninstall as ONE unit with fault injection at every mutating step (rollback restores the exact
// previous bytes), the Mods-engine placer on a local fake guest, and the dynamic plan/evidence merge. Pure/temp dirs.
//   tsx --test test/cyrus-modpack.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { buildModPack, type BuildInput, type BuildOk, type MemberInput } from "../lib/cyrus/modpack/builder";
import { nxPackJsonSchema, validateNxPack, SERVER_JAR_NAME_RE, type NxPack } from "../lib/cyrus/modpack/manifest";
import { installModPackUnit, uninstallModPackUnit, type UnitFs, type UnitDeps } from "../lib/cyrus/modpack/install";
import { engineMemberPlacer, MODPACK_REAL_FLAG } from "../lib/cyrus/modpack/engine-placer";
import { planDynamicChecks, mergeDynamic, type DynamicMember, type FlightOutcome } from "../lib/cyrus/modpack/dynamic";
import { readDescriptor } from "../lib/cyrus/inventory/descriptor";
import { indexZip, readEntry } from "../lib/cyrus/inventory/zipread";
import { canonical } from "../lib/cyrus/conflicts/merge";
import { LocalGuestFs, seedSandboxGuest } from "../lib/mods/guest-fs";
import { STATE_PATH } from "../lib/mods/engine";
import type { TestFlightReport, TestFlightSummary } from "../lib/cyrus/testflight/types";
import { dpZip, goodMod, jarOf, rpZip, shopPlugin, type ModFx } from "./_cyrus-modfixture";

const h = (alg: string, b: Buffer) => createHash(alg).update(b).digest("hex");
const A = "nx_aaaa1111", B = "nx_bbbb2222";
const PACK = "mp_testpack0001";

function cyrusMembers(m: ModFx, idBase: string, version = "1.0.0"): MemberInput[] {
  const project = { projectId: `cp_${idBase}`, revisionId: `rev_${idBase}_${version}`, namespace: m.ns! };
  const out: MemberInput[] = [{ id: `${idBase}`, kind: "plugin", origin: "cyrus", label: m.name, version, project, artifact: { name: `${m.name}.jar`, bytes: jarOf(m) } }];
  if (m.dp) out.push({ id: `${idBase}-dp`, kind: "datapack", origin: "cyrus", label: `${m.name} data`, version, project, artifact: { name: `${m.tag}-data.zip`, bytes: dpZip(m) } });
  if (m.rp) out.push({ id: `${idBase}-rp`, kind: "resourcepack", origin: "cyrus", label: `${m.name} pack`, version, project, artifact: { name: `${m.tag}-rp.zip`, bytes: rpZip(m) } });
  return out;
}
function shopMember(): MemberInput {
  const bytes = jarOf(shopPlugin());
  return { id: "shop", kind: "plugin", origin: "thirdparty", label: "Shop", version: "3.1.0", artifact: { name: "Shop.jar", bytes }, ref: { name: "Shop.jar", url: "https://cdn.modrinth.com/data/shop/Shop-3.1.0.jar", sha1: h("sha1", bytes), sha512: h("sha512", bytes), size: bytes.length, provider: "modrinth" } };
}
const baseInput = (members: MemberInput[], over: Partial<BuildInput> = {}): BuildInput => ({ packId: PACK, name: "Test Pack", mcVersion: "1.21.11", members, ...over });
async function okBuild(input: BuildInput): Promise<BuildOk> { const r = await buildModPack(input); assert.ok(r.ok, JSON.stringify(!r.ok && r.errors)); return r as BuildOk; }

describe("nxpack.json schema + policy", () => {
  it("the committed JSON Schema matches the Zod source", () => {
    const file = JSON.parse(readFileSync(path.join(__dirname, "../lib/cyrus/modpack/nxpack.v1.schema.json"), "utf8"));
    assert.deepEqual(file, nxPackJsonSchema(), "regenerate with: npx tsx scripts/cyrus-nxpack-schema.ts");
  });
  it("server jar names are recognised without blocking ordinary plugin names", () => {
    for (const p of ["plugins/paper-1.21.11-132.jar", "plugins/purpur-1.21.4.jar", "plugins/minecraft_server.1.21.jar", "plugins/spigot.jar", "plugins/paperclip.jar"]) assert.ok(SERVER_JAR_NAME_RE.test(p), p);
    for (const p of ["plugins/PaperTweaks.jar", "plugins/Shop.jar", "plugins/ServerUtils.jar", "plugins/Paper-Hooks.jar"]) assert.ok(!SERVER_JAR_NAME_RE.test(p), p);
  });
  it("refuses embedded third-party jars, http downloads, server jars (name or registry hash) and blocking conflicts", async () => {
    const b = await okBuild(baseInput([...cyrusMembers(goodMod(A, "alpha"), "alpha"), shopMember()]));
    const bad = (mut: (p: NxPack) => void) => { const p = JSON.parse(JSON.stringify(b.manifest)) as NxPack; mut(p); const v = validateNxPack(p); return v.ok ? [] : v.errors.map((e) => e.code); };
    assert.deepEqual(bad(() => {}), []);
    assert.ok(bad((p) => { const f = p.files[0]; p.embedded.push({ path: f.path, member: f.member, role: f.role, hashes: { ...f.hashes, sha256: "a".repeat(64) }, fileSize: f.fileSize, env: f.env, embedded: `overrides/${f.path}` }); p.files = []; }).includes("embed_thirdparty"));
    assert.ok(bad((p) => { p.files[0].downloads = ["http://x.invalid/a.jar"]; }).includes("https_only"));
    assert.ok(bad((p) => { p.files[0].path = "plugins/paper-1.21.11-132.jar"; }).includes("server_jar"));
    const pin = "4c0e5ec2d7fd12dc4a4bb9fac4d1d4ac6a2a3da6c2b13b2b5c1d3ad7e3c9a0f1";
    const { VERSIONS } = await import("../lib/cyrus/versions/registry");
    const real = VERSIONS.find((v) => v.paperServerSha256)?.paperServerSha256 ?? pin;
    assert.ok(bad((p) => { p.files[0].hashes.sha256 = real; }).includes("server_jar"));
    assert.ok(bad((p) => { p.conflicts.counts.blocking = 1; }).includes("blocking_conflicts"));
    assert.ok(bad((p) => { p.members.push({ ...p.members[0] }); }).includes("duplicate_member"));
  });
});

describe("Mod Pack builder (pure)", () => {
  const members = () => [...cyrusMembers(goodMod(A, "alpha"), "alpha"), ...cyrusMembers(goodMod(B, "beta"), "beta"), shopMember()];
  it("composes one merged resource pack, embeds only Cyrus artifacts, references third-party jars", async () => {
    const b = await okBuild(baseInput(members()));
    const m = b.manifest;
    assert.equal(m.resourcePacks.mode, "merged");
    assert.equal(m.resourcePacks.packs.length, 1);
    assert.deepEqual(m.resourcePacks.packs[0].members, ["alpha-rp", "beta-rp"]);
    assert.deepEqual(m.files.map((f) => [f.path, f.downloads[0]]), [["plugins/Shop.jar", "https://cdn.modrinth.com/data/shop/Shop-3.1.0.jar"]]);
    assert.deepEqual(m.embedded.map((f) => f.path).sort(), ["datapacks/alpha-data.zip", "datapacks/beta-data.zip", "plugins/NxAlpha.jar", "plugins/NxBeta.jar"]);
    assert.ok(!b.archive.some((f) => f.path.includes("Shop")), "third-party bytes never in the archive");
    assert.deepEqual(m.datapackOrder, ["alpha-dp", "beta-dp"]);
    assert.deepEqual(m.compatibility, [{ mcVersion: "1.21.11", static: "clean", dynamic: "not_run", evidence: ["no Test Flight evidence supplied: not run (not a pass)"] }]);
    assert.deepEqual(m.changelog[0].changes.map((c) => c.type), ["added", "added", "added", "added", "added", "added", "added"]);
    const z = indexZip(b.resourcePackZips[0].zip);
    assert.ok(z.ok);
    if (!z.ok) return;
    const names = z.zip.entries.map((e) => e.name);
    for (const ns of [A, B]) assert.ok(names.includes(`assets/${ns}/items/gem.json`));
    const mcmeta = JSON.parse(readEntry(z.zip, z.zip.entries.find((e) => e.name === "pack.mcmeta")!).ok ? (readEntry(z.zip, z.zip.entries.find((e) => e.name === "pack.mcmeta")!) as { data: Buffer }).data.toString() : "{}");
    assert.equal(mcmeta.pack.pack_format, 75);
  });
  it("is deterministic (same inputs -> same archive bytes)", async () => {
    const a = await okBuild(baseInput(members())), b = await okBuild(baseInput(members()));
    assert.equal(h("sha256", a.archiveZip), h("sha256", b.archiveZip));
  });
  it("refuses blocking conflicts, server jars, bad hashes; asks for decisions only when told to", async () => {
    const a = goodMod(A, "alpha"), b2 = goodMod(B, "beta"); b2.name = "NxAlpha";
    const r1 = await buildModPack(baseInput([...cyrusMembers(a, "alpha"), ...cyrusMembers(b2, "beta")]));
    assert.ok(!r1.ok && r1.code === "blocking_conflicts" && r1.errors[0].startsWith("plugin.duplicate_name"));
    const sj = goodMod(B, "beta"); sj.serverJar = true;
    const r2 = await buildModPack(baseInput([...cyrusMembers(sj, "beta")]));
    assert.ok(!r2.ok && r2.code === "blocking_conflicts" && r2.errors.some((e) => e.startsWith("policy.server_jar")));
    const named = cyrusMembers(goodMod(B, "beta"), "beta"); named[0].artifact!.name = "paper-1.21.11-132.jar";
    const r3 = await buildModPack(baseInput(named));
    assert.ok(!r3.ok && r3.code === "invalid_input");
    const shop = shopMember(); shop.ref!.sha1 = "0".repeat(40);
    const r4 = await buildModPack(baseInput([shop]));
    assert.ok(!r4.ok && r4.code === "hash_mismatch");
    const c1 = goodMod(A, "alpha"), c2 = goodMod(B, "beta"); c1.chatRenderer = c2.chatRenderer = true;
    const ms = [...cyrusMembers(c1, "alpha"), ...cyrusMembers(c2, "beta")];
    const loose = await buildModPack(baseInput(ms));
    assert.ok(loose.ok);
    const strict = await buildModPack(baseInput(ms, { requireAcknowledged: true }));
    assert.ok(!strict.ok && strict.code === "needs_decision");
    const ids = strict.report!.findings.filter((f) => f.resolution.kind === "user_decision").map((f) => f.id);
    const acked = await okBuild(baseInput(ms, { requireAcknowledged: true, acknowledge: ids }));
    assert.ok(acked.manifest.conflicts.open.filter((o) => ids.includes(o.findingId)).every((o) => o.acknowledged));
  });
  it("falls back to an ordered pack list when shaders cannot merge", async () => {
    const a = goodMod(A, "alpha"), b = goodMod(B, "beta");
    a.rp!["assets/minecraft/shaders/core/x.fsh"] = "a"; b.rp!["assets/minecraft/shaders/core/x.fsh"] = "b";
    const r = await okBuild(baseInput([...cyrusMembers(a, "alpha"), ...cyrusMembers(b, "beta")]));
    assert.equal(r.manifest.resourcePacks.mode, "stacked");
    assert.deepEqual(r.manifest.resourcePacks.packs.map((p) => p.members), [["alpha-rp"], ["beta-rp"]]);
    assert.ok(r.manifest.conflicts.open.some((o) => o.class === "rp.shader"));
  });
  it("versions + changelog: updated, removed, reordered; unchanged rebuild refused; preview packs refused", async () => {
    const v1 = await okBuild(baseInput(members()));
    const alpha2 = goodMod(A, "alpha"); alpha2.commands[0].aliases = ["alphag", "ag"];
    const v2 = await okBuild(baseInput([...cyrusMembers(goodMod(B, "beta"), "beta"), ...cyrusMembers(alpha2, "alpha", "1.1.0").slice(0, 1), ...cyrusMembers(goodMod(A, "alpha"), "alpha").slice(1)], { previous: v1.manifest }));
    assert.equal(v2.manifest.versionId, "1.0.1");
    const types = v2.manifest.changelog[0].changes.map((c) => `${c.type}:${c.member}`).sort();
    assert.deepEqual(types, ["removed:shop", "reordered:alpha", "reordered:alpha-dp", "reordered:alpha-rp", "reordered:beta", "reordered:beta-dp", "reordered:beta-rp", "updated:alpha"]);
    assert.equal(v2.manifest.changelog[1].versionId, "1.0.0");
    const same = await buildModPack(baseInput(members(), { previous: v1.manifest }));
    assert.ok(!same.ok && /nothing changed/.test(same.errors[0]));
    const older = await buildModPack(baseInput(members(), { previous: v1.manifest, versionId: "0.9.0" }));
    assert.ok(!older.ok);
    const pre = await buildModPack(baseInput(members(), { mcVersion: "26.2" }));
    assert.ok(!pre.ok && /preview/.test(pre.errors[0]));
    assert.ok((await buildModPack(baseInput(members(), { mcVersion: "26.2", allowPreview: true }))).ok);
  });
  it("checks members against the target server's inventory", async () => {
    const { MemFs, fakeServer } = await import("./_cyrus-fakeserver");
    const { scanServer } = await import("../lib/cyrus/inventory/scan");
    const inv = await scanServer(new MemFs(fakeServer()));
    const a = goodMod(A, "alpha"); a.commands[0].name = "rich";
    const r = await okBuild(baseInput(cyrusMembers(a, "alpha"), { inventory: inv }));
    assert.ok(r.manifest.conflicts.open.some((o) => o.class === "command.label_collision" && o.subject === "/rich"));
    assert.ok(r.manifest.conflicts.open.some((o) => o.class === "rp.existing_owner"));
  });
});

// ---- writable in-memory fs + fault injection -------------------------------------------------------------------
class MemW implements UnitFs {
  files = new Map<string, Buffer>();
  async stat(p: string) { const f = this.files.get(p); if (f) return { type: "file" as const, size: f.length }; return [...this.files.keys()].some((k) => k.startsWith(p + "/")) ? { type: "dir" as const, size: 0 } : null; }
  async readFile(p: string, max = Infinity) { const f = this.files.get(p); return f && f.length <= max ? Buffer.from(f) : null; }
  async writeFile(p: string, d: Buffer) { this.files.set(p, Buffer.from(d)); }
  async mkdirp() {}
  async rename(a: string, b: string) { const f = this.files.get(a); if (!f) throw new Error(`rename: ${a} missing`); this.files.set(b, f); this.files.delete(a); }
  async remove(p: string) { for (const k of [...this.files.keys()]) if (k === p || k.startsWith(p + "/")) this.files.delete(k); }
  async list(d: string) { return [...new Set([...this.files.keys()].filter((k) => k.startsWith(d + "/")).map((k) => k.slice(d.length + 1).split("/")[0]))]; }
  async copy(a: string, b: string) { const f = this.files.get(a); if (!f) throw new Error(`copy: ${a} missing`); this.files.set(b, Buffer.from(f)); }
  tree(exclude = "/root/.nxeon-cyrus/modpack-backups") { return canonical([...this.files.entries()].filter(([k]) => !k.startsWith(exclude)).map(([k, v]) => [k, h("sha256", v)]).sort()); }
}
class FaultFs implements UnitFs {
  ops = 0;
  constructor(readonly inner: UnitFs, public failAt = 0, public persistent = false, public only?: string) {}
  private tick(op: string) { this.ops++; if (this.failAt && (this.persistent ? this.ops >= this.failAt && (!this.only || op === this.only) : this.ops === this.failAt)) throw new Error(`injected fault at op ${this.ops} (${op})`); }
  stat(p: string) { return this.inner.stat(p); }
  readFile(p: string, m?: number) { return this.inner.readFile(p, m); }
  list(d: string) { return this.inner.list(d); }
  async writeFile(p: string, d: Buffer) { this.tick("writeFile"); return this.inner.writeFile(p, d); }
  async mkdirp(p: string) { this.tick("mkdirp"); return this.inner.mkdirp(p); }
  async rename(a: string, b: string) { this.tick("rename"); return this.inner.rename(a, b); }
  async remove(p: string) { this.tick("remove"); return this.inner.remove(p); }
