      const b = await okBuild(baseInput([...cyrusMembers(goodMod(A, "alpha"), "alpha"), shopMember()]));
      const off = engineMemberPlacer({ fs: g, server: srv, packId: PACK, env: {} });
      const r0 = await installModPackUnit({ manifest: b.manifest, archive: archiveOf(b), deps: { ...deps(g), placer: off } });
      assert.ok(!r0.ok && r0.step === "validate" && new RegExp(MODPACK_REAL_FLAG).test(r0.error));
