// Cyrus R2 Mod Packs: manifest schema + policy, the pure builder (merge, refusals, versions/changelog, determinism),
// install/update/uninstall as ONE unit with fault injection at every mutating step (rollback restores the exact
// previous bytes), the Mods-engine placer on a local fake guest, and the dynamic plan/evidence merge. Pure/temp dirs.
//   tsx --test test/cyrus-modpack.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
