const h = (alg: string, b: Buffer) => createHash(alg).update(b).digest("hex");
const A = "nx_aaaa1111", B = "nx_bbbb2222";
const PACK = "mp_testpack0001";

function cyrusMembers(m: ModFx, idBase: string, version = "1.0.0"): MemberInput[] {
  const project = { projectId: `cp_${idBase}`, revisionId: `rev_${idBase}_${version}`, namespace: m.ns! };
  const out: MemberInput[] = [{ id: `${idBase}`, kind: "plugin", origin: "cyrus", label: m.name, version, project, artifact: { name: `${m.name}.jar`, bytes: jarOf(m) } }];
  if (m.dp) out.push({ id: `${idBase}-dp`, kind: "datapack", origin: "cyrus", label: `${m.name} data`, version, project, artifact: { name: `${m.tag}-data.zip`, bytes: dpZip(m) } });
  if (m.rp) out.push({ id: `${idBase}-rp`, kind: "resourcepack", origin: "cyrus", label: `${m.name} pack`, version, project, artifact: { name: `${m.tag}-rp.zip`, bytes: rpZip(m) } });
  return out;
}
function shopMember(): MemberInput {
  const bytes = jarOf(shopPlugin());
  return { id: "shop", kind: "plugin", origin: "thirdparty", label: "Shop", version: "3.1.0", artifact: { name: "Shop.jar", bytes }, ref: { name: "Shop.jar", url: "https://cdn.modrinth.com/data/shop/Shop-3.1.0.jar", sha1: h("sha1", bytes), sha512: h("sha512", bytes), size: bytes.length, provider: "modrinth" } };
