describe("nxpack.json schema + policy", () => {
  it("the committed JSON Schema matches the Zod source", () => {
    const file = JSON.parse(readFileSync(path.join(__dirname, "../lib/cyrus/modpack/nxpack.v1.schema.json"), "utf8"));
    assert.deepEqual(file, nxPackJsonSchema(), "regenerate with: npx tsx scripts/cyrus-nxpack-schema.ts");
  });
  it("server jar names are recognised without blocking ordinary plugin names", () => {
    for (const p of ["plugins/paper-1.21.11-132.jar", "plugins/purpur-1.21.4.jar", "plugins/minecraft_server.1.21.jar", "plugins/spigot.jar", "plugins/paperclip.jar"]) assert.ok(SERVER_JAR_NAME_RE.test(p), p);
    for (const p of ["plugins/PaperTweaks.jar", "plugins/Shop.jar", "plugins/ServerUtils.jar", "plugins/Paper-Hooks.jar"]) assert.ok(!SERVER_JAR_NAME_RE.test(p), p);
  });
  it("refuses embedded third-party jars, http downloads, server jars (name or registry hash) and blocking conflicts", async () => {
    const b = await okBuild(baseInput([...cyrusMembers(goodMod(A, "alpha"), "alpha"), shopMember()]));
    const bad = (mut: (p: NxPack) => void) => { const p = JSON.parse(JSON.stringify(b.manifest)) as NxPack; mut(p); const v = validateNxPack(p); return v.ok ? [] : v.errors.map((e) => e.code); };
    assert.deepEqual(bad(() => {}), []);
    assert.ok(bad((p) => { const f = p.files[0]; p.embedded.push({ path: f.path, member: f.member, role: f.role, hashes: { ...f.hashes, sha256: "a".repeat(64) }, fileSize: f.fileSize, env: f.env, embedded: `overrides/${f.path}` }); p.files = []; }).includes("embed_thirdparty"));
    assert.ok(bad((p) => { p.files[0].downloads = ["http://x.invalid/a.jar"]; }).includes("https_only"));
    assert.ok(bad((p) => { p.files[0].path = "plugins/paper-1.21.11-132.jar"; }).includes("server_jar"));
    const pin = "4c0e5ec2d7fd12dc4a4bb9fac4d1d4ac6a2a3da6c2b13b2b5c1d3ad7e3c9a0f1";
    const { VERSIONS } = await import("../lib/cyrus/versions/registry");
