    assert.ok(bad((p) => { p.files[0].hashes.sha256 = real; }).includes("server_jar"));
    assert.ok(bad((p) => { p.conflicts.counts.blocking = 1; }).includes("blocking_conflicts"));
    assert.ok(bad((p) => { p.members.push({ ...p.members[0] }); }).includes("duplicate_member"));
  });
});

describe("Mod Pack builder (pure)", () => {
  const members = () => [...cyrusMembers(goodMod(A, "alpha"), "alpha"), ...cyrusMembers(goodMod(B, "beta"), "beta"), shopMember()];
  it("composes one merged resource pack, embeds only Cyrus artifacts, references third-party jars", async () => {
    const b = await okBuild(baseInput(members()));
