// ---- writable in-memory fs + fault injection -------------------------------------------------------------------
class MemW implements UnitFs {
  files = new Map<string, Buffer>();
  async stat(p: string) { const f = this.files.get(p); if (f) return { type: "file" as const, size: f.length }; return [...this.files.keys()].some((k) => k.startsWith(p + "/")) ? { type: "dir" as const, size: 0 } : null; }
  async readFile(p: string, max = Infinity) { const f = this.files.get(p); return f && f.length <= max ? Buffer.from(f) : null; }
  async writeFile(p: string, d: Buffer) { this.files.set(p, Buffer.from(d)); }
  async mkdirp() {}
  async rename(a: string, b: string) { const f = this.files.get(a); if (!f) throw new Error(`rename: ${a} missing`); this.files.set(b, f); this.files.delete(a); }
  async remove(p: string) { for (const k of [...this.files.keys()]) if (k === p || k.startsWith(p + "/")) this.files.delete(k); }
  async list(d: string) { return [...new Set([...this.files.keys()].filter((k) => k.startsWith(d + "/")).map((k) => k.slice(d.length + 1).split("/")[0]))]; }
  async copy(a: string, b: string) { const f = this.files.get(a); if (!f) throw new Error(`copy: ${a} missing`); this.files.set(b, Buffer.from(f)); }
  tree(exclude = "/root/.nxeon-cyrus/modpack-backups") { return canonical([...this.files.entries()].filter(([k]) => !k.startsWith(exclude)).map(([k, v]) => [k, h("sha256", v)]).sort()); }
}
class FaultFs implements UnitFs {
  ops = 0;
  constructor(readonly inner: UnitFs, public failAt = 0, public persistent = false, public only?: string) {}
  private tick(op: string) { this.ops++; if (this.failAt && (this.persistent ? this.ops >= this.failAt && (!this.only || op === this.only) : this.ops === this.failAt)) throw new Error(`injected fault at op ${this.ops} (${op})`); }
  stat(p: string) { return this.inner.stat(p); }
  readFile(p: string, m?: number) { return this.inner.readFile(p, m); }
  list(d: string) { return this.inner.list(d); }
  async writeFile(p: string, d: Buffer) { this.tick("writeFile"); return this.inner.writeFile(p, d); }
  async mkdirp(p: string) { this.tick("mkdirp"); return this.inner.mkdirp(p); }
  async rename(a: string, b: string) { this.tick("rename"); return this.inner.rename(a, b); }
  async remove(p: string) { this.tick("remove"); return this.inner.remove(p); }
  async copy(a: string, b: string) { this.tick("copy"); return this.inner.copy(a, b); }
}

const PUBLISH = async (_z: Buffer, sha1: string) => ({ url: `https://packs.example.invalid/p/${sha1}.zip` });
const OTHER_LOADER = { schema: 1, packs: [{ id: "11111111-2222-5333-8444-555555555555", url: "https://packs.example.invalid/p/" + "b".repeat(40) + ".zip", sha1: "b".repeat(40), prompt: "other", required: false, owner: "nx_other001", role: "main" }] };

function server(): MemW {
  const fs = new MemW();
  fs.files.set("/opt/mc/server.properties", Buffer.from("level-name=world\n"));
  fs.files.set("/opt/mc/plugins/Unrelated.jar", Buffer.from("someone else's plugin"));
  fs.files.set("/opt/mc/plugins/NxeonPackLoader/packs.json", Buffer.from(JSON.stringify(OTHER_LOADER, null, 2) + "\n"));
