// ---- dynamic plan + evidence merge -----------------------------------------------------------------------------
const descOf = (m: ModFx) => readDescriptor((require("./_cyrus-modfixture") as typeof import("./_cyrus-modfixture")).ymlOf(m), "plugin.yml");
function fakeReport(over: { status?: TestFlightReport["status"]; log?: string[]; rcon?: string[]; enabled?: string[] }): TestFlightReport {
  const status = over.status ?? "completed";
  return {
    schema: 1, runId: "tf-x", status, version: "1.21.11", javaRelease: 21, startedAt: "", finishedAt: "", timings: {}, bootMs: 1000, doneReportedSec: 1, peakRssKb: 1, artifacts: [], engine: null, notes: [], overall: "passed",
    checks: [
      { id: "boot_done", status: "pass", required: true, evidence: ["done"], durationMs: 1 },
      { id: "plugins_enabled", status: "pass", required: true, evidence: over.enabled ?? [], durationMs: 1 },
      { id: "startup_log_clean", status: over.log?.length ? "fail" : "pass", required: true, evidence: ["n startup lines", ...(over.log ?? [])], durationMs: 1 },
      { id: "rcon_checks", status: "pass", required: true, evidence: over.rcon ?? [], durationMs: 1 },
    ],
  };
}
const summ = (ok: boolean, status: TestFlightSummary["overall"] = ok ? "passed" : "failed"): TestFlightSummary => ({ version: "1.21.11", overall: status, success: ok, passed: [], failed: ok ? [] : ["startup_log_clean"], skippedRequired: [], notRunOptional: [], reasons: [], bootMs: 1, peakRssKb: 1, runId: "tf-x" });

describe("dynamic check (plan + honest merge)", () => {
  const a = goodMod(A, "alpha"), b = goodMod(B, "beta");
  b.commands[0].name = "alphagem"; b.perms.push({ name: `${A}.use`, default: "op" });
  const dm = (m: ModFx, id: string, changed: boolean): DynamicMember => ({ member: id, artifact: { remotePath: `/x/${m.name}.jar` }, descriptor: descOf(m), changed });
  it("plans one combined boot + a differential boot only for changed, statically flagged members", async () => {
    const { detectConflicts } = await import("../lib/cyrus/conflicts/engine");
    const { candidateJar } = await import("../lib/cyrus/conflicts/normalize");
    const rep = detectConflicts([candidateJar("A.jar", jarOf(a), { id: "member:alpha", cyrus: { namespace: A } }), candidateJar("B.jar", jarOf(b), { id: "member:beta", cyrus: { namespace: B } })], { mcVersion: "1.21.11" });
    const plan = planDynamicChecks({ mcVersions: ["1.21.11", "26.2"], members: [dm(a, "alpha", false), dm(b, "beta", true)], report: rep });
    assert.deepEqual(plan.map((p) => p.key), ["1.21.11:combined", "1.21.11:without:beta", "26.2:combined", "26.2:without:beta"]);
    assert.ok(plan[0].spec.rcon!.some((c) => c.command === "help alphagem" && c.required === false));
    const clean = detectConflicts([candidateJar("A.jar", jarOf(goodMod(A, "alpha")), { id: "member:alpha" }), candidateJar("C.jar", jarOf(goodMod(B, "beta")), { id: "member:beta" })], {});
    assert.deepEqual(planDynamicChecks({ mcVersions: ["1.21.11"], members: [dm(goodMod(A, "alpha"), "alpha", true), dm(goodMod(B, "beta"), "beta", true)], report: clean }).map((p) => p.role), ["combined"]);
    // merge: the combined boot shows the label owned by alpha and a permission warning; the differential (no beta) is clean
    const members = [dm(a, "alpha", false), dm(b, "beta", true)];
    const p1 = plan.filter((p) => p.mcVersion === "1.21.11");
    const outcomes: FlightOutcome[] = [
      { key: "1.21.11:combined", report: fakeReport({ log: [`L40 [warn-exception] [12:00:01 WARN]: Plugin NxBeta v1.0.0 tried to register permission '${A}.use' but it's already registered`], rcon: ["help-alphagem 'help alphagem': ok (optional) -> --------- Help: /alphagem --------- | Description: NxAlpha alphagem | Usage: /alphagem"] }), summary: summ(false) },
      { key: "1.21.11:without:beta", report: fakeReport({ rcon: ["help-alphagem 'help alphagem': ok (optional) -> Description: NxAlpha alphagem"] }), summary: summ(true) },
    ];
    const d = mergeDynamic(rep, p1, outcomes, members);
    assert.equal(d.versions[0].overall, "failed");
    const byClass = (c: string) => d.findings.find((f) => f.class === c)!;
    assert.equal(byClass("command.label_collision").dynamic, "confirmed");
    assert.equal(byClass("permission.duplicate").dynamic, "confirmed");
    assert.ok(d.dynamicOnly.some((x) => x.kind === "new_error_line" && x.member === "beta"));
    // a differential that came back busy: not a pass
    const busy = mergeDynamic(rep, p1, [{ ...outcomes[0], report: fakeReport({}), summary: summ(true) }, { key: "1.21.11:without:beta", report: fakeReport({ status: "busy" }), summary: summ(false, "busy") }], members);
    assert.equal(busy.versions[0].overall, "incomplete");
    const none = mergeDynamic(rep, p1, [], members);
    assert.deepEqual([none.versions[0].overall, byClass("command.label_collision").dynamic && none.findings[0].dynamic], ["not_run", "not_run"]);
    assert.ok(d.findings.filter((f) => f.class === "item.item_model" || f.class === "event.overlap").every((f) => f.dynamic === "not_observable"));
  });
});

