input.command:
cd /tank/dev-worktrees/cyrus-r2/services/modbuilder/tools/testflight/fixtures && for spec in "pair-a:TfPairA:tfpaira:tfpaira.use:true:NORMAL:read" "pair-b:TfPairB:tfpairb:tfpairb.use:true:NORMAL:read" "clash-a:TfClashA:nxclash:nxclash.use:true:HIGH:mutate" "clash-b:TfClashB:nxclash:nxclash.use:op:HIGH:mutate"; do
IFS=: read dir name cmd perm def prio kind <<< "$spec"
pkg="dev.nxeon.tf.$(echo $name | tr 'A-Z' 'a-z')"
mkdir -p "$dir/src/$(echo $pkg | tr . /)"
cat > "$dir/plugin.yml" <<EOF
name: $name
version: 1.0.0
main: $pkg.Main
api-version: "@API@"
description: Cyrus R2 composition fixture ($kind)
commands:
  $cmd:
    description: $name command
    usage: /$cmd
    permission: $perm
permissions:
  $perm:
    description: use /$cmd
    default: $def
EOF
if [ "$kind" = mutate ]; then body='        event.setJoinMessage("'$name' says welcome");'; else body='        getLogger().fine("join seen: " + event.getEventName());'; fi
cat > "$dir/src/$(echo $pkg | tr . /)/Main.java" <<EOF
package $pkg;

import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.plugin.java.JavaPlugin;

/** Cyrus R2 composition fixture: answers /$cmd with its own name so a boot shows which plugin owns the label. */
public class Main extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        getServer().getPluginManager().registerEvents(this, this);
        getLogger().info("$name enabled");
    }

    @EventHandler(priority = EventPriority.$prio)
    public void onJoin(PlayerJoinEvent event) {
$body
    }

    @Override
    public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {
        sender.sendMessage("$name handled /" + label);
        return true;
    }
}
EOF
done; find pair-a clash-b -type f | xargs ls -la; cat clash-b/plugin.yml

