  const staticFor = (v: string): NxPack["compatibility"][number]["static"] => {
    const row = getVersion(v);
    if (!row) return "blocked";
    const r = v === input.mcVersion ? report : detectConflicts([...entries, ...(inv?.mods ?? [])], { ...(inv?.ctx ?? {}), mcVersion: v, javaRelease: row.javaRelease, modPack: true });
