// REAL Test Flight runs of the Cyrus R2 composition check on node-2 (not part of the unit suite: boots real Paper).
//   tsx test/cyrus-composition-real.ts [clean|clash|all] [--versions 1.21.11,26.2] [--out file.json]
// Per scenario: static conflict report over the fixture jars -> Mod Pack build -> the dynamic plan (one combined boot
// per version + one differential boot per changed, statically flagged member) -> flights strictly one at a time,
// retried with backoff when node-2 says "busy" (another agent's flight; never bypassed) -> mergeDynamic -> rebuild
// with the evidence -> the compatibility matrix. Fixture jars (test/fixtures/cyrus-r2/, built by
// services/modbuilder/tools/testflight/fixtures/build.sh with JDK 21 --release 21 against the 1.21.11 classpath):
// TfPairA + TfPairB (clean pair) and TfClashA + TfClashB (same /nxclash, same nxclash.use with different defaults,
// both set the join message at HIGH).
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import { candidateJar } from "../lib/cyrus/conflicts/normalize";
import { buildModPack, type MemberInput } from "../lib/cyrus/modpack/builder";
import { mergeDynamic, planDynamicChecks, type DynamicMember, type FlightOutcome } from "../lib/cyrus/modpack/dynamic";
import type { RconCheck } from "../lib/cyrus/testflight/types";

const FX = path.join(__dirname, "fixtures/cyrus-r2");
const h = (alg: string, b: Buffer) => createHash(alg).update(b).digest("hex");
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

type Scenario = { name: string; jars: { id: string; file: string; changed: boolean }[]; extraRcon: RconCheck[] };
const SCENARIOS: Scenario[] = [
  { name: "clean", jars: [{ id: "pair-a", file: "TfPairA-1.0.0.jar", changed: false }, { id: "pair-b", file: "TfPairB-1.0.0.jar", changed: true }], extraRcon: [
    { id: "run-tfpaira", command: "tfpaira", expect: ["TfPairA handled /tfpaira"] }, { id: "run-tfpairb", command: "tfpairb", expect: ["TfPairB handled /tfpairb"] },
  ] },
  { name: "clash", jars: [{ id: "clash-a", file: "TfClashA-1.0.0.jar", changed: false }, { id: "clash-b", file: "TfClashB-1.0.0.jar", changed: true }], extraRcon: [
    { id: "run-nxclash", command: "nxclash", required: false },
    { id: "run-tfclasha-prefixed", command: "tfclasha:nxclash", expect: ["TfClashA handled"] },
    { id: "run-tfclashb-prefixed", command: "tfclashb:nxclash", expect: ["TfClashB handled"], required: false },
  ] },
];

async function flyWithBackoff(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec);
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

async function main() {
  const which = process.argv[2] ?? "all";
  const vi = process.argv.indexOf("--versions");
  const versions = vi > 0 ? process.argv[vi + 1].split(",") : ["1.21.11", "26.2"];
  const oi = process.argv.indexOf("--out");
  const out: unknown[] = [];
  for (const sc of SCENARIOS.filter((s) => which === "all" || s.name === which)) {
    const bytes = new Map(sc.jars.map((j) => [j.id, readFileSync(path.join(FX, j.file))]));
    const entries = sc.jars.map((j) => candidateJar(j.file, bytes.get(j.id)!, { id: `member:${j.id}`, changed: j.changed }));
    const members: MemberInput[] = sc.jars.map((j) => {
      const b = bytes.get(j.id)!;
      return { id: j.id, kind: "plugin", origin: "thirdparty", label: entries.find((e) => e.id === `member:${j.id}`)!.label, version: "1.0.0", artifact: { name: j.file, bytes: b }, ref: { name: j.file, url: `https://fixtures.example.invalid/${j.file}`, sha1: h("sha1", b), sha512: h("sha512", b), size: b.length, provider: "url" } };
    });
    const build0 = await buildModPack({ packId: `mp_r2${sc.name.padEnd(9, "0")}`, name: `R2 ${sc.name} pair`, mcVersion: versions[0], members });
    if (!build0.ok) throw new Error(`${sc.name}: static build refused: ${build0.errors.join("; ")}`);
    const staticReport = build0.report;
    console.log(`${sc.name}: static ${JSON.stringify(staticReport.counts)} ${staticReport.findings.map((f) => `${f.severity}:${f.class}:${f.subject}`).join(" | ")}`);
    const dms: DynamicMember[] = sc.jars.map((j) => ({ member: j.id, artifact: { localPath: path.join(FX, j.file) }, descriptor: entries.find((e) => e.id === `member:${j.id}`)!.plugin!.descriptor, changed: j.changed }));
    const plan = planDynamicChecks({ mcVersions: versions, members: dms, report: staticReport, extraRcon: sc.extraRcon });
    const outcomes: FlightOutcome[] = [];
    const flights: unknown[] = [];
    for (const p of plan) {
      try {
        const r = await flyWithBackoff(p.spec, `${sc.name} ${p.key}`);
        outcomes.push({ key: p.key, report: r.report, summary: r.summary });
        console.log(`${sc.name} ${p.key}: ${describeSummary(r.summary)}`);
        flights.push({ key: p.key, role: p.role, without: p.without, status: r.report.status, overall: r.summary.overall, bootMs: r.report.bootMs, peakRssKb: r.report.peakRssKb, runId: r.report.runId, paper: r.report.engine?.paper, jdk: r.report.engine?.jdk?.version, checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence.slice(0, 14) })) });
      } catch (e) {
        outcomes.push({ key: p.key, report: null, summary: null, error: (e as Error).message });
        flights.push({ key: p.key, error: (e as Error).message });
        console.log(`${sc.name} ${p.key}: ERROR ${(e as Error).message}`);
      }
    }
    const dynamic = mergeDynamic(staticReport, plan, outcomes, dms);
    const build1 = await buildModPack({ packId: `mp_r2${sc.name.padEnd(9, "0")}`, name: `R2 ${sc.name} pair`, mcVersion: versions[0], members, dynamic });
    out.push({
      scenario: sc.name, versions, static: { counts: staticReport.counts, findings: staticReport.findings.map((f) => ({ id: f.id, class: f.class, severity: f.severity, subject: f.subject, resolution: f.resolution.kind, items: f.items.map((i) => i.evidence) })) },
      plan: plan.map((p) => ({ key: p.key, role: p.role, without: p.without, members: p.members })), flights,
      dynamic: { versions: dynamic.versions, findings: dynamic.findings, dynamicOnly: dynamic.dynamicOnly },
      compatibility: build1.ok ? build1.manifest.compatibility : { error: build1.errors },
    });
  }
  const text = JSON.stringify(out, null, 1);
  if (oi > 0) writeFileSync(process.argv[oi + 1], text);
  else console.log(text);
}
main().catch((e) => { console.error(e); process.exit(1); });

