input.command:
cd /tank/dev-worktrees/cyrus-r2 && cat >> test/cyrus-inventory.test.ts <<'EOF'

describe("real javac output (test/fixtures/cyrus-r2, built on node-2 with JDK 21 --release 21)", () => {
  const read = (f: string) => readFileSync(path.join(__dirname, "fixtures/cyrus-r2", f));
  it("reads descriptors and the bytecode summary of real compiled plugins", async () => {
    const a = inspectJar("TfClashA-1.0.0.jar", "plugins/TfClashA-1.0.0.jar", read("TfClashA-1.0.0.jar"));
    assert.equal(a.descriptor?.name, "TfClashA");
    assert.deepEqual(a.descriptor?.commands.map((c) => [c.name, c.permission, c.description]), [["nxclash", "nxclash.use", "TfClashA command"]]);
    assert.deepEqual(a.descriptor?.permissions.map((p) => [p.name, p.default]), [["nxclash.use", "true"]]);
    const b = a.bytecode!;
    assert.equal(b.javaRelease, 21);
    assert.equal(b.classesFailed, 0);
    assert.deepEqual(b.events.map((e) => [e.event, e.priority, e.mutates, e.cancels]), [["org.bukkit.event.player.PlayerJoinEvent", "HIGH", true, false]]);
    const p = inspectJar("TfPairA-1.0.0.jar", "plugins/TfPairA-1.0.0.jar", read("TfPairA-1.0.0.jar")).bytecode!;
    assert.deepEqual(p.events.map((e) => [e.priority, e.mutates]), [["NORMAL", false]]);
  });
  it("the clash pair gives exactly the statically expected findings; the clean pair none", async () => {
    const { detectConflicts } = await import("../lib/cyrus/conflicts/engine");
    const { candidateJar } = await import("../lib/cyrus/conflicts/normalize");
    const run = (x: string, y: string) => detectConflicts([candidateJar(x, read(x)), candidateJar(y, read(y))], { mcVersion: "1.21.11" });
    assert.deepEqual(run("TfPairA-1.0.0.jar", "TfPairB-1.0.0.jar").findings, []);
    assert.deepEqual(run("TfClashA-1.0.0.jar", "TfClashB-1.0.0.jar").findings.map((f) => `${f.severity} ${f.class} ${f.subject}`), [
      "warn command.label_collision /nxclash", "warn event.overlap org.bukkit.event.player.PlayerJoinEvent@HIGH", "warn permission.default_mismatch nxclash.use", "warn permission.duplicate nxclash.use", "warn resource.single_owner join_quit_messages",
    ]);
  });
});
EOF
